window.POEM_DB=window.POEM_DB||{};POEM_DB["song_010"]={"n":"张耒","dyn":"宋","poems":[{"t":"登悬瓠城感吴李事","f":"七言律诗","c":["将军戈甲从天下，丞相旌旗匝地来。","堪笑怒螳犹强臂，不知蛰户欲惊雷。","咄嗟武相深冤洗，指顾山东逆境开。","吏部声名千古在，段碑何处卧苍苔。"]},{"t":"同应之登大宋陂","f":"五言律诗","c":["望阔真多思，凭高更损神。","山川散白日，草木共青春。","寂寂兴亡事，悠悠来往人。","素衣吴白纻，尽化洛阳尘。"]},{"t":"寒食","f":"五言古诗","c":["风云虽不定，日雨亦易乾。","残春犹凛凛，助我朝食寒。","想见芳野田，士女游班班。","去者日以疏，更为来者欢。","青红间车马，日暮醉墦间。"]},{"t":"和晁应之大暑书事","f":"七言律诗","c":["蓬门久闭谢来车，畏暑尤便小阁虚。","青引嫩苔留鸟篆，绿垂残叶带虫书。","寒泉出井功何有，白羽邀凉计已疏。","忍待西风一萧瑟，碧鲈斫鲙意何如。"]},{"t":"七月六日二首 其二","f":"七言绝句","c":["积雨空阶生绿衣，幽幽点点弄秋姿。","黄昏楼角看新月，还是去年牛女时。"]},{"t":"七月六日二首 其二","f":"七言绝句","c":["山川摇落雁南飞，想见横汾鼓吹时。","得意刘郎犹叹老，萧条宋玉故应悲。"]},{"t":"七月六日二首 其一","f":"七言绝句","c":["雨洗秋城碧玉天，暮云吹尽月娟娟。","寂寥谁是清宵伴，只有姮娥最可怜。"]},{"t":"七月六日二首 其一","f":"七言绝句","c":["月落暗虫啼不休，五更白露晓悠悠。","西风是处将摇落，可但梧桐独报秋。"]},{"t":"九日登高","f":"七言绝句","c":["黄梨丹柿已催寒，一月西风积雨乾。","绀滑秋天称行草，却凭秋雁作挥翰。"]},{"t":"九月十日菊花烂开","f":"七言绝句","c":["萧条秋圃风飞叶，却有黄花照眼明。","已过重阳慵采撷，自嫌亦作世人情。"]},{"t":"二十八日","f":"七言绝句","c":["忆昨秋风吹马蹄，瓦关分袂涕交挥。","淮阳春物应如锦，犹在柯山送雁归。"]},{"t":"二月二十一日东园桃李未开有感二首 其二","f":"七言绝句","c":["寄语玄都观里花，饶君繁丽夺朝霞。","刘郎想到长安日，葵麦风前一叹嗟。"]},{"t":"二月二十一日东园桃李未开有感二首 其一","f":"七言绝句","c":["日惨东风正怒号，小园寂寂闭蓬蒿。","可能春色如人事，独发玄都观里桃。"]},{"t":"二月二日挑菜节大雨不能出","f":"七言绝句","c":["久将菘芥芼南羹，佳节泥深人未行。","想见故园蔬甲好，一畦春水辘轳声。"]},{"t":"二月五日折梅时经雨梅谢矣","f":"七言绝句","c":["江云霮䨴未全开，东岭微芒日色来。","独犯轻寒踏春晓，殷勤更折雨中梅。"]},{"t":"二绝句 其一","f":"七言绝句","c":["衙斋无事雨初晴，山泽有容春向深。","何物东风吹不散，祇应多病谪官心。"]},{"t":"二绝句 其二","f":"七言绝句","c":["茅檐斜日晓鸡号，水满陂塘荠麦高。","回首故园空怅望，东门归路绿迢迢。"]},{"t":"二绝句 其一","f":"七言绝句","c":["幽窗老客寒无睡，长听城楼晓角悲。","万里沧溟初浴日，暗鸡先向草间知。"]},{"t":"二绝句 其二","f":"七言绝句","c":["岁阴惨澹不可出，竹榻地炉聊自安。","黄叶满山篱落晚，北风吹雨湿荒寒。"]},{"t":"十八日","f":"七言绝句","c":["寒食清明人意閒，春城士女出班班。","柳黄花白楼台外，紫翠江南数叠山。"]},{"t":"三乡道中遇雨","f":"七言绝句","c":["萧萧古道西风雨，惨惨黄昏匹马行。","未遇功名莫嗟叹，逢时更自忆平生。"]},{"t":"上元三绝 其三","f":"七言绝句","c":["江边灯火似秋萤，哀怨山歌不可听。","自怪今春牢落甚，禅房止酒读黄庭。"]},{"t":"上元三绝 其二","f":"七言绝句","c":["沽酒垆边人若市，算商亭下浪连天。","张君官况今如此，岂有工夫作醉眠。"]},{"t":"上元都下二首 其二","f":"七言绝句","c":["骄马金鞭白面郎，双鬟小女坐车箱。","轮声辘辘归何处，留得红笼绛蜡香。"]},{"t":"上元都下二首 其一","f":"七言绝句","c":["淡薄晴云放月华，晚妆新晕脸边霞。","管弦楼上争沽酒，巧笑车头旋买花。"]},{"t":"下直","f":"七言绝句","c":["留住长安鬓已丝，宫廊还见落梅飞。","暮云疏雨苍龙阙，不惜障泥策马归。"]},{"t":"久雨","f":"七言绝句","c":["攲檐积雨苔生瓦，陋巷人稀泥及门。","坡下牛羊来远墅，舍旁麻苘接荒村。"]},{"t":"女几山","f":"七言绝句","c":["不复当年端正楼，多情犹问故宫游。","山川不改繁华尽，须信人生一世浮。"]},{"t":"小雨","f":"七言绝句","c":["萧萧小雨不能收，一霎西风便似秋。","枕席夜凉灯火暗，丁丁更漏隔南楼。"]},{"t":"中秋夜酌","f":"七言绝句","c":["一片秋天碧万寻，月华初上水沈沈。","遣愁不用先愁醉，更看清光到夜深。"]},{"t":"予元祐六年六月罢著作佐郎除秘书丞是岁仲冬复除著作郎兼史院检讨复至旧局题屏","f":"五言绝句","c":["庭树应如我，相逢益老苍。","别来秋苦雨，但觉瓦松长。"]},{"t":"予向集贤殿试罢寓居京师尝游西冈钱昌武郎中之第时同会者河东柳子文与钱氏三子夏中予出京今才半年而昔所共游者或东或西有不知所之者古人所谓俯仰之间已为陈迹者欤夫求昨日之我于今日终其身而不得而况偶然相值聚而旋散者欤追记春睡诗一首乃寓钱第所为者","f":"七言绝句","c":["东风冷峭著衣寒，云影深沉美睡天。","青杏园林花尽落，晚风吹雨湿鞦韆。"]},{"t":"五更","f":"七言绝句","c":["岁事先教蟋蟀催，暮云楼阙殷轻雷。","五更庭叶惊残梦，知有清秋犯雨来。"]},{"t":"元忠学士八兄耒离京师远蒙追送许惠服丹法托故竟未惠及赋五绝句 其四","f":"七言绝句","c":["昔见将军破虎鞯，玉堂曾共扫千言。","功名老去皆蹉跌，相见谆谆劝学仙。"]},{"t":"元忠学士八兄耒离京师远蒙追送许惠服丹法托故竟未惠及赋五绝句 其三","f":"七言绝句","c":["欲盗羲和一点春，五更注想隔重云。","如何但欲独不死，分我刀圭未费君。"]},{"t":"元忠学士八兄耒离京师远蒙追送许惠服丹法托故竟未惠及赋五绝句 其五","f":"七言绝句","c":["无复颠狂似少时，逢君犹自说蛾眉。","玉堂旧事君休念，两袖啼痕又送谁。"]},{"t":"元忠学士八兄耒离京师远蒙追送许惠服丹法托故竟未惠及赋五绝句 其二","f":"七言绝句","c":["衰柳苦催空壁月，悲虫真吊短檠光。","无情少壮抛人去，只有穷愁气味长。"]},{"t":"元忠学士八兄耒离京师远蒙追送许惠服丹法托故竟未惠及赋五绝句 其一","f":"七言绝句","c":["身逐孤舟似断云，故人追送尚殷勤。","秋城夜泊西风岸，落叶悲虫独自闻。"]},{"t":"分冬","f":"七言绝句","c":["莫惊人事浮云变，且作吾侪饱饭行。","白首分冬聊自劝，江城今夜一阳生。"]},{"t":"厄台寺三首 其三","f":"七言绝句","c":["世味嗟予淡莫加，更将诗句寄烟霞。","自怜落笔无好字，不及扬州王谢家。"]},{"t":"厄台寺三首 其二","f":"七言绝句","c":["峨嵋前约已成空，风雨萧萧送暮钟。","何用忘机来问话，不如松下谒痴龙。"]},{"t":"厄台寺三首 其一","f":"七言绝句","c":["诸佛苍然照殿楹，圆光明满自然灯。","千年遗事无人问，馆后高眠久属僧。"]},{"t":"双槐","f":"七言绝句","c":["老去相看终惨淡，秋来无赖对婆娑。","任从叶逐西风去，要听庭宽夜雨多。"]},{"t":"壬午腊月下旬偶作二首 其二","f":"七言绝句","c":["风折蒹葭水结凘，燕鸿相语定归期。","淮南水阔山长处，小待燕山霰雪晞。"]},{"t":"壬午腊月下旬偶作二首 其一","f":"七言绝句","c":["啄块饥禽傍短篱，风鸢一笑起高枝。","君看草树冰霜里，即是东风欲到时。"]},{"t":"方丈小山","f":"七言绝句","c":["窗外幽轩数步宽，小山幽石对巑岏。","说知老子婆娑意，且作僧房一衲看。"]},{"t":"无题二首 其二","f":"七言绝句","c":["晚起清秋一枕凉，四檐鸣雨下淋浪。","竹笼烧药时添火，书榻焚香却闭房。"]},{"t":"无题二首 其一","f":"七言绝句","c":["风槐已疏遽如许，夜蛩虽怨可若何。","出门屐齿苔痕满，隐几书尘鼠迹多。"]},{"t":"月季","f":"七言绝句","c":["月季祇应天上物，四时荣谢色常同。","可怜摇落西风里，又放寒枝数点红。"]},{"t":"木香","f":"七言绝句","c":["紫皇宝辂张珠幰，玉女熏笼覆绣衾。","万紫千红休巧笑，人间春色在檀心。"]},{"t":"水仙花叶如金灯而加柔泽花浅黄其干如萱草秋深开至来春方已虽霜雪不衰中州未尝见一名雅蒜","f":"七言绝句","c":["宫样鹅黄绿带垂，中州未省见仙姿。","只疑湘水绡机女，来伴清秋宋玉悲。"]},{"t":"水阁二首 其二","f":"七言绝句","c":["池水亭亭如有光，晓风清露点新妆。","翠帷自障非游女，多谢经营白鹭郎。"]},{"t":"水阁二首 其一","f":"七言绝句","c":["积雨荒池水欲平，轩窗长夏有馀清。","公馀一枕沧浪梦，卧听风荷受雨声。"]},{"t":"东斋杂咏 竹","f":"七言绝句","c":["袅袅墙阴竹数竿，秋风尽日舞青鸾。","平生爱尔缘潇洒，莫作封君渭上看。"]},{"t":"东斋杂咏 老槐","f":"七言绝句","c":["雪霜未死阅年华，危叶萧萧战古槎。","袅袅秋风官舍冷，半枝斜日带啼鸦。"]},{"t":"东斋杂咏 皂荚","f":"七言绝句","c":["畿县尘埃不可论，故山乔木尚能存。","不缘去垢须青荚，自爱苍鳞百岁根。"]},{"t":"东斋杂咏 南窗","f":"七言绝句","c":["门前尘土慵驱马，堂上文书厌坐曹。","只有南窗慰人意，寒灯清夜读离骚。"]},{"t":"东斋杂咏 盆池","f":"七言绝句","c":["点点青萍秋后衰，溶溶晴日见鱼儿。","水边窥影何方客，自照行吟憔悴姿。"]},{"t":"东斋杂咏 菊","f":"七言绝句","c":["野人斋爨屏膻腥，自向阶前撷紫茎。","老去爱花心转薄，一杯蔬饭足浮生。"]},{"t":"东斋杂咏 道榻","f":"七言绝句","c":["纸阁芦帘小榻安，一裘容易却轻寒。","谁惊午枕江湖梦，风落晴窗柏子乾。"]},{"t":"东海旅夜二首 其二","f":"七言绝句","c":["兰釭背壁影微微，千里天涯客梦归。","一夜海风声不断，晓来寒叶满庭飞。"]},{"t":"东海旅夜二首 其一","f":"七言绝句","c":["无酒消忧寒未减，隔帷相对一灯愁。","虫声唤觉五更梦，风雨满庭桐叶秋。"]},{"t":"东堂四首 其四","f":"七言绝句","c":["乌衣更士能呼旦，金缕娇娘解唱歌。","天与旅人供一笑，不然奈此寂寥何。"]},{"t":"东堂四首 其三","f":"七言绝句","c":["居止年来如传舍，构堂珍重主人情。","浮生行止谁能计，苟合真须学子荆。"]},{"t":"东堂四首 其二","f":"七言绝句","c":["老翁还作小儿情，手种芭蕉为雨声。","便有微泉出堂下，一泓清彻照轩楹。"]},{"t":"东堂四首 其一","f":"七言绝句","c":["主人怜客置东堂，为致炎天十步凉。","胜事自来非力致，江南山色巧相望。"]},{"t":"乍晴二首 其二","f":"七言绝句","c":["虹长饮雨川无滴，蘋末生风沼有波。","一扫烟云不知处，夜天如水泻银河。"]},{"t":"乍晴二首 其一","f":"七言绝句","c":["洗来桐叶晚青青，积雨阑干暗菌生。","墙角半倾苔晕合，萧萧风草一蛩鸣。"]},{"t":"代嘲","f":"五言绝句","c":["过作抛人去，非真我独知。","如何立不定，却有独来时。"]},{"t":"写情二首 其一","f":"七言绝句","c":["墙外谁家桃李开，何由花下一徘徊。","先教飞絮传愁去，却遣游丝取蕊来。"]},{"t":"冬日","f":"七言绝句","c":["忽忽新冬无一旬，自怜憔悴楚江滨。","满前魑魅何曾禦，尚愧无功作逐臣。"]},{"t":"冬日怀竟陵管氏梅桥四首 其四","f":"七言绝句","c":["堂下幽芳自可人，北风一为屏埃尘。","上元簪珥玲珑玉，却曳青霞霜女裙。"]},{"t":"冬日怀竟陵管氏梅桥四首 其三","f":"七言绝句","c":["他日华陵迹已陈，嘉辰怀旧一销魂。","小园幽径谁相念，应有新梅觅故人。"]},{"t":"冬日怀竟陵管氏梅桥四首 其二","f":"七言绝句","c":["小小园林点点梅，如今绰约为谁开。","只应清夜新霜里，依旧横斜倒影来。"]},{"t":"冬日怀竟陵管氏梅桥四首 其一","f":"七言绝句","c":["旅居泽国小园林，千里相望岁暮心。","想见竟陵残雪里，新梅点雪橘垂金。"]},{"t":"冬至赠潘郎二首 其二","f":"七言绝句","c":["五更人语起江城，歌笑喧喧天欲明。","酌酒寿君但一醉，百年珍重是人情。"]},{"t":"冬至赠潘郎二首 其一","f":"七言绝句","c":["荻篱茅屋柯山下，卖饼归来也作冬。","不见长安竞时节，车如流水马如龙。"]},{"t":"出京寄无咎二首 其二","f":"七言绝句","c":["老去相看情益亲，河梁分手欲沾巾。","祇应诵得离骚赋，长作行吟去国人。"]},{"t":"出京寄无咎二首 其一","f":"七言绝句","c":["不许多闻长乐钟，打包旦遇又匆匆。","长安城里谁相识，只有周南太史公。"]},{"t":"北风","f":"七言绝句","c":["北风卷地寒侵骨，冻雪连山鸟不飞。","试问朱门馀酒肉，几人回首念无衣。"]},{"t":"发孝感","f":"七言绝句","c":["袅袅樯乌转晚空，娟娟霜月入窗栊。","岸头杨柳如怜客，犹舞萧萧五两风。"]},{"t":"发金陵折柳亭二首 其二","f":"五言绝句","c":["瞿昙昔教我，林下一宵行。","何事春江上，依依作俗情。"]},{"t":"发金陵折柳亭二首 其一","f":"五言绝句","c":["匆匆十日事，回首亦凄凉。","何处无芳草，行人休断肠。"]},{"t":"古意","f":"七言绝句","c":["楼上珠帘拂疏网，却匀愁黛对凌波。","也知新旧争多少，敢话机头织素多。"]},{"t":"古意三首 其三","f":"五言绝句","c":["橘犀如半月，何日是圆时。","如何一种味，却有两人知。"]},{"t":"古意三首 其二","f":"五言绝句","c":["金铺银屈膝，动处有人挨。","棋盘作十字，中心为子来。"]},{"t":"古意三首 其一","f":"五言绝句","c":["园中杨柳树，飞舞似含羞。","如何风静处，尽放眼中愁。"]},{"t":"四月二十三日昼睡起","f":"七言绝句","c":["幽人睡足芭蕉雨，独岸纶巾几案凉。","谁和薰风来殿阁，不知陋巷有羲皇。"]},{"t":"失性","f":"七言绝句","c":["失性摧颓君子鹤，忘羞跳掷沐猴冠。","须知六合枭鸾杂，供与閒人静处看。"]},{"t":"宁子","f":"七言绝句","c":["宁子阳愚饱谙事，贾生恸哭漫多愁。","无言天道何须问，毕竟人间春复秋。"]},{"t":"对菊花二首 其二","f":"七言绝句","c":["躬耕遇岁真吾事，牛下齐儿妇妾歌。","招饮风烟过閒日，绕篱栽菊可如何。"]},{"t":"对菊花二首 其一","f":"七言绝句","c":["官閒身世两悠悠，种竹栽花一散愁。","黄菊丛边对疏雨，一年怀抱此时秋。"]},{"t":"平生","f":"七言绝句","c":["平生壮节终难变，投老浮名信所遭。","要路争先宁遽福，从来率野屈吾曹。"]},{"t":"戊寅正月八日早寒","f":"七言绝句","c":["浓淡春云夜雨乾，寂寥庭院裌衣寒。","无人为发樽前笑，但把梅花似旧看。"]},{"t":"末伏日五更小凉","f":"七言绝句","c":["幽人短梦不终宵，起步星河望泬寥。","缺月低檐鸡一唱，露华秋色满芭蕉。"]},{"t":"正月二十五日以小疾在告作三绝是日苦寒 其二","f":"七言绝句","c":["春色三分有尚多，且饶芳草占高坡。","门前柳色如彭泽，争奈陶君止酒何。"]},{"t":"正月二十五日以小疾在告作三绝是日苦寒 其三","f":"七言绝句","c":["见说樱桃已烂开，坐愁风雨苦相催。","自怜华发伤春客，两见飞花未放回。"]},{"t":"正月二十五日以小疾在告作三绝是日苦寒 其一","f":"七言绝句","c":["黄土冈头荠麦长，春阴蔽日午风狂。","山前梅落无人见，只有幽禽啼暗香。"]},{"t":"正月十八日四首 其四","f":"七言绝句","c":["山下书生业读书，荻篱葛蔓避人居。","最怜无奈穷耽酒，时遣羸童致一壶。"]},{"t":"正月十八日四首 其三","f":"七言绝句","c":["道旁兰若冷于秋，迎客开门一比丘。","夜久无人风露冷，空廊饥鼠窃膏油。"]},{"t":"正月十八日四首 其二","f":"七言绝句","c":["收灯城市接荒村，翁媪耽眠日已暾。","何事牧童能早起，缓驱白牯出柴门。"]},{"t":"正月十八日四首 其一","f":"七言绝句","c":["幽人睡足闻春鸟，共喜晖晖日满篱。","里巷收灯人寂寞，邻家夫妇赁舂归。"]},{"t":"永宁赴晁应之见招赏花途中遇雨","f":"七言绝句","c":["行云浓淡日无辉，轻雨飘飘点客衣。","马上漫郎醒复醉，一杯容易送春归。"]},{"t":"生日赠潘郎","f":"七言绝句","c":["春雨萧萧江上城，论花与子酒同倾。","恨君未到淮阳市，一见姚黄慰此生。"]},{"t":"田家二首 其一","f":"七言绝句","c":["门外清流系野船，白杨红槿短篱边。","旱蝗千里秋田净，野秫萧萧八月天。"]},{"t":"立春三首 其三","f":"七言绝句","c":["苍龙阙角回金斗，文德门南散晓班。","车马纷纷残雪里，镂银剪綵舞新幡。"]},{"t":"立春三首 其二","f":"七言绝句","c":["风光先著竹间梅，和气应从九地回。","桃李满园浑未觉，微红先向宝刀开。"]},{"t":"立春三首 其一","f":"七言绝句","c":["天上春来谁报人，江山气象一时新。","懒将白首簪幡胜，寿酒三杯慰逐臣。"]},{"t":"立秋二首 其二","f":"七言绝句","c":["对酒聊同楚人醉，哦诗惟听越吟声。","洞庭北岸孤城下，落月西风听晓莺。"]},{"t":"立秋二首 其一","f":"七言绝句","c":["西风袅袅木飕飕，身在江湖北岸州。","自古楚人词最好，为君重赋竟陵秋。"]},{"t":"伤春","f":"七言绝句","c":["浮云冉冉送春华，怯见春寒日欲斜。","一夜雨声能几许，晓来落尽一城花。"]},{"t":"伤春四首 其四","f":"七言绝句","c":["高楼春昼独惊心，白日閒云亦自阴。","风雨催花花已尽，满城新绿乱鸣禽。"]},{"t":"伤春四首 其三","f":"七言绝句","c":["嫩紫妖红惜不得，乱随风雨点蓬蒿。","荒田野草花开晚，主管春光输尔曹。"]},{"t":"伤春四首 其二","f":"七言绝句","c":["红杏墙头最可怜，腻红娇粉两娟娟。","晓来并逐东风尽，容易分飞又一年。"]},{"t":"伤春四首 其一","f":"七言绝句","c":["晓雨催春不惜花，乱红飘泊委泥沙。","伤心忆得年时事，白发风前只叹嗟。"]},{"t":"再谢周颙之句","f":"七言绝句","c":["烟飞小玉吴王国，柳暗朱楼铁瓮城。","见说周颙经案外，亦闻荀粲并床声。"]},{"t":"同仲达雪后踰小山游蔡氏园得红梅数枝奇绝因赋二首 其二","f":"七言绝句","c":["北风凛凛留高树，融雪涓涓聚小塘。","三亩山园半春草，无人为结小丁香。"]},{"t":"同仲达雪后踰小山游蔡氏园得红梅数枝奇绝因赋二首 其一","f":"七言绝句","c":["与君陟巘踏春泥，邂逅红梅得一枝。","失却孤山风露格，却成卯酒醉冰肌。"]},{"t":"戏作雪狮绝句","f":"七言绝句","c":["六出装来百兽王，日头出后便郎当。","争眉霍眼人谁怕，想你应无熟肺肠。"]},{"t":"戏呈希古","f":"七言绝句","c":["半世辛勤守黄卷，白头容易过青春。","枕前亦觉春晴否，试问东邻晚起人。"]},{"t":"成帝","f":"七言绝句","c":["百华衣上渍馀香，夜照犹烦蚌有光。","解道温柔胜武帝，不知壮发似元皇。"]},{"t":"早起二首 其二","f":"七言绝句","c":["风鸣槁叶未辞枝，雨湿疏梅欲弄姿。","地下一阳应蹀躞，世间浑未有人知。"]},{"t":"早起二首 其一","f":"七言绝句","c":["沧江初夜雨翻盆，将晓风声战乱云。","篱下寒鸡鸣晓苦，老人先起自开门。"]},{"t":"有所叹","f":"七言绝句","c":["骈胁当车闟戟先，相君冠盖照秦川。","六雄未灭君无苦，当念杜门公子虔。"]},{"t":"有感","f":"七言绝句","c":["鬓毛已自秋来变，髀肉仍于马上消。","满眼青山不归去，强颜微禄亦何聊。"]},{"t":"有感二绝 其一","f":"七言绝句","c":["残雪微风冷透衣，柳黄梅破欲春时。","年年景物常相似，满眼相思只自知。"]},{"t":"有感二绝 其二","f":"七言绝句","c":["日暇凝云去复还，晚风不动自清寒。","可怜庭雪无人扫，斜占墙阴独未残。"]},{"t":"朱云","f":"七言绝句","c":["直言请剑斩安昌，勿谓朱游只素狂。","君看汉家文景业，张侯能以一言亡。"]},{"t":"杂诗二首 其二","f":"七言绝句","c":["病腹难禁七椀茶，小窗睡起日西斜。","贫无隙地栽桃李，日日门前自买花。"]},{"t":"杂题二首 其二","f":"七言绝句","c":["苍苍落月井梧西，睡觉幽人自卷帷。","只有林莺知梦断，晓庭人静语移时。"]},{"t":"杂题二首 其一","f":"七言绝句","c":["寒雨萧萧桐叶惊，浪浪还作夜阶声。","西风忽起幽人觉，枕簟凉时向五更。"]},{"t":"次韵子由舍人先生追读迩英绝句四首 其四","f":"七言绝句","c":["恭默谁聆金玉音，陶甄万物付无心。","君王好学真天意，忧国论思不厌深。"]},{"t":"次韵子由舍人先生追读迩英绝句四首 其三","f":"七言绝句","c":["冠佩煌煌拱北辰，道人风骨自轩轩。","茯苓松下龟鼋老，须乞灵丹一粒吞。"]},{"t":"次韵子由舍人先生追读迩英绝句四首 其二","f":"七言绝句","c":["联翩右史直西垣，旧墨螭头点未乾。","自是退之平昔事，可须惭著进贤冠。"]},{"t":"次韵子由舍人先生追读迩英绝句四首 其一","f":"七言绝句","c":["天寒书殿晓班清，气爽仙盘瑞露零。","讲罢群公佩声散，一竿宫日转槐庭。"]},{"t":"次韵王彦昭感秋三首 其三","f":"七言绝句","c":["尘埃容易点吴衣，泽国秋来信息稀。","想见淮南初木落，秋云秋水雁初飞。"]},{"t":"次韵王彦昭感秋三首 其二","f":"七言绝句","c":["年来诗酒最关身，满酌休论薄与醇。","愁见洛阳秋夜月，无情偏照不眠人。"]},{"t":"次韵王彦昭感秋三首 其一","f":"七言绝句","c":["木落风高秋雁归，初晴野水涨清伊。","东流会向淮南去，凭寄秋来无限悲。"]},{"t":"次韵智叔三首 其三","f":"七言绝句","c":["今朝一见诗人诗，不用更寻黄绢词。","深山一鹤自唱和，亦有松下童子知。"]},{"t":"次韵智叔三首 其二","f":"七言绝句","c":["公子风流更可人，仙家问讯柳湖春。","烦公瓮下一杯水，洗我胸中百斛尘。"]},{"t":"次韵智叔三首 其一","f":"七言绝句","c":["才似庖刀不待硎，思如流水更清泠。","诗坛李杜谁为将，尽扫欃枪正国刑。"]},{"t":"江上二首 其二","f":"五言绝句","c":["纷纷浑是梦，黯黯只消魂。","江上浪无限，舟中酒一樽。"]},{"t":"江上二首 其一","f":"五言绝句","c":["相别亦何事，相逢尽偶然。","愁肠贯綵笔，离梦绕朱弦。"]},{"t":"自二月末苦雨寒食前一日始晴视园中花乃殊不败","f":"七言绝句","c":["春云霮䨴弄朝晖，清峭馀寒透裌衣。","最喜园花浑似旧，十分春色一分归。"]},{"t":"自上元后閒作五首 其五","f":"七言绝句","c":["喧喧野县自笙歌，风卷高云天似波。","谁谓楼前明月好，月明多处客愁多。"]},{"t":"自上元后閒作五首 其四","f":"七言绝句","c":["灯火人家夜不收，三更明月过南楼。","风烟随处自能乐，何事客心还独愁。"]},{"t":"自上元后閒作五首 其三","f":"七言绝句","c":["面冷春霜拂瓦乾，晓风吹雨冻阑干。","柳梢黄弱梅苞破，更放东君几日寒。"]},{"t":"自上元后閒作五首 其二","f":"七言绝句","c":["东风吹雨夜侵阶，楼角长烟晓未开。","何事旧时愁意绪，一番春至一番来。"]},{"t":"自上元后閒作五首 其一","f":"七言绝句","c":["阊阖楼南粉署西，旧时种柳长应齐。","如今冷落穷山县，卧听春风百鸟啼。"]},{"t":"自遣四首 其四","f":"七言绝句","c":["浮世荣枯理易观，不劳重取朽龟钻。","直应桃李繁华日，便把荆榛寂寞看。"]},{"t":"自遣四首 其三","f":"七言绝句","c":["谁云至理宗无相，大道由来万法兼。","且以声音为佛事，晓敲清磬诵华严。"]},{"t":"自遣四首 其二","f":"七言绝句","c":["谁云造化本无情，利害乘除理甚平。","莫逐众情生愠喜，君看三四孰亏盈。"]},{"t":"自遣四首 其一","f":"七言绝句","c":["是非得失一区区，蚊蚋啾啾共一壶。","不学退之求羽翼，惟凭一梦到华胥。"]},{"t":"至后早赴馆二首 其二","f":"七言绝句","c":["城围残雪寒催晓，宫近晴云暖欲春。","谁觉风光添一线，玉壶漏水报鸡人。"]},{"t":"至后早赴馆二首 其一","f":"七言绝句","c":["红蜡妆梅冷未黏，柳条偷暖作纤纤。","高楼残白谁家雪，尽日天寒不捲帘。"]},{"t":"舟行六绝 其一","f":"七言绝句","c":["猎猎西风秋水清，野花寒草傍流生。","沙边水鹤待鱼立，石底暗蛩先夜鸣。"]},{"t":"舟行六绝 其三","f":"七言绝句","c":["落景秋云晚不开，天寒古岸野船回。","初惊波面微澜起，已觉风前细雨来。"]},{"t":"舟行六绝 其四","f":"七言绝句","c":["渡头风雨晚生寒，蓑笠渔翁坐钓船。","为问篷中有鱼否，一双新鳜出笼鲜。"]},{"t":"舟行六绝 其五","f":"七言绝句","c":["天寒野店断人行，晚系孤舟浪未平。","半夜西风惊客梦，卧听寒雨到天明。"]},{"t":"西江","f":"七言绝句","c":["拂瓦轻霜铅粉轻，东南日出竹窗明。","小楼下见西江水，日日风光无限情。"]},{"t":"西园风雨杂花谢","f":"七言绝句","c":["楚泽春残雨又风，啼莺芳草思无穷。","芜菁满地黄金烂，不及蔷薇一点红。"]},{"t":"西轩","f":"七言绝句","c":["出架蔷薇秀晚枝，雨馀屋角理蛛丝。","可怜一曲秋风地，万思千情斗入诗。"]},{"t":"西湖三首 其二","f":"七言绝句","c":["水上亭台凉气多，扣舷倚棹唱吴歌。","何人为放青莲出，剪却翻翻一万荷。"]},{"t":"西窗杂咏三首 其三","f":"七言绝句","c":["稻畦新插绿云齐，雨过沟塍水接溪。","到舍妻儿劳勤苦，白醪缸畔醉如泥。"]},{"t":"观苏仲南诗卷","f":"七言绝句","c":["苏子诗如刃发硎，十章入耳韵泠泠。","文章三昧无多子，祇守君家旧典刑。"]},{"t":"观鱼亭呈陈公度二首 其二","f":"七言绝句","c":["猎猎微风波面开，近人鸥鹭不相猜。","樽前忽起扁舟兴，新管江南山水来。"]},{"t":"观鱼亭呈陈公度二首 其一","f":"七言绝句","c":["千古濠梁庄惠词，不须反覆辨真知。","直应人意逍遥处，便是游鱼自乐时。"]},{"t":"观音泉","f":"七言绝句","c":["岩松偃盖不知年，寂寂秋灯宝供前。","清彻一源传万古，空山长伴白衣仙。"]},{"t":"许同尘示张八侍郎避暑览馆中旧题绝句俾之同作次韵","f":"七言绝句","c":["聚散人生集渚鸿，飞鸣邂逅一宵同。","是非荣辱何劳问，共在邯郸一枕中。"]},{"t":"过涟水","f":"七言绝句","c":["城头落日在旗竿，城外长淮水浸天。","左海门前灯火尽，橹声呕轧夜深船。"]},{"t":"过蕲泽","f":"七言绝句","c":["雄吞六国弱秦强，壮士逡巡野水傍。","耕叟不知鸿鹄志，笑观宫室忤陈王。"]},{"t":"齐安春谣五绝 其四","f":"七言绝句","c":["赤壁矶前江急流，周郎功业莽悠悠。","惆怅沙边雨中树，无言供作古今愁。"]},{"t":"齐安春谣五绝 其二","f":"七言绝句","c":["莫笑江城大如斗，桃花如烧酒如油。","人生无病即为乐，莫诵离骚泽畔愁。"]},{"t":"初见嵩山","f":"七言绝句","c":["年来鞍马困尘埃，赖有青山豁我怀。","日暮北风吹雨去，数峰清瘦出云来。"]},{"t":"初夏谒告家居值风雨偶作二绝 其一","f":"七言绝句","c":["春愁已逐莺花尽，野果垂檐绿叶稠。","天上几回飞破镜，端居未折大刀头。"]},{"t":"初离山阳寄城中友人二首 其二","f":"七言绝句","c":["野岸萧萧落叶风，秋光离思两相攻。","殷勤临水挥双泪，凭寄清流却向东。"]},{"t":"初离山阳寄城中友人二首 其一","f":"七言绝句","c":["落月昏昏向水低，五更残烛一声鸡。","祇应魂梦犹东去，从此扁舟日向西。"]},{"t":"初离陈寄孙户曹兄弟","f":"七言绝句","c":["三年流落寓于陈，一命青衫淮水滨。","城北桥边长送别，扁丹今自作行人。"]},{"t":"别齐安税务窗竹二绝 其一","f":"七言绝句","c":["何独王郎与尔欢，一年惭愧碧琅玕。","葛陂一别知何处，见尽人间行路难。"]},{"t":"别齐安税务窗竹二绝 其二","f":"七言绝句","c":["随流泛梗虽无定，别渚栖鸿亦有情。","为问竹窗清夜月，从今谁解听秋声。"]},{"t":"别钱筠甫三首 其三","f":"七言绝句","c":["原头绿尽柳初芟，落月满川风满衫。","已过寺西三十里，为君回首驻征衔。"]},{"t":"别钱筠甫三首 其二","f":"七言绝句","c":["春灯欲尽晓鸡啼，残月影中征马嘶。","为语相逢不消喜，相逢终有道分离。"]},{"t":"别钱筠甫三首 其一","f":"七言绝句","c":["倦客无眠听晓钟，五更蜡烛泪消红。","城西古寺来何处，今日分携独向东。"]},{"t":"听鸣禽","f":"七言绝句","c":["流滞江边鬓已霜，又闻春鸟啅朝阳。","他时北去怀陈迹，寒竹疏梅黄土冈。"]},{"t":"吴王郊台","f":"七言绝句","c":["异时随举孝廉郎，旗盖相承据一方。","肠绕阊门祥已定，将军毕竟是吴王。"]},{"t":"吴江道中怀陆鲁望","f":"七言绝句","c":["我亦扁舟一散人，江湖为洗十年尘。","笔床茶灶经过地，风月相望亦有神。"]},{"t":"吹角","f":"七言绝句","c":["断霞归鸟隔山钟，日过西山转海空。","长恨南城催晓急，五更吹角怨秋风。"]},{"t":"呈宜君","f":"七言绝句","c":["江城风雨作朝昏，愁杀垆边卖酒人。","祇有醉时差可喜，不应醒坐过新春。"]},{"t":"宋玉","f":"七言绝句","c":["云雨朝朝峡里兴，可能无复梦中情。","巫娥若问谁为赋，敢乞君王道宋生。"]},{"t":"宋景平命赋隔窗花影","f":"七言绝句","c":["午睡帘栊春日长，半消金鸭水沉香。","隔窗花影时来去，疑有东邻觇宋郎。"]},{"t":"局中听雨","f":"七言绝句","c":["秋庭听雨断人声，凉入衣裾秋意生。","临水登山送归语，怜君解有许多情。"]},{"t":"巫臣二首 其二","f":"七言绝句","c":["咫尺山河不易知，无言莫谓即无思。","人间只见枝头茧，不悟春蚕暗理丝。"]},{"t":"巫臣二首 其一","f":"七言绝句","c":["万古风情不易禁，多言未似不言深。","楚王只听巫臣谏，不道逃吴已有心。"]},{"t":"怀陆羽井","f":"七言绝句","c":["寒泉背石老松根，禅室幽人古像存。","长恨千年无屈宋，楚招难与此遗魂。"]},{"t":"怀金陵三首 其三","f":"七言绝句","c":["曾作金陵烂漫游，北归尘土变衣裘。","芰荷声里孤舟雨，卧入江南第一州。"]},{"t":"怀金陵三首 其二","f":"七言绝句","c":["璧月琼枝不复论，秦淮半已掠荒榛。","清溪天水相澄映，便是临春阁上魂。"]},{"t":"怀金陵三首 其一","f":"七言绝句","c":["此君堂后青苍玉，别后何曾寄一声。","想见秦淮月堂下，西风吹浪拍堤平。"]},{"t":"怀竟陵莲花","f":"七言绝句","c":["景湖门外有汀洲，灼灼红莲照碧流。","公子不归时节晚，雨枝风叶卧清秋。"]},{"t":"旱池","f":"七言绝句","c":["藕梢菱蔓绿才深，日射游鱼聚岸阴。","呴沫已知为计尽，渚鸥沙鹭亦何心。"]},{"t":"李广","f":"七言绝句","c":["李广才非卫霍俦，孝文能鉴不能收。","君王未是忘征战，何待高皇万户侯。"]},{"t":"牡丹","f":"七言绝句","c":["天女奇姿云锦囊，故应听法傍禅床。","静中独有维摩觉，触鼻惟闻净戒香。"]},{"t":"苍浪","f":"七言绝句","c":["苍浪鬓发一衰翁，何事年来到骨穷。","魑魅何常居四裔，自怜放逐尚无功。"]},{"t":"苏先生诗云芒鞋青竹杖自挂百钱游何事春山里人人识故侯辄继其后","f":"五言绝句","c":["斋心礼仙圣，不是爱山游。","山中笑何等，白发故诸侯。"]},{"t":"閒步","f":"七言绝句","c":["枝上啼鸦巢欲成，晴檐向日乳鸠鸣。","可怜霜雪馀威尽，春草无名著处生。"]},{"t":"依韵和晁十七落花二首 其二","f":"七言绝句","c":["飞随风雨落随流，更有馀红亦已休。","杳杳天涯春物尽，可怜莺蝶不知愁。"]},{"t":"依韵和晁十七落花二首 其一","f":"七言绝句","c":["投老殷勤向物华，风前犹欲拾馀花。","更将梦逐残红去，遍入长安百万家。"]},{"t":"卧病昼眠秋风作恶","f":"七言绝句","c":["东堂岑寂似僧居，年老身閒不读书。","病卧空床鸡唱晓，窗前饥雀啄寒蔬。"]},{"t":"和人二首 其二","f":"七言绝句","c":["曈眬晓日漏春光，栏下萱丛尚卧霜。","认得君家门上雪，易知何事却难忘。"]},{"t":"和人二首 其一","f":"七言绝句","c":["腊残春近独消魂，残雪长安千万门。","青鸟何曾寄音信，碧云刚解报黄昏。"]},{"t":"和天启惠橘诗","f":"七言绝句","c":["十年不摘洞庭霜，喜见新苞照眼黄。","但对典刑休嗜味，虎贲犹得作中郎。"]},{"t":"和应之出城","f":"七言绝句","c":["路穿槐柳绕山斜，长夏村墟对物华。","青玉一寻披箨竹，绛缯千片剪榴花。"]},{"t":"和李二秀才","f":"七言绝句","c":["羡君年少盛游春，顾我无聊似厄陈。","东市车牛泥到领，不劳举袂障京尘。"]},{"t":"和苏适春雪八首 其八","f":"七言绝句","c":["寒窗冻坐成何事，趣唤红妆遣暖寒。","却把吟肠盛美酒，更令柔指拨清弹。"]},{"t":"和苏适春雪八首 其七","f":"七言绝句","c":["山中景物最幽奇，祇欠夫君为赋诗。","长忆东风吹女几，琼瑶交贯碧琉璃。"]},{"t":"和苏适春雪八首 其六","f":"七言绝句","c":["偏憎游骑香蹄污，最称佳人素手团。","方丈老翁容膝外，出门四顾尽漫漫。"]},{"t":"和苏适春雪八首 其五","f":"七言绝句","c":["不死松篁劳借问，未开桃李与催妆。","已饶艳女纤腰舞，偏犯贫儒百结裳。"]},{"t":"和苏适春雪八首 其四","f":"七言绝句","c":["溪上泛舟成底事，庵前夜立意如何。","争知万顷青青麦，绝胜黄河一尺波。"]},{"t":"和苏适春雪八首 其三","f":"七言绝句","c":["白帝阴兵严羽卫，汉皇老傅振须眉。","撒盐飞絮浑粗俗，尽拨尘言赋好诗。"]},{"t":"和苏适春雪八首 其二","f":"七言绝句","c":["寒阵须凭酒解围，閒官幸可典朝衣。","一杯冷落凭谁劝，却有飞花舞入帷。"]},{"t":"和苏适春雪八首 其一","f":"七言绝句","c":["春城北斗转招摇，寒御初还阵尚嚣。","一夜雪声欺布被，定知贫舍故相撩。"]},{"t":"和房日严换武诗","f":"七言绝句","c":["青衫厌著待封侯，慷慨知君定远流。","莫叹书生长龌龊，元戎曾与报更筹。"]},{"t":"和慎思与文潜无咎对榻夜话达旦","f":"七言绝句","c":["灯花昨夜已分明，更听朝檐喜鹊声。","明日朱门闭空馆，秋风骏马大梁城。"]},{"t":"和端午","f":"七言绝句","c":["竞渡深悲千载冤，忠魂一去讵能还。","国亡身殒今何有，只有离骚在世间。"]},{"t":"夜","f":"七言绝句","c":["斗柄阑珊风瑟瑟，银河错落露森森。","人声静后幽虫急，月色好时清夜深。"]},{"t":"夜坐","f":"七言绝句","c":["庭户无人秋月明，夜霜欲落气先清。","梧桐直不甘衰谢，数叶迎风尚有声。"]},{"t":"夜坐","f":"七言绝句","c":["半消炉火夜三更，欲灭青灯暗又明。","闭户无人瞑目坐，此时一念悟浮生。"]},{"t":"夜来","f":"七言绝句","c":["夜来风雨掠馀春，晏起萧条一病身。","三月长安泥浩浩，懒随车马作游人。"]},{"t":"夜间风雨有感","f":"七言绝句","c":["留滞招提未是归，卧闻秋雨响疏篱。","何当粗息飘萍恨，却诵僧窗听雨诗。"]},{"t":"夜思","f":"七言绝句","c":["万声沉寂漏丁东，金井栏干上暗空。","半夜西风人未觉，秋声先报草根虫。"]},{"t":"奉先寺","f":"七言绝句","c":["定知生不出长门，禾黍萧萧寺后村。","松柏城南万丘冢，伤心最说内人园。"]},{"t":"奉安神考御容入景灵宫小臣获睹有感二首 其二","f":"七言绝句","c":["渭上衣冠故老哀，西陵石径已莓苔。","从今仗下新歌舞，长及年年献酎来。"]},{"t":"奉安神考御容入景灵宫小臣获睹有感二首 其一","f":"七言绝句","c":["灵风依伞绣舆深，仗外犹疑警跸音。","不似寻常游幸日，楼前鼓吹却沾襟。"]},{"t":"宛丘道中","f":"七言绝句","c":["日斜沙路马翩翩，故欲迎凉不著鞭。","谁解多情似新月，伴人归去照人眠。"]},{"t":"屈原","f":"七言绝句","c":["楚国茫茫尽醉人，独醒惟有一灵均。","餔糟更遣从流俗，渔父由来亦不仁。"]},{"t":"所居有梅一株在堂东荒秽中正月二十六日已谢矣二首 其二","f":"七言绝句","c":["冷落疏枝寒草冈，欲攀先怕踏榛荒。","异时折处何堪说，临水高城倚女墙。"]},{"t":"所居有梅一株在堂东荒秽中正月二十六日已谢矣二首 其一","f":"七言绝句","c":["平生常恨逢梅少，及对江梅无好诗。","寂寞荒山少风味，直须云鬓插斜枝。"]},{"t":"昏昏","f":"七言绝句","c":["昏昏落日下墙东，历历晴云送去鸿。","岁晚苍槐甘老大，尽将黄叶付秋风。"]},{"t":"昔苏先生游庐山诗云平日怀真赏神游杳霭间如今不是梦真个有庐山辄继一首","f":"五言绝句","c":["人生孰非梦，梦里见庐山。","若了元无梦，何曾有往还。"]},{"t":"泊楚州锁外六首 其六","f":"七言绝句","c":["莫愁家住大堤边，朱阁青楼映暮川。","斜映清淮一梳月，晚妆相对斗婵娟。"]},{"t":"泊楚州锁外六首 其五","f":"七言绝句","c":["水榭疏帘秋夜凉，清歌一曲釂瑶觞。","明朝回首高城处，只有西风却断肠。"]},{"t":"泊楚州锁外六首 其四","f":"七言绝句","c":["流落相逢二十年，羞将白发对婵娟。","如何见我都依旧，添得尊前一惘然。"]},{"t":"泊楚州锁外六首 其三","f":"七言绝句","c":["襄王席上旧行云，二十年间生死分。","可惜风流一抔土，年年春草断人魂。"]},{"t":"泊楚州锁外六首 其二","f":"七言绝句","c":["便风吹舫去无情，漫遣槎牙铁锁横。","未叹客行鸥鸟远，五更吹角是高城。"]},{"t":"泊楚州锁外六首 其一","f":"七言绝句","c":["满眼荒寒春未知，芳菲欲到野梅枝。","东南近腊风烟好，美酒千钟鱼蟹肥。"]},{"t":"绀碧","f":"七言绝句","c":["绀碧遥空秋意生，深檐当午暑风清。","老翁睡起支颐坐，初听新蝉第一声。"]},{"t":"绍圣甲戌侍立集英殿临轩试举人作此两绝 其一","f":"七言绝句","c":["春来小殿雪初残，晓日曈眬未破寒。","黄伞当轩公事退，君王缓步侍臣阑。"]},{"t":"绍圣甲戌侍立集英殿临轩试举人作此两绝 其二","f":"七言绝句","c":["弱岁干名翰墨场，春寒摇笔试西厢。","茫然二十年间事，还著春衣侍玉皇。"]},{"t":"范增","f":"七言绝句","c":["君王不解据南阳，亚父徒誇计策长。","毕竟亡秦安用楚，区区犹劝立怀王。"]},{"t":"试笔","f":"七言绝句","c":["学馆齑盐惊岁晚，寒窗书史伴身閒。","年来轗轲甘言命，老去追随厌强颜。"]},{"t":"试墨","f":"七言绝句","c":["金案冰窗净绝尘，砚寒龙尾縠生纹。","澄江清浅汀洲静，忽有苍螭下吐云。"]},{"t":"贫病投劾乞补外官亲友问者以诗答之","f":"七言绝句","c":["卑如扬子官执戟，贫似玉川居洛阳。","不敢弯弓轻妄射，争如覆被逐山郎。"]},{"t":"采石阻雨寄宣城故人二首 其二","f":"七言绝句","c":["閒云浓淡作朝阴，柳色江头春已深。","谁为宣城故人说，依依祇似去年心。"]},{"t":"采石阻雨寄宣城故人二首 其一","f":"七言绝句","c":["风雨江头思故人，东南烟水湿青春。","宛溪东岸垂杨树，想见烟眉亦解颦。"]},{"t":"雨中题壁","f":"七言绝句","c":["去年此日泊瓜州，衰柳萧萧系客舟。","白发天涯叹流落，今年对雨古宣州。"]},{"t":"雨后游朱园","f":"七言绝句","c":["绿叶阴阴护翠枝，晚花虽小亦应稀。","东风不惜残桃李，吹作春愁处处飞。"]},{"t":"雨歇二首 其二","f":"七言绝句","c":["家童取酒冲泥至，酒满山瓶重莫携。","老子欣然一笑起，开尝洗盏对山妻。"]},{"t":"雨歇二首 其一","f":"七言绝句","c":["雨歇山园竹引芽，老禅睡起日初斜。","今朝却忆香严老，解点沩山一椀茶。"]},{"t":"青桐道中值雨凡数里舟行久之颇有江湖之思二首 其二","f":"七言绝句","c":["冥冥烟外鸟飞归，野老得鱼收网回。","隔浦断霞沉欲尽，半弯新月出云来。"]},{"t":"青桐道中值雨凡数里舟行久之颇有江湖之思二首 其一","f":"七言绝句","c":["系马操舟问楫师，却疑淮口挂帆时。","人间迁改何须问，便作江湖未可知。"]},{"t":"鱼虾","f":"七言绝句","c":["一尺盆池数种荷，鱼虾亦解起风波。","尔来未识天池乐，更有鲸鹏奈尔何。"]},{"t":"鱼虾相望","f":"七言绝句","c":["悲欢回首两茫然，忆别龙门又半年。","应是旧时歌舞处，和风开冻一层天。"]},{"t":"临淮道中","f":"七言绝句","c":["凛凛春寒犯客裘，轻阴残雪放孤舟。","无端惟有堤边柳，作态东风恼客愁。"]},{"t":"复答迎郭侯犊车之句","f":"七言绝句","c":["玉壶春酒射朝霞，只看纤腰不看花。","但遣舟迎桃叶女，仍须恩赐短辕车。"]},{"t":"宫人斜","f":"七言绝句","c":["青蛾皓齿作埃尘，玉匣珠衾地下身。","一曲坏墙门不锁，林花开落墓前春。"]},{"t":"宫词效王建五首 其五","f":"七言绝句","c":["莲烛千枝夜宴迟，君王索笔写新诗。","宫人和得争先进，偏爱宋家兄弟词。"]},{"t":"宫词效王建五首 其四","f":"七言绝句","c":["玉墀夜色昼昏昏，催放朝班散侍臣。","随驾上楼同看雪，万重宫殿一时新。"]},{"t":"宫词效王建五首 其三","f":"七言绝句","c":["昨夜新霜满玉阶，初冬处处火炉开。","中官逐院传宣赐，南国诸侯进橘来。"]},{"t":"宫词效王建五首 其二","f":"七言绝句","c":["帘外微明烛下妆，殿门放钥待君王。","玉阶地冷罗鞋薄，众里偷身倚御床。"]},{"t":"宫词效王建五首 其一","f":"七言绝句","c":["夜来霜重著栏干，玉殿无尘玉甃寒。","日日君王罢朝早，禁廷无事一冬閒。"]},{"t":"将之天长题新亭壁二首 其二","f":"七言绝句","c":["云捲山光到眼前，满川摇落早秋天。","客来系马成何事，风雨寒窗一觉眠。"]},{"t":"将之天长题新亭壁二首 其一","f":"七言绝句","c":["新亭登眺解征鞍，飞鸟悠扬云意閒。","谁谓尘埃无野兴，故乘风雨看秋山。"]},{"t":"挂剑台","f":"七言绝句","c":["上国归来岁月深，悲嗟脱剑挂高林。","欲知不负徐君意，便是当年让国心。"]},{"t":"春","f":"七言绝句","c":["磔牛门外色初分，共喜钗头彩胜新。","花萼怯寒犹积雪，鸟声催报已知春。"]},{"t":"春日书事","f":"五言绝句","c":["禅宫门寂寂，庭草无行迹。","东风自扫阶，疑是开帘客。"]},{"t":"春日书事","f":"七言绝句","c":["虫飞丝堕两悠飏，人意迟迟日共长。","春草满庭门寂寂，数棂窗日挂空堂。"]},{"t":"春日怀临汝园","f":"七言绝句","c":["西江逆上通清汝，凭仗双鱼致我词。","若向池边见鸿雁，为言春至苦相思。"]},{"t":"春日怀淮阳六首 其六","f":"七言绝句","c":["城中万枝木芍药，姚黄一萼得春多。","日日踏春浑坐此，人间无醉奈渠何。"]},{"t":"春日怀淮阳六首 其五","f":"七言绝句","c":["莽莽郊原带古丘，渐渐陇麦散羊牛。","杏花杨柳春浓处，一片青帘慰客愁。"]},{"t":"春日怀淮阳六首 其四","f":"词","c":["黄巢寨南琵琶沟，古原芳草静春流。","大艑舸?何处客，樯竿西北是神州。"]},{"t":"春日怀淮阳六首 其三","f":"七言绝句","c":["最爱南城汲井园，春来蔬甲不胜繁。","人家断处无鸡犬，迟日东风似古原。"]},{"t":"春日怀淮阳六首 其二","f":"七言绝句","c":["灵通禅刹古丛林，永日惟闻钟梵音。","阅世兴亡千室佛，百年风雨古墙金。"]},{"t":"春日怀淮阳六首 其一","f":"七言绝句","c":["西城门外古壕清，太昊祠前春草生。","早晚粗酬身计了，长为閒客此间行。"]},{"t":"春日偶题四首 其四","f":"七言绝句","c":["白首伤春一老翁，预愁寒食过春中。","下帘数点黄昏雨，一霎轻寒青杏风。"]},{"t":"春日偶题四首 其三","f":"七言绝句","c":["舍北小桃才及肩，可怜枝弱苦花繁。","黄昏雨急东风恶，惜尔不禁春夜寒。"]},{"t":"春日偶题四首 其二","f":"七言绝句","c":["隔屋桃花暖斗妆，好风时有过墙香。","满园芳草无人种，何事春来特地长。"]},{"t":"春日偶题四首 其一","f":"七言绝句","c":["漫漫东风百草长，夭桃如笑柳如妆。","惟凭酒作青春敌，收拾风光入醉乡。"]},{"t":"春阴","f":"七言绝句","c":["惊鸿瞥过不容攀，病眼淮边楚望寒。","独卧孤舟对杨柳，春风终日在樯竿。"]},{"t":"春词二首 其二","f":"七言绝句","c":["霭霭芳园谁氏家，朱门横锁夕阳斜。","鸠鸣鹊噪閒庭馆，尽日春风吹百花。"]},{"t":"春词二首 其一","f":"七言绝句","c":["残红新绿间鞦韆，寒食园林人意阑。","一阵春寒花上起，画廊连夜雨珊珊。"]},{"t":"春雨中偶成四首 其四","f":"七言绝句","c":["春阴只与睡相宜，卧听鸣禽语复飞。","一缕断香浮不散，何人深院昼熏衣。"]},{"t":"春雨中偶成四首 其三","f":"七言绝句","c":["天低芳草接浮云，万柳含烟翠不分。","燕子归时花遍落，暮云和雨入黄昏。"]},{"t":"春雨中偶成四首 其二","f":"七言绝句","c":["槐叶青青染不如，护巢鸦语有新雏。","萧萧晚雨窗鸣急，卧稳藜床玉枕书。"]},{"t":"春雨中偶成四首 其一","f":"七言绝句","c":["廉纤小雨作春愁，吹湿长云漫不收。","架上酴醾浑著叶，眼明新见小花头。"]},{"t":"春宫","f":"七言绝句","c":["团金袍袖群长靴，寒食宸游乐事奢。","风摆珠帘红幕润，满宫春雨落梨花。"]},{"t":"春蔬","f":"七言绝句","c":["新春书剑滞江城，又见南蔬入旅羹。","关心太昊祠前路，小甲连畦带雪晴。"]},{"t":"昼卧口占二首 其二","f":"五言绝句","c":["扰扰终何得，萧萧亦自如。","将求解牛道，要解斲轮书。"]},{"t":"昼卧口占二首 其一","f":"五言绝句","c":["人事日益远，秋居何飒然。","苔随墙半雨，叶放树中天。"]},{"t":"昼卧口占三首 其三","f":"七言绝句","c":["学道穷年要有得，强颜干世欲何求。","病栽薏苡无劳谤，湿要鞠藭不待搜。"]},{"t":"昼卧口占三首 其二","f":"七言绝句","c":["甘风远集闻朝嘒，怨月深栖有夜鸣。","凉牖疏明稀老翠，雨畦幽独立新清。"]},{"t":"昼卧口占三首 其一","f":"七言绝句","c":["康济朝饥进汤饼，谁何午睡属新茶。","读书隐几聊复尔，谢客扃门岂不佳。"]},{"t":"柯山杂诗四首 其四","f":"七言绝句","c":["九月江城霜气清，旅人寒事略经营。","隔窗便是山前树，永夜叶声如雨声。"]},{"t":"柯山杂诗四首 其三","f":"七言绝句","c":["断涧横桥卧古槎，晚鸡鸣处有人家。","山头月出疏钟断，江上风高落雁斜。"]},{"t":"柯山杂诗四首 其二","f":"七言绝句","c":["萧萧茅屋土山前，翁媪关门去穫田。","朝日满檐鸡犬静，荻篱深处有炊烟。"]},{"t":"柯山杂诗四首 其一","f":"七言绝句","c":["幽人睡足戴纶巾，策杖开门卯酒醺。","黄叶满山乌鹊嗓，江城秋日少行人。"]},{"t":"柯山春望","f":"七言绝句","c":["先教一雨净江山，便放千林春意还。","何事东风吹客雁，便教无意恋汀湾。"]},{"t":"残春三绝 其一","f":"七言绝句","c":["低檐送雨晚霏微，湿透梅房白渐肥。","半捲画帘屏扇掩，朦胧春睡拥春衣。"]},{"t":"洛岸春行二首 其二","f":"七言绝句","c":["南山晴翠入波光，一派溪声绕郭长。","最爱早春沙岸暖，衮风轻浪拍鸳鸯。"]},{"t":"洛岸春行二首 其一","f":"七言绝句","c":["溪上映人杨柳黄，满溪流水碧泱泱。","凭君莫向溪南望，春草春风能断肠。"]},{"t":"看花","f":"七言绝句","c":["风暖日高花气动，鸣鸠乳燕自求群。","经营美景还诗匠，倾扫顽愁赖酒军。"]},{"t":"秋日二首 其一","f":"七言绝句","c":["一庭秋色清如水，篱落萧条日脚残。","忽忆淮阳旧庭院，出邻高叶翠梧寒。"]},{"t":"秋日二首 其二","f":"七言绝句","c":["黄帘朱户狭洞房，何事易知独难忘。","相思故人云间月，凉夜皎皎出东厢。"]},{"t":"秋日即事三首 其三","f":"七言绝句","c":["萧萧衰草傍墙生，中有寒虫白日鸣。","秋物荒凉禾稼熟，悠悠驱马水边行。"]},{"t":"秋日即事三首 其二","f":"七言绝句","c":["萧条岁晚搔双鬓，流落天涯念旧游。","惟有醉来心暂展，无钱沽酒合长愁。"]},{"t":"秋日即事三首 其一","f":"七言绝句","c":["支离卧病不知秋，暑退初惊大火流。","蟋蟀知时鸣近壁，银河照夜直当楼。"]},{"t":"秋末圭窦斋前菊盛开赋得绝句时秬出未归","f":"七言绝句","c":["幽斋谁与破穷愁，蜀锦当轩烂不收。","白帝属车千万乘，玉轮金毂照清秋。"]},{"t":"秋夜","f":"七言绝句","c":["微云淡月夜朦胧，幽草虫鸣树影中。","不待南城吹鼓角，桐声长报五更风。"]},{"t":"秋夜寄远","f":"七言绝句","c":["秋晚萧条风露清，星河耿耿漏丁丁。","祇应新月频相见，长向玉楼东畔生。"]},{"t":"秋雨二首 其二","f":"七言绝句","c":["离披衰柳已无蝉，黄叶闭门风雨天。","陶令无钱难得醉，竹窗过午枕书眠。"]},{"t":"秋雨二首 其一","f":"七言绝句","c":["南山云起满庭阴，帘幕初凉七月深。","桃子压枝桐叶老，连绵风雨作愁霖。"]},{"t":"秋思","f":"七言绝句","c":["故人陈迹生蛛网，古殿苔深叠绿缯。","檐雨晚秋鸣槁叶，窗风深夜触孤灯。"]},{"t":"秋蚊","f":"七言绝句","c":["江城落木已穷秋，病客初寒欲袭裘。","暗室飞蚊犹扑面，不知天上火西流。"]},{"t":"秋晚","f":"七言绝句","c":["日转秋庭树影斜，风来粉蝶胜悲笳。","祇应宋玉秋来梦，常在墙东阿子家。"]},{"t":"秋移宛丘牡丹植圭窦斋前作二绝示秬秸和 其二","f":"七言绝句","c":["千里相逢如故人，故栽庭下要相亲。","明年一笑东风里，山杏江桃不当春。"]},{"t":"绝句","f":"七言绝句","c":["伏暑新除风露清，五更山舍一鸡鸣。","幽人枕上朦胧睡，卧看东冈次第明。"]},{"t":"绝句","f":"五言绝句","c":["雨麦浑漫垄，风梅已退妆。","高鸿望燕塞，飞疾不成行。"]},{"t":"绝句九首 其九","f":"七言绝句","c":["岁弊寒骄风落山，卧听园木怒涛翻。","去年慈德门东雪，永夜宫廊喝探喧。"]},{"t":"绝句九首 其八","f":"七言绝句","c":["黄叶桑林赤土冈，蓬茅小径度牛羊。","似闻流乞之唐汝，叹息何人为发仓。"]},{"t":"绝句九首 其七","f":"七言绝句","c":["读书老眼苦眵昏，茗饮无端遣梦魂。","到处相逢真可喜，祇应酒是好知闻。"]},{"t":"绝句九首 其六","f":"七言绝句","c":["老去不禁茶力悍，两瓯破尽五更眠。","月团三百真魔物，欲乞当垆当酒钱。"]},{"t":"绝句九首 其五","f":"七言绝句","c":["空山风雨冷蓬茅，晨起幽人理缊袍。","深闭衡门且无出，湿云如墨怒江号。"]},{"t":"绝句九首 其四","f":"七言绝句","c":["千林黄叶总飞霜，寂历疏梅未肯妆。","谁信轮囷卧山木，心知九地有微阳。"]},{"t":"绝句九首 其三","f":"七言绝句","c":["晓起山鸦噪作团，西园霜木倚空寒。","风高断雁呼前伴，雨止归云赴旧山。"]},{"t":"绝句九首 其二","f":"七言绝句","c":["树头三唱鸡宾日，门外斜行雁寄书。","十月江城霜霰薄，满山林叶乱蓝朱。"]},{"t":"绝句九首 其一","f":"七言绝句","c":["天高列岫出林外，霜落大江流地中。","晚日桥边数归牧，牛羊部分听儿童。"]},{"t":"绝句二首 其一","f":"七言绝句","c":["风掉浮烟匝地回，雨将浓翠扑山来。","晚凉楼角三吹罢，夕照江天万里开。"]},{"t":"绝句二首 其二","f":"七言绝句","c":["荒山岑寂晚鸡号，独闭衡门守一瓢。","风雨似秋君莫怪，容愁逢处易萧条。"]},{"t":"绝句二首 其二","f":"七言绝句","c":["门前山树插云青，雨足山前稻水平。","桑柘半空蚕事了，绿阴深处啭残莺。"]},{"t":"绝句二首 其一","f":"七言绝句","c":["翠润园林草木长，春归积雨满芳塘。","更无一点殷红色，叶底青梅已可尝。"]},{"t":"绝句三首 其三","f":"七言绝句","c":["淮上春风万鼓鼙，落帆舟泊岸边矶。","喧喧野市残阳里，沽酒携鱼客散归。"]},{"t":"绝句三首 其一","f":"七言绝句","c":["蔼蔼晴郊花气浮，午窗正睡拥驼裘。","觉来鸟雀茅檐静，屋角春风怒未休。"]},{"t":"绝句三首 其二","f":"七言绝句","c":["照水轻明杨柳芽，隔林相映占巢鸦。","东风香草城边路，到处人家尽是花。"]},{"t":"荆轲","f":"七言绝句","c":["燕丹计尽问田生，易水悲歌壮士行。","嗟尔有心虽苦拙，区区两死一无成。"]},{"t":"荒园","f":"七言绝句","c":["日暖风檐翻乳燕，晓寒露柳啭流莺。","荒园日日东风里，吹尽閒花香草生。"]},{"t":"赴官咸平蔡河阻水泊舟宛丘皇华亭下三首 其三","f":"七言绝句","c":["夜空如鉴碧新磨，倒影疏星乱素波。","天色水光无别处，为君垂手揽银河。"]},{"t":"赴官咸平蔡河阻水泊舟宛丘皇华亭下三首 其二","f":"七言绝句","c":["袅袅悲蝉古柳风，水边幽草已鸣蛩。","长河未放羲和宿，却放斜阳更向东。"]},{"t":"赴官咸平蔡河阻水泊舟宛丘皇华亭下三首 其一","f":"七言绝句","c":["怒河凭雨正奔流，踏跕卑梁滞去舟。","淹泊我生应有定，不须归怨一污沟。"]},{"t":"赵飞燕","f":"七言绝句","c":["苦心膏沐不论赀，富贵人生各有时。","直使中流畏仙去，君王何啻似婴儿。"]},{"t":"赵弟","f":"七言绝句","c":["男儿何用立奇勋，赵弟从军初不闻。","但斩郁城侯万户，不须猿臂老将军。"]},{"t":"送圣民出城即事","f":"七言绝句","c":["东风堤上送行人，渐出城来渐少尘。","柳色已深花又落，客来下马独伤春。"]},{"t":"送穷","f":"七言绝句","c":["年年沥酒拜清晨，风俗新正竞逐贫。","不用为文送穷鬼，直须图事祝钱神。"]},{"t":"送周六赴濠州户曹二首 其二","f":"七言绝句","c":["从来悟道不由书，觌面相呈已有馀。","麈尾花飞终不近，濠梁古鬼解揶揄。"]},{"t":"送周六赴濠州户曹二首 其一","f":"七言绝句","c":["老颙有妇何妨道，一室萧然尚愧君。","但恐小乔来丈室，却须射虎作将军。"]},{"t":"送客愁","f":"七言绝句","c":["数星点点间微河，城上三更树影蹉。","霜落夜深风悄悄，月明无限客愁多。"]},{"t":"送春","f":"七言绝句","c":["二年江上见春归，预想重来我未回。","淹速世间谁料得，祇应相遇且衔杯。"]},{"t":"闻蛩二首 其二","f":"七言绝句","c":["二年江海转萍踪，白发苍颜换旧容。","新月窥帘风动竹，宣城今夜又闻蛩。"]},{"t":"闻蛩二首 其一","f":"七言绝句","c":["晚风庭竹已秋声，初听空阶蛩夜鸣。","流落天涯聊自得，今宵为尔感平生。"]},{"t":"闻鹎鵊","f":"七言绝句","c":["纸窗未白烛微明，鹎鵊枝头一两声。","却忆去年桃李后，淮阳旅舍听残更。"]},{"t":"项羽","f":"七言绝句","c":["沛公百万保咸阳，自古柔仁伏暴强。","慷慨悲歌君勿恨，拔山盖世故应亡。"]},{"t":"项城道中","f":"七言绝句","c":["尘壁苍茫有旧题，十年重见一伤悲。","野僧欲与论前事，自说年多不复知。"]},{"t":"夏日七首 其七","f":"七言绝句","c":["女几山前官舍清，绕堂鸣涧夜泠泠。","尘埃别后何由见，檐雨三更起坐听。"]},{"t":"夏日七首 其六","f":"七言绝句","c":["风转翻翻梧叶惊，入檐白雨打窗鸣。","应将清绝酬无睡，稳听空阶半夜声。"]},{"t":"夏日七首 其五","f":"七言绝句","c":["凉风一扫宿云轻，隐隐收雷不复惊。","试决小池疏积潦，谁教蛙吻顿无声。"]},{"t":"夏日七首 其四","f":"七言绝句","c":["千蛙鸣噪污池水，万蚁奔驰一腐虫。","得丧世间能几许，冥冥高处有飞鸿。"]},{"t":"夏日七首 其三","f":"七言绝句","c":["蕲簟纱厨与夏宜，法曹腰腹大何为。","重云到地翻盆雨，却是幽人稳睡时。"]},{"t":"夏日七首 其二","f":"七言绝句","c":["野水弯环夏木森，清蝉晚噪碧云深。","扁舟两桨谁家子，万里江湖此日心。"]},{"t":"夏日七首 其一","f":"七言绝句","c":["两架酴醾侧覆檐，夏条交映渐多添。","春归花落君无恨，一架清阴恰满帘。"]},{"t":"夏日池上三首 其三","f":"七言绝句","c":["拒霜灼灼欲破红，夜来雨落荒兰丛。","空亭无人日色午，但听桐叶惊秋风。"]},{"t":"夏日池上三首 其二","f":"七言绝句","c":["落日鸣蝉夏木荒，芙蓉半落柳成行。","何人纨扇生新恨，亭馆迎秋夜夜凉。"]},{"t":"夏日池上三首 其一","f":"七言绝句","c":["新蝉上树空遗蜕，野雀哺雏争小虫。","粉沾衣袖竹枝雨，香满水亭荷叶风。"]},{"t":"徐园閒步二首 其二","f":"七言绝句","c":["动地春风晚未休，吹花折柳却成愁。","尘埃不用频车马，独卧氍毹正拥裘。"]},{"t":"徐园閒步二首 其一","f":"七言绝句","c":["平田小雨润新耕，晓日园林信脚行。","衬步野芜吹面柳，可怜春物总多情。"]},{"t":"效吴融咏情","f":"七言绝句","c":["依依漠漠复纷纷，触处相随过晓昏。","知是妄缘除不尽，更教风月助吟魂。"]},{"t":"效李商隐","f":"七言绝句","c":["夜深传警报更筹，霜桂月华寒未收。","昨夜雨昏今日朗，一番风雨一番愁。"]},{"t":"斋中列酒数壶皆齐安村醪也今旦亦强饮数杯戏成呈邠老昆仲二首 其二","f":"七言绝句","c":["放逐江边长苦饮，壶浆尚敢较醇醨。","中都光禄多新酿，不解随人得一卮。"]},{"t":"斋中列酒数壶皆齐安村醪也今旦亦强饮数杯戏成呈邠老昆仲二首 其一","f":"七言绝句","c":["曾尝玉皇碧琳腴，不醉长安市上酤。","饮湿先生今已矣，啜醨留得与门徒。"]},{"t":"晁二家有海棠去岁花开晁二呼杜卿家小娃歌舞花下痛饮今春花开复欲招客而杜已出守戏以诗调之","f":"七言绝句","c":["颇疑蜂蝶过邻家，知是东墙去岁花。","骏马无因迎小妾，鸱夷何用强随车。"]},{"t":"晏起","f":"七言绝句","c":["晚起翻书日欲西，偶然乘兴忘遨嬉。","好书自癖非求利，掘冢才须数句诗。"]},{"t":"晓发途中","f":"七言绝句","c":["坐无灯火夜萧然，马上匆匆未晓天。","值驿老兵应笑我，肯将斗粟换高眠。"]},{"t":"晓雨","f":"七言绝句","c":["绿满园林红已稀，湿烟和柳共霏微。","谁家油壁春寒里，独辗天街晓雨归。"]},{"t":"晓雨","f":"七言绝句","c":["轻阴江上千峰秀，小雨墙边百草生。","惟有春禽慰孤客，晓啼浑似故园声。"]},{"t":"株林","f":"七言绝句","c":["九寡奔亡一老姬，白头蛮叟嬖西施。","二公费尽平生事，深屋婵娟世得知。"]},{"t":"桓温","f":"七言绝句","c":["北征谈笑缚姚公，静扫诸陵见洛嵩。","不用登高笑夷甫，正缘此辈使君雄。"]},{"t":"殷浩","f":"七言绝句","c":["田野高风过有薰，庙堂经画竟无闻。","固应竹马思元子，江左兴亡不在君。"]},{"t":"病起登叠嶂楼","f":"七言绝句","c":["病来久不上层台，窗有蜘蛛径有苔。","多少山茶梅子树，未开齐待主人来。"]},{"t":"真阳县昼睡县舍素丝堂","f":"七言绝句","c":["见君堂下小荷叶，惊我客中春已空。","一觉西堂亭午睡，悠悠春梦逐春风。"]},{"t":"离京后作七首 其七","f":"七言绝句","c":["燕雀翩翻夏屋深，成溪桃李已成阴。","黄鹂深处无人见，时有清风递好音。"]},{"t":"离京后作七首 其六","f":"七言绝句","c":["高槐老柳舞南风，晴日家家蚕麦中。","芟尽黄云见原隰，却教风雨洗长空。"]},{"t":"离京后作七首 其五","f":"七言绝句","c":["过雨陂塘处处深，南风萧艾欲成林。","道边拾穗行歌者，亦有丰年一饱心。"]},{"t":"离京后作七首 其四","f":"七言绝句","c":["一水夷犹达汝阴，年华客意两相侵。","河边无限青青草，揽辔何人系此心。"]},{"t":"离京后作七首 其三","f":"七言绝句","c":["灌畦沽酒两三家，春去芳丛有晚花。","莫道长安在天上，女牛犹有客乘槎。"]},{"t":"离京后作七首 其二","f":"七言绝句","c":["水谙送客浑无浪，风解留人却有情。","今夜榆林系帆宿，却从北斗望天心。"]},{"t":"离京后作七首 其一","f":"七言绝句","c":["蘋芷江边已五年，厌闻风浪打船舷。","南风萧艾荒凉野，时望高丘一慨然。"]},{"t":"读王荆公诗","f":"七言绝句","c":["名实由来不可逃，悠悠毁誉亦徒劳。","臧公已死言终立，不是轩裳世禄高。"]},{"t":"读史二首 其二","f":"七言绝句","c":["嬴秦馀祚已蛇分，车府凶高尚畏人。","安有区区犹指鹿，从来菽麦不曾分。"]},{"t":"读史二首 其一","f":"七言绝句","c":["区区奸智终何补，不悟身犹弄伎儿。","蛇断楚郊秦未觉，鬼谋曹社梦先知。"]},{"t":"读仲南和诗","f":"七言绝句","c":["异时文席许论诗，三载江湖读楚词。","自笑酸寒无好语，少年仓氏独相知。"]},{"t":"读吴怡诗卷二首 其二","f":"七言绝句","c":["疏梅半落雪中香，想子孤吟对酒缸。","野水荒山半猿鸟，跨驴谁问贾长江。"]},{"t":"读吴怡诗卷二首 其一","f":"七言绝句","c":["罗田春动雪消初，主簿清诗雪不如。","休学风骚穷事业，花前莫负古铜壶。"]},{"t":"读周本纪","f":"七言绝句","c":["周公七百年礼乐，箕服檿弧纷破除。","空使遗臣经故国，徘徊禾黍叹丘墟。"]},{"t":"读除目有感","f":"七言绝句","c":["祸福茫茫不可猜，可能凭势即无灾。","相君西闼挥毫日，岂料方还此地来。"]},{"t":"读秦纪二首 其二","f":"七言绝句","c":["汲汲威刑继祖龙，收功终在望夷宫。","未应家国归车府，却有山东老沛公。"]},{"t":"读秦纪二首 其一","f":"七言绝句","c":["烹灭群雄力未疲，赭山射海奋馀威。","谁知传与痴儿子，祇得阿房似旧时。"]},{"t":"调全玉病二首 其二","f":"七言绝句","c":["诗将收功久戢戈，羸师再鼓奈疲何。","想君无物惊禅定，独未能除是此魔。"]},{"t":"调全玉病二首 其一","f":"七言绝句","c":["维摩丈室自萧然，病起新凉得恣眠。","我愧声闻难问疾，想君独对散花天。"]},{"t":"贾谊","f":"七言绝句","c":["贾生未免孝文疑，自古功名叹数奇。","逐得洛阳年少去，白头绛灌亦何为。"]},{"t":"酒病中寄李十二招饮五首 其二","f":"七言绝句","c":["酒病岑岑更怯寒，一窗疏雨拥衾眠。","西风一入庭前树，便有秋声到枕边。"]},{"t":"酒病中寄李十二招饮五首 其一","f":"七言绝句","c":["班郎握笔未封侯，嗜酒扬雄欲白头。","寂寞著书谁作伴，雨枝风叶碧梧秋。"]},{"t":"偃王城","f":"七言绝句","c":["蔓草悲风知几秋，黄桑晚叶野云愁。","偃王城下樵苏尽，犹有耕人指旧丘。"]},{"t":"偶成","f":"七言绝句","c":["许君踏月夜相过，此语当时恨已多。","但愿相逢休怨老，不妨白发听新歌。"]},{"t":"偶成","f":"七言绝句","c":["低云著地晓悠悠，雨湿帘旌不上钩。","江北江南千万里，年年长向此时愁。"]},{"t":"偶成二首 其二","f":"七言绝句","c":["乍晴幽步踏斜阳，残潦青苔曲径荒。","风掷落花填小堑，雨催芳草上空墙。"]},{"t":"偶成二首 其一","f":"七言绝句","c":["新引龙孙欲解苞，篱根抽笋已梢梢。","莓苔雨过蜗缘壁，杨柳叶深莺有巢。"]},{"t":"偶题二首 其二","f":"七言绝句","c":["春水长流鸟自飞，偶然相值不相知。","请君试采中塘藕，若道心空却有丝。"]},{"t":"偶题二首 其一","f":"七言绝句","c":["相逢记得画桥头，花似精神柳似柔。","莫谓无情即无语，春风传意水传愁。"]},{"t":"堂前种二桃诗示秬秸","f":"七言绝句","c":["平昔殷勤向物华，谁知憔悴客天涯。","双桃栽罢还惆怅，忆得淮阳旧种花。"]},{"t":"宿文殊院呈孙子和二绝 其一","f":"七言绝句","c":["天河初没空明星，四听鸡号人欲兴。","高林有露乍蹄马，佛屋无人到晓灯。"]},{"t":"宿文殊院呈孙子和二绝 其二","f":"七言绝句","c":["朱楼帘捲见天涯，倦客倚栏何所思。","新月无情明复落，清箫有恨歇还吹。"]},{"t":"宿卢村逆旅","f":"七言绝句","c":["夜宿村南贫主人，入门桃李已残春。","无人折赠门前柳，伫立东风独怆神。"]},{"t":"宿南山普济院","f":"七言绝句","c":["闪闪青灯照薄帷，幽人不寐自吟诗。","僧来邀我更深坐，待听山风到树枝。"]},{"t":"宿咸平驿","f":"七言绝句","c":["萧萧暗叶鸣秋雨，淅淅窗风战客灯。","世味饱谙心已老，不烦潘鬓强侵陵。"]},{"t":"宿钱睦甫南斋","f":"七言绝句","c":["潇洒南轩与病宜，庳床长簟碧纱帏。","三更月上梦初觉，竹影满窗风入衣。"]},{"t":"宿第四铺","f":"七言绝句","c":["系缆寒沙伤客情，秋云不动夜阴生。","萧萧两岸黄榆叶，解报三更雨到声。"]},{"t":"宿铜陵寺题壁","f":"七言绝句","c":["僧房秋夜月明天，下马拥裘人悄然。","老僧何事亦晨起，清磬一声惊客眠。"]},{"t":"宿慈氏院","f":"七言绝句","c":["楼上鸣钟报五更，朦胧深殿佛灯明。","更无幽梦随寒枕，听彻风松到晓声。"]},{"t":"宿潘君草堂闻蛙声二首 其二","f":"七言绝句","c":["孤村足雨菰蒲合，只有群蛙噪满陂。","我亦閒来无鼓吹，不烦通夕短长吹。"]},{"t":"宿潘君草堂闻蛙声二首 其一","f":"七言绝句","c":["跳踉鼓怒任争雄，何事鸣呼聒睡翁。","不用洒灰烦鲁老，正须两股付吴侬。"]},{"t":"寄李不危","f":"七言绝句","c":["忆昨东风吹马蹄，瓦关分袂涕交挥。","淮阳风物应如旧，独在柯山送雁归。"]},{"t":"寄陈州朱教授三首 其三","f":"七言绝句","c":["春雨江干不肯晴，大江栎岸转雷霆。","山头方丈浑无事，扫地焚香看佛经。"]},{"t":"寄陈州朱教授三首 其二","f":"七言绝句","c":["欲晓山禽百种鸣，最怜哑咤是雏莺。","遥想西湖烟柳色，深春风露水边声。"]},{"t":"寄陈州朱教授三首 其一","f":"七言绝句","c":["殷勤寄语朱夫子，僧舍花前亦举觞。","学舍萧条官职冷，不知谁与戴姚黄。"]},{"t":"寄都下旧友二首 其二","f":"七言绝句","c":["城西古地昔同游，望月思家相对愁。","明月秋来应更好，何人看月又悲秋。"]},{"t":"寄都下旧友二首 其一","f":"七言绝句","c":["一别长安西复东，琵琶旧地已应空。","当时风景归何处，须信人生是梦中。"]},{"t":"崇化寺三首 其三","f":"七言绝句","c":["零落宫墙官树秋，行人东去路悠悠。","祇应楼下邯郸路，亦有离人对此愁。"]},{"t":"崇化寺三首 其二","f":"七言绝句","c":["白发荆州叹滞淫，吴衣重杵洛城砧。","遣愁莫上高楼望，只有秋来昼日阴。"]},{"t":"崇化寺三首 其一","f":"七言绝句","c":["楼殿沉沉锁夜烟，秋灯一点佛龛前。","梧桐叶上三更雨，亦有愁人独自眠。"]},{"t":"崇宁壬午临汝四月始闻莺二首 其二","f":"七言绝句","c":["好音终在耻争先，谷外寒多故后迁。","已过花时亦何恨，不妨夏木绿参天。"]},{"t":"崇宁壬午临汝四月始闻莺二首 其一","f":"七言绝句","c":["青杏登盘樱压枝，园林初夏啭黄鹂。","一声风露高林晓，却觉年华总未衰。"]},{"t":"綵花","f":"七言绝句","c":["清寒带雪未成春，可得芳菲早向人。","须遣艳阳归掌握，故教桃李及芳辰。"]},{"t":"悼亡九首 其九","f":"七言绝句","c":["欲治烦恼更无方，只有头陀理最长。","不待存亡始知梦，故应交臂已凄凉。"]},{"t":"悼亡九首 其八","f":"七言绝句","c":["嵩阳道出建春门，同入西都四见春。","谁谓回头隔存没，断肠今作独归人。"]},{"t":"悼亡九首 其七","f":"七言绝句","c":["山僧老去久忘情，笑我多悲白发生。","为道人间具烦恼，早来林下共修行。"]},{"t":"悼亡九首 其六","f":"七言绝句","c":["亦知存没等浮云，鲜笑多悲失道真。","却恐荒唐齐物叟，鼓盆真是已伤神。"]},{"t":"悼亡九首 其五","f":"七言绝句","c":["新霜已重菊初残，半死梧桐泣井阑。","可是神伤即无泪，哭多清血也应乾。"]},{"t":"悼亡九首 其四","f":"七言绝句","c":["晓梳零乱发星星，病眼昏昏怯夜灯。","乌几素屏双草屦，百年从此学山僧。"]},{"t":"悼亡九首 其三","f":"七言绝句","c":["千行垂泪对风烟，万事伤心儿女前。","晓镜不须催白发，潘郎秋鬓久萧然。"]},{"t":"悼亡九首 其二","f":"七言绝句","c":["遥夜新霜凋碧槐，三更寒月满堂阶。","美人化作秋风去，只有清魂梦里来。"]},{"t":"悼亡九首 其一","f":"七言绝句","c":["菊花还似去年黄，一寸愁心万事伤。","独立高楼对残日，秋风吹得泪千行。"]},{"t":"晚归","f":"七言绝句","c":["学省归来门巷秋，伴眠书史满床头。","低云漠漠梧桐晚，屏上江山亦解愁。"]},{"t":"晚步灵寿寺后二首 其二","f":"七言绝句","c":["逢秋种菊尚殷勤，隙地侵寻欲过邻。","便好采花供服饵，形容已似泽边人。"]},{"t":"晚步灵寿寺后二首 其一","f":"七言绝句","c":["秋城草树欲黄昏，微径新晴菜甲新。","便好灌园从老圃，此怀原是汉阴人。"]},{"t":"晚春四首 其四","f":"七言绝句","c":["荒畦零乱满芜菁，春事收功欲老成。","鹊噪鸠鸣莫无赖，晓枝千啭有雏莺。"]},{"t":"晚春四首 其三","f":"七言绝句","c":["洗雨吹风送晚春，尽收红紫布青云。","眼前消长谙已久，清坐不妨长闭门。"]},{"t":"晚春四首 其二","f":"七言绝句","c":["蔷薇倒架笋过邻，梦泽茫茫欲晚春。","绿暗红稀君莫叹，满枝梅杏欲尝新。"]},{"t":"晚春四首 其一","f":"七言绝句","c":["杨柳藏鸦笋作竿，晓风吹雨作轻寒。","清阴一片收春去，留得蔷薇数点殷。"]},{"t":"晚春初夏八首 其八","f":"七言绝句","c":["酴醾压架不胜繁，洗雨吹风更可怜。","姑射仙人本仙骨，百花凋尽独婵娟。"]},{"t":"晚春初夏八首 其七","f":"七言绝句","c":["春归草木漫青红，半委尘埃半逐风。","谁似长楸百馀尺，高张锦绣照青空。"]},{"t":"晚春初夏八首 其六","f":"七言绝句","c":["青春已属明年事，昼漏初知夏景长。","日日南风笋成竹，残红虽有不成妆。"]},{"t":"晚春初夏八首 其五","f":"七言绝句","c":["睡足高檐春日斜，碾声初破小龙茶。","楼边绿树飞红尽，春色墙阴老荠花。"]},{"t":"晚春初夏八首 其四","f":"七言绝句","c":["古柳参天鸣啄木，青芜覆地下鸣鸠。","白头懒作留春计，睡起移时独倚楼。"]},{"t":"晚春初夏八首 其三","f":"七言绝句","c":["吹尽成蹊桃李尘，兔葵燕麦一番新。","只应解箨抽青玉，霜节棱棱尚可人。"]},{"t":"晚春初夏八首 其二","f":"七言绝句","c":["少室山前日日风，望嵩楼下水溶溶。","卷将春色归何处，尽在车前榆荚中。"]},{"t":"晚春初夏八首 其一","f":"七言绝句","c":["阴阴夏景变馀春，清晓园林未有尘。","日日东风欺弱柳，鹅黄吹尽作青云。"]},{"t":"晚莺二首 其二","f":"七言绝句","c":["青竹万叶一霜摧，何事流莺去复回。","啼鵊已摧芳草歇，春风安肯为君来。"]},{"t":"晚莺二首 其一","f":"七言绝句","c":["庭树知秋彫晚枝，春莺一去几时归。","晚来何事枝头见，哑咤数声还复飞。"]},{"t":"晨起二首 其二","f":"七言绝句","c":["中宵爽气入衾裯，檐雨浪浪晓末收。","三伏炎歊扫除尽，待教明月放清秋。"]},{"t":"梁冀","f":"七言绝句","c":["力回汉鼎未收功，又道将军世上雄。","不悟折腰同龋齿，百般装束为秦宫。"]},{"t":"梅","f":"七言绝句","c":["覆釜湖边雪压尘，数枝林外已先春。","尽将七泽清霜气，洗出姑山绰约身。"]},{"t":"梅花","f":"七言绝句","c":["我爱梅花不忍摘，清香却解逐人来。","风露肌肤随处好，不知人世有尘埃。"]},{"t":"梅花二首 其二","f":"七言绝句","c":["天质自清非为瘦，仙姿正白不施红。","未开如怨开如笑，枉乞幽香与北风。"]},{"t":"梅花二首 其一","f":"七言绝句","c":["便使柳肥终解舞，莫惊梅瘦为含酸。","因风自袅还成态，与雪争妍却要寒。"]},{"t":"梅花 其五","f":"七言绝句","c":["脉脉无言亦有期，雪中狂杀羽林儿。","可怜多少幽奇事，却是东风总不知。"]},{"t":"梅花 其四","f":"七言绝句","c":["清寒池馆静无尘，岁岁相逢似故人。","任遣墙头疑是雪，欲教园木早知春。"]},{"t":"梅花 其三","f":"七言绝句","c":["玉粟匀圆官样黄，领巾借与十分香。","冲寒不为生春物，自要晨霜为洗妆。"]},{"t":"梅花 其二","f":"七言绝句","c":["林外啼禽自往还，风前诗客倚阑干。","小园门锁黄昏月，耿耿幽姿伴岁寒。"]},{"t":"梅花 其六","f":"七言绝句","c":["三亩荒园草棘荒，可堪终夜北风狂。","瑶环瑜珥谁将去，啧啧幽禽啄蕊黄。"]},{"t":"梅花 其一","f":"七言绝句","c":["月落严霜自理妆，北风工为发清香。","晓英数点辞人去，幽独无人为断肠。"]},{"t":"梦至一园池藕花盛开水鸟飞鸣为作二小诗记之 其二","f":"七言绝句","c":["平池秋水雨来深，无数红妆出岸阴。","翠幕深藏知有意，白鸥相见本无心。"]},{"t":"梦至一园池藕花盛开水鸟飞鸣为作二小诗记之 其一","f":"七言绝句","c":["偶来乘兴不须疑，一顷秋香欲发时。","老子婆娑真为尔，百回相见愧鸬鹚。"]},{"t":"梦灵寿寺","f":"七言绝句","c":["客居有似鸿遵渚，鸿渚相看岂有情。","何事春来频见梦，老僧谈笑起相迎。"]},{"t":"梦周楚望","f":"七言绝句","c":["春风吹梦到淮南，一夕从容尽笑谈。","睡觉始知经岁别，洛阳新柳已毵毵。"]},{"t":"淮上观冰下","f":"七言绝句","c":["寒淮千里群冰下，古岸枯槎黄苇枝。","忆得天津桥下见，五门春动雪消时。"]},{"t":"淮上晓望","f":"七言绝句","c":["酒醒窗明月半川，怯将病齿漱寒泉。","楼西别有清秋色，一片淮山在晓烟。"]},{"t":"淮阴","f":"七言绝句","c":["芦梢林叶雨萧萧，独卧孤舟听楚谣。","生计飘然一搔首，西风沙上趁归潮。"]},{"t":"淮阴晚望","f":"七言绝句","c":["萧萧衰柳来时路，袅袅危樯西去船。","白鸟归飞夕阳尽，断霞风约过平川。"]},{"t":"淮阴道中","f":"七言绝句","c":["映日断霞临水尽，出云新月向人来。","野塘秋晚无行迹，点点黄花照水开。"]},{"t":"清明日舟中书事二首 其二","f":"七言绝句","c":["巢乌噪处绿杨村，寒食人家昼掩门。","麦陇晓风收宿润，烟林午日涨黄昏。"]},{"t":"清明日舟中书事二首 其一","f":"七言绝句","c":["清明不到旅人家，乞火邻船自试茶。","弄柳好风低作舞，夹船春浪细浮花。"]},{"t":"竟陵酒官舍北有数步草岁寒霜落犹郁然也予为障其风霜暮冬尚自如一日大火焚舍无遗复往寻草不复有矣","f":"七言绝句","c":["为爱墙隅芳草色，故遮霜霰待新春。","火烧雨洗寻无处，祇有东风吹旧尘。"]},{"t":"竟陵梦野亭在子城西南角一目而尽云梦之野最为郡中之胜","f":"七言绝句","c":["高甍巨桷压城闉，平视如将七泽吞。","几度春光招宋玉，碧阑干外独消魂。"]},{"t":"竟陵僦舍仍有小园景物颇佳","f":"七言绝句","c":["荒凉台阁追随事，懒慢江河放逐臣。","应是主人怜寂寞，僦居仍有小园春。"]},{"t":"章华","f":"七言绝句","c":["长恨章华亦陋夫，周秦仅可胜登徒。","谁知南楚仍穷巷，骨像何妨自应图。"]},{"t":"萧何","f":"七言绝句","c":["萧公俯仰系安危，功业君王心独知。","犹道邵平能缓颊，君臣从古固多疑。"]},{"t":"萧萧","f":"七言绝句","c":["萧萧风雨五更初，枕上秋声独井梧。","只有菊花犹灼灼，苦教摧拉就荒芜。"]},{"t":"谒蒋帝祠过钟山下二首 其二","f":"七言绝句","c":["溶溶野水戏凫鹥，垄麦初长午景迟。","尽日绿杨閒照水，临风自爱好腰支。"]},{"t":"谒蒋帝祠过钟山下二首 其一","f":"七言绝句","c":["野塘春水绿迢迢，上有东风弄柳条。","晓日已穿东岭出，轻寒犹欲战驼毛。"]},{"t":"谒僧不值","f":"七言绝句","c":["古寺人閒僧掩扉，客来下马解尘衣。","双松带月风蝉噪，古阁鸣钟夕鸟归。"]},{"t":"野步","f":"七言绝句","c":["带水依城一径微，出城桃杏雨来枝。","最怜杨柳身无力，付与春风自在吹。"]},{"t":"鹿邑道中","f":"五言绝句","c":["去岁秋时去，今年秋又来。","浮名何所得，岁月苦相催。"]},{"t":"黄州酒务税宿房北窗新种竹戏题于壁","f":"七言绝句","c":["异时小杜高眠地，几向秋风听楚江。","身世浮云那可计，试留双竹守寒窗。"]},{"t":"黄葵","f":"七言绝句","c":["黄葵贵丽不妖娆，一朵新晴槛外高。","还似迩英临便坐，曈眬朝日照天袍。"]},{"t":"喜雪走笔呈李宣城三首 其三","f":"七言绝句","c":["万夫饿腹待仓储，三户穷民守破圩。","疲瘵不禁鞭挞甚，长官对酒且欢娱。"]},{"t":"喜雪走笔呈李宣城三首 其二","f":"七言绝句","c":["聒聒庭中争曲直，纷纷笔下判鞭笞。","坐曹决事输归饮，须信薛宣称吏师。"]},{"t":"喜雪走笔呈李宣城三首 其一","f":"七言绝句","c":["殷勤寄语宣城宰，公事何时是了时。","病守欣然有嘉思，亦须对雪把空卮。"]},{"t":"寒食","f":"七言绝句","c":["庭院轻寒新雨过，江城寒食野花飞。","故园北望一千里，极目江枫客未归。"]},{"t":"寒食日作二首 其二","f":"七言绝句","c":["朝寒却觉春衣薄，禅诵还将酒盏疏。","落尽江城千树雪，门前杨柳已藏乌。"]},{"t":"寒食日作二首 其一","f":"七言绝句","c":["荒山野水非吾土，寒食清明似去年。","杨柳插门人竞笑，荆蛮不信子推贤。"]},{"t":"寒食离白沙","f":"七言绝句","c":["莫惊客路已经年，尚有青春一半妍。","试上芳堤望春野，万丝杨柳拂晴天。"]},{"t":"寒食离白沙","f":"七言绝句","c":["花枝袅袅水溶溶，杨柳轻明二月风。","景物可怜人寂寞，年年寒食醉眠中。"]},{"t":"寓寺八首 其八","f":"七言绝句","c":["笼灯到晓只微明，独拥单衾听雨声。","葛幌竹床清过暑，萧然未觉负平生。"]},{"t":"寓寺八首 其七","f":"七言绝句","c":["错落星河没半空，江城悲角五更风。","幽人梦断西窗雨，背壁笼灯到晓红。"]},{"t":"寓寺八首 其六","f":"七言绝句","c":["平晓春云失半山，濛濛小雨暗江干。","寺楼倚遍消残醉，只有春愁伴薄寒。"]},{"t":"寓寺八首 其五","f":"七言绝句","c":["翠眉长好何曾损，寄语啼禽漫不閒。","应为残春足愁恨，长疑蹙破镜中山。"]},{"t":"寓寺八首 其三","f":"七言绝句","c":["病卧淮阳太昊城，牡丹丛畔过清明。","那知春暮长江上，竹里招提听晓莺。"]},{"t":"寓寺八首 其四","f":"七言绝句","c":["江城梅子青时节，嫩紫夭红扫地无。","修竹满山连草色，却烦林鸟劝提壶。"]},{"t":"寓寺八首 其二","f":"七言绝句","c":["道人钟梵久寂寞，倦客弭车聊静便。","我亦云山閒衲子，平生香火旧因缘。"]},{"t":"寓寺八首 其一","f":"七言绝句","c":["门外清泉浸稻畦，西南脩竹作城埤。","川平林断空明处，却有遥山作翠眉。"]},{"t":"寓淮阳驿二首 其二","f":"七言绝句","c":["悠飏短日下西墙，庭叶吟风作夕凉。","客枕甚安无一事，邻鸡不用唤朝阳。"]},{"t":"寓淮阳驿二首 其一","f":"七言绝句","c":["一庭秋色高堂夜，半壁灯光短幌凉。","都是去年秋气味，谁知飘泊古淮阳。"]},{"t":"寓楚题杨补之官舍","f":"七言绝句","c":["一辞螭陛走天涯，客路悠悠老岁华。","住久不知身是客，自来堂下采黄花。"]},{"t":"朝寒","f":"七言绝句","c":["朝寒卯饮已战胜，煮饼一瓯充午饥。","便是衰翁一日了，夜炉茗果亦随宜。"]},{"t":"渡江","f":"七言绝句","c":["白发人惊老阿童，横江聊借半帆风。","却嗟缚得穷孙皓，未似高歌醉闭篷。"]},{"t":"渡沙河","f":"七言绝句","c":["溶漾澄明彻底清，鸬鹚惯客不相惊。","却疑洛水新霜后，八节滩津石柱声。"]},{"t":"游园","f":"七言绝句","c":["病来久不上层台，窗有蛛丝径有苔。","为报园花莫惆怅，故教太守及春来。"]},{"t":"湖上成绝句呈刘伯声四首 其四","f":"七言绝句","c":["谁道原头春未回，柳梢黄软冻齐开。","争惊腊日峥嵘尽，忽问田翁乞野梅。"]},{"t":"湖上成绝句呈刘伯声四首 其三","f":"七言绝句","c":["野岸北风归客愁，浮烟不动雨飕飕。","围成野色萦纡岸，点破湖光三四鸥。"]},{"t":"湖上成绝句呈刘伯声四首 其二","f":"七言绝句","c":["风荡云容不成雪，柳偷春色放冲寒。","湖边艇子冲烟去，天畔青山隔雨看。"]},{"t":"湖上成绝句呈刘伯声四首 其一","f":"七言绝句","c":["湖北风来吹晓钟，湖边渔客闭船篷。","波光不动天光阔，更在浮烟细雨中。"]},{"t":"登乘槎亭","f":"七言绝句","c":["海天秋雾暗乘槎，风响空山浪卷沙。","杳杳橹声何处客，一帆冲雨暗天涯。"]},{"t":"腊日步西园","f":"七言绝句","c":["三亩寒园春欲回，浅池低树忽飘梅。","楚乡万里霜云尽，归雁行行斜日来。"]},{"t":"腊月下旬偶作","f":"七言绝句","c":["岁暮烟霜泽国寒，晓鸦鸣处是柯山。","地炉有火樽馀酒，自起焚香深掩关。"]},{"t":"腊月殊有春意二首 其二","f":"七言绝句","c":["拂槛垂杨雪后青，谁家朱阁晓来晴。","拂帘动幕无人解，先把春愁寄有情。"]},{"t":"腊月殊有春意二首 其一","f":"七言绝句","c":["一夜长风无片云，晓来风动似初春。","应知春近催桃李，更有轻寒不著人。"]},{"t":"腊初小雪后圃梅开二首 其二","f":"七言绝句","c":["晨起千林腊雪新，数枝云梦泽南春。","一尘不染香到骨，姑射仙人风露身。"]},{"t":"腊初小雪后圃梅开二首 其一","f":"七言绝句","c":["风格孤高又国香，故教小雪发新妆。","修行嗟我无功力，却使天魔入道场。"]},{"t":"谢仲闵惠友于泉上多紫竹","f":"七言绝句","c":["地吉泉甘庆所钟，直疑遥与惠山通。","曲肱烦暑都消尽，如卧萧萧紫竹风。"]},{"t":"谢仲南和诗","f":"七言绝句","c":["曾约西湖薄主人，只今湖色已知春。","会须多载连车酒，绝胜寒仓满目尘。"]},{"t":"赏心亭","f":"七言绝句","c":["楫迎桃叶家何处，桨送莫愁人已非。","独立东风今古恨，春江无语又斜晖。"]},{"t":"道彭泽","f":"七言绝句","c":["姓陶令尹今何在，空补陈编归去来。","安得春江作春酒，百年长与子衔杯。"]},{"t":"韩信","f":"七言绝句","c":["登坛一日冠群雄，钟室仓皇念蒯通。","能用能诛谁计策，嗟君终自愧萧公。"]},{"t":"韩信祠","f":"七言绝句","c":["千金一饭恩犹报，南面称孤岂遽忘。","何待陈侯乃中起，不思萧相在咸阳。"]},{"t":"感春三首 其一","f":"七言绝句","c":["日长残雪滴高檐，院静人閒风度帘。","可是岁华随日好，故应愁恨逐春添。"]},{"t":"感春三首 其三","f":"七言绝句","c":["梅梢柳眼弄春娇，云暖南山腊雪消。","近郭樵渔成野市，远村箫鼓隔溪桥。"]},{"t":"感春三首 其二","f":"七言绝句","c":["冰消水面波光动，日暖树梢花意归。","世上繁华随日好，却应春浅胜芳菲。"]},{"t":"感秋三绝 其三","f":"七言绝句","c":["高林败叶已飕飕，更有寒莎翠已收。","若道神仙脱情累，如何独唱感庭秋。"]},{"t":"新春","f":"七言绝句","c":["水乡清冷落梅风，正月雪消春信通。","昨夜园林新得雨，杏梢争放晓来红。"]},{"t":"新堂望樊山","f":"七言绝句","c":["幽人井臼两山间，邻里樵渔尽往还。","兴发登临穷眼界，江南秀色碧云鬟。"]},{"t":"楚王","f":"七言绝句","c":["十二巫山耸翠峦，楚王宫殿玉巑岏。","定知为雨为云处，不似当初梦里看。"]},{"t":"楚城晓望","f":"七言绝句","c":["鼓角凌虚雉堞牢，晚天如鉴绝秋毫。","山川摇落霜华重，风日晴明雁字高。"]},{"t":"楚桥秋暮阻雨","f":"七言绝句","c":["水满城西钓艇横，云豪风弱晚冥冥。","天寒小店人愁雨，灯暗孤舟客卧听。"]},{"t":"福昌官舍后绝句十首 其二","f":"七言绝句","c":["小园寒尽雪成泥，堂角方池水接溪。","梦觉隔窗残月尽，五更春鸟满山啼。"]},{"t":"福昌官舍后绝句十首 其七","f":"七言绝句","c":["洛川春色几时归，漾漾清流照翠微。","日暖雪消沙岸软，鸳鸯相对不惊飞。"]},{"t":"福昌官舍后绝句十首 其四","f":"七言绝句","c":["漫与东风作主人，栽培花草伴閒身。","不辞伐竹成高架，收拾蔷薇一片春。"]},{"t":"福昌官舍后绝句十首 其一","f":"七言绝句","c":["淮南梅柳想春还，怯见西州岁暮寒。","惟有看山心未厌，晴明终日在阑干。"]},{"t":"福昌官舍后绝句十首 其六","f":"七言绝句","c":["翠竹留人不忍还，暖泉春涨已潺潺。","寄言山鸟休归去，与尔同来乐此间。"]},{"t":"福昌官舍后绝句十首 其十","f":"七言绝句","c":["清明山色到前檐，汩汩溪流聚小潭。","一榻竹窗晴昼睡，依依春梦入江南。"]},{"t":"福昌官舍后绝句十首 其八","f":"七言绝句","c":["风吹春日下南山，尚有轻冰结暮滩。","何事鸳鸯故相守，清溪不怕夜栖寒。"]},{"t":"福昌官舍后绝句十首 其九","f":"七言绝句","c":["不扫竹根藏笋茁，旋培残雪拥兰芽。","为君更接樱桃树，付与春风换却花。"]},{"t":"福昌官舍后绝句十首 其五","f":"七言绝句","c":["卧听堂南布谷鸣，陇头细麦已青盈。","殷勤谢汝催春种，我为无田岂懒耕。"]},{"t":"遣兴","f":"七言绝句","c":["百感摧伤强对春，看花花畔独沾巾。","祇应闭目林中坐，须学无言壁下人。"]},{"t":"鹎鵊","f":"七言绝句","c":["整刷衣裾紫翠新，晓天风露压鸡晨。","应知不置莲花漏，长唤林中宴坐人。"]},{"t":"僧允怀惠紫竹杖","f":"七言绝句","c":["轻坚滑泽节仍匀，上下柯山助老身。","他日天恩许归去，提携同踏故园春。"]},{"t":"墙东二首 其二","f":"七言绝句","c":["岁晚长安足风土，天寒官舍少文书。","下马闭门复无事，壁间佛像对铜炉。"]},{"t":"墙东二首 其一","f":"七言绝句","c":["墙东椿老叶已尽，堂下菊丛无复香。","长安风埃岁已晚，闭门不出马毛长。"]},{"t":"摘芙蓉","f":"七言绝句","c":["今年古寺摘芙蓉，憔悴真成泽畔翁。","聊把一枝閒照酒，明年何处对霜红。"]},{"t":"漫成七首 其七","f":"七言绝句","c":["庭阴当午起犹慵，断送残春醉梦中。","桑柘成阴桃李尽，一川零乱柳花风。"]},{"t":"漫成七首 其六","f":"七言绝句","c":["溪水春来清荡沙，溪南溪北是人家。","依依陌上多情柳，簇簇原头自在花。"]},{"t":"漫成七首 其五","f":"七言绝句","c":["江南梅花凌雪霜，桃李开尽春无光。","谁知洛阳三月暮，千金一朵卖姚黄。"]},{"t":"漫成七首 其四","f":"七言绝句","c":["风吹桃花西复东，雨打海棠零乱红。","可是春光即消歇，牡丹音信未全通。"]},{"t":"漫成七首 其三","f":"七言绝句","c":["高槐无花亦有阴，参天老枝逾十寻。","流莺不使人窥见，故隔深条送好音。"]},{"t":"漫成七首 其二","f":"七言绝句","c":["修竹娟娟一万竿，清渠引水正潺潺。","知时燕子来相语，任意凫雏去不还。"]},{"t":"漫成七首 其一","f":"七言绝句","c":["应敌诗才惭古人，牵情春色空閒身。","铺排物色虽甘拙，消散閒愁亦有神。"]},{"t":"漫呈无咎一绝","f":"七言绝句","c":["题扇灯前亦偶然，那知别后远如天。","去年醉舞看花处，独听琵琶却惘然。"]},{"t":"嘲无咎夜起明灯听慎思诵诗","f":"七言绝句","c":["翠屏香暖秋眠稳，霜冷宝奁金错刀。","谁信苦吟无睡客，挑灯起听楚人骚。"]},{"t":"樊山","f":"七言绝句","c":["黄叶疏林江上洲，西风角怨夕阳楼。","晚天紫翠凌空阔，只有樊山取意秋。"]},{"t":"潮水二首 其二","f":"七言绝句","c":["近来消息愈堪猜，飞鸟无情不肯回。","惟有清淮慰人意，春流日日自东来。"]},{"t":"潮水二首 其一","f":"七言绝句","c":["水满清淮自在流，落花吹尽浪悠悠。","总将春雨为春泪，未比思君一半愁。"]},{"t":"蕲水道中二首 其二","f":"七言绝句","c":["绿野新晴风日凉，肩舆细路转重冈。","桥边野水侵官道，旋唤渔舟渡夕阳。"]},{"t":"蕲水道中二首 其一","f":"七言绝句","c":["蚕老麦枯田舍忙，谁令四月雨浪浪。","未容乌鸟私遗粒，鸣蚓跳蛙欲满场。"]},{"t":"霅溪道至四安镇","f":"七言绝句","c":["苕霅清秋水底天，夜帆灯火客高眠。","江东可但鲈鱼美，一看溪山直万钱。"]},{"t":"题五柳亭","f":"七言绝句","c":["大夫风韵如彭泽，五柳萧森手自栽。","我亦扁舟倦游者，登临聊复赋归来。"]},{"t":"题史院直舍鱼鹭屏","f":"七言绝句","c":["钟鼓声稀下直迟，秋晖初转万年枝。","寒厅尽日谁相对，惭愧屏风两鹭鸶。"]},{"t":"题宅后井","f":"七言绝句","c":["清泉十丈白如浆，甘似醍醐透椀凉。","君欲道中无渴死，百寻操绠莫辞长。"]},{"t":"题西园酴醾","f":"七言绝句","c":["风霜老蘖蹙龙蛇，中有青春白玉葩。","要使根深生意遂，不妨秋雨卧泥沙。"]},{"t":"题寿阳楼二首 其二","f":"七言绝句","c":["长淮不断水悠悠，楼下行人淮上楼。","谁谓满前风景好，古今供作别离愁。"]},{"t":"题寿阳楼二首 其一","f":"七言绝句","c":["渺渺长淮去不休，行人独上寿阳楼。","一阕长歌不须唱，山川都是旧时愁。"]},{"t":"题周文翰郭熙山水二首 其二","f":"七言绝句","c":["洞庭叶落万波秋，说与南人亦自愁。","指点吴江何处是，一行鸿雁海山头。"]},{"t":"题周文翰郭熙山水二首 其一","f":"七言绝句","c":["鱼村橘市楚江边，人外秋原雨外川。","遣骑竹边邀短艇，天涯暮色已苍然。"]},{"t":"题画二首 其二","f":"七言绝句","c":["苍苍老石守寒丛，雪洒林鸠美睡中。","鹑傍陈根饥更啄，雀栖高蘖瞑愁风。"]},{"t":"题画二首 其一","f":"七言绝句","c":["败芦浸水冻滩沙，朔雪随风乱缀花。","湿翅老鸿鸣未起，暮云山色暗天涯。"]},{"t":"题南禅院壁二首 其二","f":"七言绝句","c":["秋林落叶已斑斑，秋日当庭尚掩关。","扫榻昼眠听鸟语，可怜身世此时閒。"]},{"t":"题南禅院壁二首 其一","f":"七言绝句","c":["乞食高僧午未归，秋庭落叶日晖晖。","萧条古寺松阴下，檐铎风中乳鸽飞。"]},{"t":"题宣州后堂壁四首 其四","f":"七言绝句","c":["流落天涯一病身，簿书丛里费精神。","殷勤照水窥华发，黄鸟声中又一春。"]},{"t":"题宣州后堂壁四首 其三","f":"七言绝句","c":["翠树阴阴晚雨回，江山清润绝纤埃。","军厨煮酒香初熟，更钓溪鱼斫鲙来。"]},{"t":"题宣州后堂壁四首 其二","f":"七言绝句","c":["我欲留春情不浅，青春别我苦无情。","敬亭山下红千树，日日南风绿满城。"]},{"t":"题宣州后堂壁四首 其一","f":"七言绝句","c":["过雨山亭暑气微，老人犹未试生衣。","满园閒绿无人到，春日南风燕子飞。"]},{"t":"题庭木","f":"七言绝句","c":["枯条怪石坐寒禽，玉轴高悬画万金。","岁晚荒畦真在眼，寂寥方见此时心。"]},{"t":"题洛尾亭二首 其二","f":"七言绝句","c":["洛尾亭边淮汴交，来波去浪恨迢迢。","无端更洒黄昏雨，吹作春愁不肯消。"]},{"t":"题洛尾亭二首 其一","f":"七言绝句","c":["日出南山春雾收，浑浑洛尾入淮流。","莫向行人赠杨柳，折将离恨入孤舟。"]},{"t":"题荣子邕陋居二首 其二","f":"七言绝句","c":["一室荒芜孺子贫，知君四海入经纶。","杀身虎口终何补，洒扫庭除自可人。"]},{"t":"题荣子邕陋居二首 其一","f":"七言绝句","c":["草舍隆中一幅巾，闭门三致汉将军。","纷纷自献知何有，终遣斯人了鼎分。"]},{"t":"题赵楶所收赵令穰大年烟林二绝 其二","f":"七言绝句","c":["枫林荻港白昼静，落雁飞鸥尽日閒。","平远起君千里恨，清诗可要助江山。"]},{"t":"题赵楶所收赵令穰大年烟林二绝 其一","f":"七言绝句","c":["江上孤烟蔽远林，秋原人静下鸣禽。","水乡此景常经眼，谁信侯家画万金。"]},{"t":"题轸师房二首 其二","f":"七言绝句","c":["铜瓶布衲出尘埃，疏瘦风标日一斋。","门径萧然更无事，生萤飞鸽及时来。"]},{"t":"题轸师房二首 其一","f":"七言绝句","c":["漠漠雨苔依砌绿，鲜鲜秋菊映阶黄。","山僧睡起日亭午，出户微微柏子香。"]},{"t":"题唐宋辅城上小楼二首 其二","f":"七言绝句","c":["近郊小径绝人行，水满菰蒲取次生。","沙岸雨来长集燕，桑田深处忽闻莺。"]},{"t":"题唐宋辅城上小楼二首 其一","f":"七言绝句","c":["沙田小雨不成泥，一带溪光照翠微。","远目直随残日尽，晚云还望故山归。"]},{"t":"题扇二首 其二","f":"七言绝句","c":["弯弯凉月帖淮天，露湿蒲梢风堕莲。","松盖草茵迎不至，南山桂子老秋烟。"]},{"t":"题扇二首 其一","f":"七言绝句","c":["越衫罗薄逆新凉，扇剪青绡秋水光。","花前一把罗敷手，直到花残襟袖香。"]},{"t":"题海州怀仁令藏春亭","f":"七言绝句","c":["闻道山中贤长官，种花不肯放春还。","故知车马红尘地，催促东风不得閒。"]},{"t":"题淮阴侯庙","f":"七言绝句","c":["云梦何须伪出游，遭谗犹得故乡侯。","平生萧相真知己，何事还同女子谋。"]},{"t":"题绿野亭","f":"七言绝句","c":["渺渺孤亭沧海东，天连平野四无穷。","可须户牖毫端上，自揽山河眼界中。"]},{"t":"题寒溪长老方丈","f":"七言绝句","c":["满坐绳床百事贫，荒溪古屋四无邻。","为生易足君无笑，渠是人间得计人。"]},{"t":"凝祥三首 其三","f":"七言绝句","c":["奉灵桃李已堪攀，只有春风作往还。","园吏不须防客到，长安从古少人閒。"]},{"t":"凝祥三首 其二","f":"七言绝句","c":["已随芳草藉杯盘，更任垂杨拂马鞍。","斜日两竿眠犊晚，春波一眼去凫寒。"]},{"t":"凝祥三首 其一","f":"七言绝句","c":["斋祠太一馆清真，望秩名山固有神。","斜日苑门人不到，灵风自扫石床尘。"]},{"t":"橘","f":"七言绝句","c":["霭霭高林绿实圆，清霜一洗若金悬。","李衡何等相奴隶，自有高人相国贤。"]},{"t":"赞皇公","f":"七言绝句","c":["才高一世有奇功，掩卷令人独想风。","莫笑狄祠迁武相，致人从古是英雄。"]},{"t":"赠无咎","f":"七言绝句","c":["欺马街泥未肯乾，重城含雾晓漫漫。","谁令万屋淋漓雪，犹作长安半夜寒。"]},{"t":"赠别仪上人","f":"七言绝句","c":["师似浮云触处闲，倦飞知我未能还。","林泉会有相逢日，风月应须乞半山。"]},{"t":"赠赵簿景平二首 其二","f":"七言绝句","c":["纷纷俗物久堪憎，爱子萧萧眉宇清。","莫叹青衫掩事业，白头卿相死无名。"]},{"t":"赠赵簿景平二首 其一","f":"七言绝句","c":["明道新坟草已春，遗风犹得见门人。","定知鲁国衣冠异，尽戴林宗折角巾。"]},{"t":"赠圆明老","f":"七言绝句","c":["一粥一斋年已老，千经万论不留心。","菩提本自非言说，默默知师得更深。"]},{"t":"赠铁牌道者","f":"七言绝句","c":["微官待旦亦朝天，赖尔绝胜钟鼓传。","举世昏冥竟难警，怜君常负五更眠。"]},{"t":"蹇驴","f":"七言绝句","c":["骥伏盐车饥不行，疲牛与尔饱平生。","子荆自是佳公子，亦向人前作汝声。"]},{"t":"鵁鶄","f":"七言绝句","c":["败荷枯苇一方池，溪上鵁鶄坐得知。","何事月寒风露下，挛拳孤影在风枝。"]},{"t":"一日复一日","f":"五言律诗","c":["一日复一日，炎凉行一周。","异乡犹在望，白发久生头。","且看寻橦技，休怀失马忧。","天公有至信，万古一春秋。"]},{"t":"丁丑岁与德载相别辛巳复会于颍相视而叹仍蒙先惠佳句谨次韵","f":"七言古诗","c":["重入修门一见春，衰容仍是卧漳滨。","归来未解累囚服，挥去真同下坂轮。","痛饮久无连夜醉，白头何啻二毛新。","□□□□□□□，□□□□□□□。"]},{"t":"七月七日晚步园中见落叶如积感而作","f":"五言律诗","c":["东园久不到，落叶曲池平。","摇落遽如许，岁时真可惊。","衡茅望故里，渔钓寄馀生。","放逐逢艰岁，藜羹未敢轻。"]},{"t":"七月十五日希古生日以诗为寿","f":"七言律诗","c":["苍颜白发老祠官，邂逅淮扬一笑欢。","且可鲸吞卮满酒，行看鹗立豸拿冠。","寿觞满对秋风举，生日欣逢伏暑阑。","阅世祝公松柏寿，从来霜雪不能寒。"]},{"t":"七言","f":"七言律诗","c":["飞鸿归尽燕将还，亭院深沉人倚栏。","斜搭鞦韆寒食雨，已黄杨柳暮春寒。","密毬杏萼红如糁，半落梅花香未残。","人世年年非旧事，感时惟有泪汍澜。"]},{"t":"九日独游怀故人","f":"七言律诗","c":["故人分散在天涯，九日登临独叹嗟。","人世光阴催日日，乡闾时节自家家。","风烟满眼临秋尽，鼓角荒城送日斜。","取醉凭谁正乌帽，遣愁犹强插黄花。"]},{"t":"九月十八日梦中作闻雁诗","f":"五言律诗","c":["何日离燕碛，来投江上洲。","高鸣云际夜，冷度雨中秋。","缯缴远须避，稻粱寒未收。","春风归翼便，容易一冬留。"]},{"t":"二十二日立秋夜行泊林皇港二首 其二","f":"五言律诗","c":["吴楚封疆接，东南泽国宽。","江流秋日尽，山对暮云闲。","囊有离骚赋，头馀骑省斑。","前秋聊把酒，一笑且开筵。"]},{"t":"二十二日立秋夜行泊林皇港二首 其一","f":"五言律诗","c":["萧萧晚风起，孤舟愁思生。","篷窗一萤过，苇岸数蛩鸣。","老大畏为客，风波难计程。","家人夜深语，应念客犹征。"]},{"t":"二月十七日欲招客饮而风霾不果有作","f":"七言律诗","c":["欲携佳客燕高堂，园馆春风又作狂。","犹挟冰霜馀意气，未分桃李好风光。","青山无赖藏云岫，流水生波滟野塘。","不饮何妨还燕坐，闭门扫地独焚香。"]},{"t":"二月三日舣舟徐城戏呈戚郎","f":"五言律诗","c":["自嗟为客久，羁旅过淮时。","雪野挑蔬瘦，霜天暖酒迟。","流年下坡毂，万事一枰棋。","异日怀陈迹，孤舟近古祠。"]},{"t":"人家","f":"五言律诗","c":["人家依古木，鸡犬乱山深。","积雪暗犹壮，寒云晚易阴。","断荷攲冻水，孤月战风林。","稍稍栖乌定，饥啼何处禽。"]},{"t":"八月十一日晨兴三首 其一","f":"五言律诗","c":["老人秋少睡，禅诵每晨兴。","邻碓舂残月，床蛩语暗灯。","高林鸟声起，幽草露华凝。","筇杖兼禅榻，生涯一野僧。"]},{"t":"八月十一日晨兴三首 其三","f":"五言律诗","c":["江上秋阴合，柯山晓雨来。","貂裘欲辞箧，纨扇已生埃。","落叶湿相藉，晚花寒未开。","殷勤探黄菊，九日泛清杯。"]},{"t":"八月十一日晨兴三首 其二","f":"五言律诗","c":["端居岁已宴，杖履亦萧然。","云露窗前日，秋明树外天。","大江寒欲落，诸岭霁逾鲜。","白首无聊剧，昏昏只醉眠。"]},{"t":"十一月七日五首 其四","f":"五言律诗","c":["三杯无奈醉，一褐有馀温。","眼下幸无事，世间何足论。","山僧元饱饭，词客谩招魂。","杖策知何诣，门前老圃村。"]},{"t":"十一月七日五首 其一","f":"五言律诗","c":["寒更催欲尽，曙色转鸡吭。","鸣雁背晓斗，清笳吟宿霜。","空山岁华晚，故园归梦长。","晨起临清镜，悲嗟发已苍。"]},{"t":"十二月二十六日旦闻东堂啄木声忽记作福昌尉时在山间环舍多老木腊后春初此鸟尤多声态不一今琵琶筝中所效既不类又百不得一二云","f":"五言律诗","c":["睡馀闻啄木，忽忆福昌春。","官舍题诗壁，如今经几人。","犹能老耽酒，依旧拙谋身。","尚想兰宫路，东风清洛滨。"]},{"t":"十二月十七日移病家居成五长句 其四","f":"七言律诗","c":["从今羞复走功名，卤莽因循已半生。","心遣我愚应有谓，眼看人智亦何成。","梦为蝴蝶因观化，目送飞鸿漫寄情。","堪笑妻儿怀土甚，谪期未满已谋行。"]},{"t":"十二月十七日移病家居成五长句 其五","f":"七言律诗","c":["纸窗低下火炉边，有底宜人意若便。","移疾何妨闲五日，放慵犹欲醉终年。","平生亲友怀天末，谈笑妻儿在目前。","谁似匡庐白居士，暮年华发洛阳仙。"]},{"t":"十二月十七日移病家居成五长句 其三","f":"七言律诗","c":["凭高游目快遐瞻，落日孤云与水兼。","万顷泽空供雪意，一枝梅笑破冬严。","擎苍未减飞扬兴，引满何辞斗石添。","杨柳催春兼警客，荒沟照影弄纤纤。"]},{"t":"十二月十七日移病家居成五长句 其二","f":"七言律诗","c":["老去尘怀痛洗煎，虚舟不系任回沿。","寸心若变有如日，万事不忧终在天。","莫为饥寒弃南亩，须知穮蓘有丰年。","桃符侲子喧闾巷，又向江城十岁捐。"]},{"t":"十月二十日夜大雨雹震电先是数日极暖至是方稍晴","f":"七言律诗","c":["江乡节候异中州，十月狂雷震未休。","二年到耳同常事，一夜雨声如蚤秋。","想见麦畦添宿润，更欣蔬甲长新柔。","东堂晚望无氛祲，洗出樊山紫翠浮。"]},{"t":"万松亭有感","f":"七言律诗","c":["荦确山行穿翠微，石云秋露湿秋衣。","朦胧小睡还成梦，讽咏新诗且疗饥。","千里归来人事改，四年辛苦旧容非。","祇应亭下青云盖，依旧苍腰耸十围。"]},{"t":"三乡怀古","f":"七言律诗","c":["清洛东流去不还，汉唐遗事有无间。","庙荒古木连空谷，宫废春芜入乱山。","南陌絮飞人寂寂，空城花落鸟关关。","登临几度游人老，又对东风鬓欲斑。"]},{"t":"三月一日马令送花","f":"七言律诗","c":["未说浔阳别泪痕，江边蘋芷不胜繁。","不知来岁在何处，又对新花忆故园。","插帽每惭辉白发，飞香曾伴照清尊。","去年今日淮阳道，落絮残红正断魂。"]},{"t":"三月十二日作诗董氏欲为筑堂","f":"七言律诗","c":["黄鸟声中花已尽，绿杨风外日何长。","柯家山下有幽筑，云梦泽南飞故乡。","老病裌衣犹怯冷，春深煮酒渐闻香。","本无智术争荣辱，只斗尊前身健强。"]},{"t":"上元日驾回登楼二首 其二","f":"七言律诗","c":["长街十二远相通，阊阖峨峨彩雾红。","天白华灯交皓月，楼寒朱幕荡春风。","车头笑语归时醉，城下传呼夜向中。","自古长安多乐事，周南留滞意何穷。"]},{"t":"上元日驾回登楼二首 其一","f":"七言律诗","c":["紫雾氛霏阊阖开，团团明月上天来。","香车百两天街晚，清跸一声仙仗回。","灯隔画帘时闪烁，风穿高幕故徘徊。","太平日久多閒暇，簪笏从容侍燕杯。"]},{"t":"上元后步西园","f":"七言律诗","c":["物态欣欣换旧年，收灯城市却萧然。","风光欲到冰霜树，日月初回雨露天。","近水远山情脉脉，碧云芳草思绵绵。","酬春欲办千缸酒，洒扫花前作醉眠。"]},{"t":"上元思京辇旧游三首 其三","f":"七言律诗","c":["随计当年寄玉京，一时交结尽豪英。","倒觥凌乱迷筹饮，醉帽敧斜并辔行。","仕路飞腾输俊杰，山城憔悴感功名。","佳晨强酌清樽酒，寒竹萧萧月正明。"]},{"t":"上元思京辇旧游三首 其二","f":"七言律诗","c":["九门灯火夜交光，罗绮风来扑面香。","信马恣穿深柳巷，随身偷看隔帘妆。","身居薄宦安知乐，心逐流年暗减狂。","留滞山城莫嗟叹，貂蝉从古属金张。"]},{"t":"上元思京辇旧游三首 其一","f":"七言律诗","c":["万雉春城逼绛霄，上元雕辇盛游遨。","迟迟瑞日低彤伞，焯焯荣光上赭袍。","云捲朱帘开綵雉，山盘玉阙枕仙鳌。","长安一别将华发，溪竹山城夜寂寥。"]},{"t":"下春风岭","f":"七言律诗","c":["东归已过春风岭，度尽千山路渐平。","人事水泡能几日，流光驹隙却堪惊。","居人落落多新屋，行店依依认旧程。","世事饱谙身已老，区区来往笑浮生。"]},{"t":"与李文举登梦野亭","f":"七言律诗","c":["樽俎相逢散百忧，虽非吾土共登楼。","天边云送荆王雨，江上枫彫宋玉秋。","华发不堪怀故国，清杯相与散牢愁。","清谈七泽谁强健，莫学骚人赋远游。"]},{"t":"久阴忽晴作诗寄秬秸时二子沿干在阳翟镇","f":"七言律诗","c":["想尔扁舟野岸横，久阴今旦喜晴明。","天寒野旷北风利，云霁江浑春水生。","家近冻醪时可致，旅庖鸣雁足供烹。","东园早作归来计，红紫纷纷日向荣。"]},{"t":"之天长会宿僧院","f":"五言律诗","c":["萧条林下寺，客至解尘鞍。","雨过月逾白，夜深秋向寒。","老僧无俗累，爱客故盘桓。","之子静相对，松风清石栏。"]},{"t":"大雪中李提举惠玻璃泉两榼二首 其二","f":"七言律诗","c":["峰高冻雪埋苍玉，河静黄沙咽浊流。","嗟我残年为远客，烦君双榼散羁愁。","屠苏禦岁将传盏，綵胜宜春欲插头。","痛饮须知谋日富，无田何用庆来麰。"]},{"t":"大雪中李提举惠玻璃泉两榼二首 其一","f":"七言律诗","c":["南山春雪冻云凝，暗火青灯急霰声。","栗烈残年新庆雪，玻璃美酒旧知名。","饥肠未惯犹空吼，冻脸何知辄妄赪。","隐忍且须留一榼，晴明待作探梅行。"]},{"t":"大雪苦寒五更无睡枕上成两篇 其二","f":"五言律诗","c":["雪气著我屋，鸡肤畏薄衾。","春寒竹窗睡，晓梦故乡心。","多病妨豪饮，无私称苦吟。","小炉炽新炭，卯酒再三斟。"]},{"t":"大雪苦寒五更无睡枕上成两篇 其一","f":"五言律诗","c":["大雪人迹绝，衡门闭不知。","寒城悲角迥，幽谷晓鸡迟。","岁月去如失，穷通默自知。","但知饱寝饭，天道两无私。"]},{"t":"大暑戏赠希古","f":"七言律诗","c":["去年挥汗对淮流，寒暑那知复一周。","土润何妨兼伏暑，火流行看放清秋。","鬓须总白难相笑，观庙俱閒好并游。","只怕樽前誇酒量，一挥百盏不言休。"]},{"t":"小雨","f":"五言律诗","c":["小雨廉纤晚，幽花寂历秋。","嘉时空冉冉，白日付悠悠。","乱思工萦恨，危肠只贮愁。","唯应时扣寂，一念万缘休。"]},{"t":"山下","f":"七言律诗","c":["山下疏钟日夜催，城头画角五更哀。","流年忽忽愁中过，世事纷纷空里来。","沮溺漫高轻世节，管商空尽济时才。","古来扰扰今何有，一熟黄粱梦已回。"]},{"t":"山行","f":"五言律诗","c":["驱马春山去，山蹊绕涧斜。","浅清沙岸水，疏瘦石岩花。","放荡从生事，殷勤向物华。","依微听鸡犬，深柳映人家。"]},{"t":"山夜","f":"五言律诗","c":["更漏孤城迥，帘帷静夜长。","天高风送雁，月冷树浮霜。","晚菊差池绿，高桐次第黄。","晓来南国梦，不觉寄他乡。"]},{"t":"山舍","f":"五言律诗","c":["萧萧山舍静，谁复与相亲。","琴酒忘尘事，诗书有古人。","岁丰民事少，地辟土风淳。","聊乐身无事，功名丧我真。"]},{"t":"出都之宛丘赠寄参寥","f":"五言律诗","c":["萧然耳目清，驱马别都城。","岸断秋光出，川平雨气横。","浮生归物理，闲景付诗情。","岁晚江湖客，何为滞玉京。"]},{"t":"己卯十二月二十日感事二首 其二","f":"七言律诗","c":["蹉跎流落已华颠，又见荆湖一岁迁。","人怯苦寒愁日短，天收残腊放新年。","园林寂历飘梅后，里巷经过爆竹前。","自料知非犹得在，潜心久学卫蘧先。"]},{"t":"己卯十二月二十日感事二首 其一","f":"七言律诗","c":["高楼乘兴独登临，搔首天涯岁暮心。","带雪腊风藏泽国，犯寒春色著烟林。","山川极目风光异，岁月惊怀老境侵。","可是斯文天未丧，楚囚何事涕沾襟。"]},{"t":"己未早春有感","f":"七言律诗","c":["南国柳黄莺未知，人情何事憾春迟。","雪抽宿麦晴来叶，雨长枯榆烧后枝。","载酒有谁寻寂寞，受薪只合学支离。","近知壁观安心法，亦拟平治不作诗。"]},{"t":"中秋无月戏呈希古年兄","f":"七言律诗","c":["放逐江湖一钓舟，萧条故国又逢秋。","炎凉始信来如旧，岁月相催逝不留。","日落千蛩喧户牖，风高一雁下汀洲。","地无积潦蟾华好，谁买新醪作夜游。"]},{"t":"书直舍","f":"五言律诗","c":["为官不治民，清坐晚秋晨。","随事文书了，偷闲笔砚亲。","吏归雅集定，门锁月华新。","野鸟何劳问，穷通理有神。"]},{"t":"书壁","f":"七言律诗","c":["晴窗浴罢试春衣，芳草江南三月时。","阴合园林禽语乐，风和庭院絮飞迟。","漫郎官事只画诺，骚客生涯惟赋诗。","极目江天已多恨，何须木落长年悲。"]},{"t":"书壁","f":"五言律诗","c":["后院人稀到，荒池半是苔。","好花随地有，幽鸟自山来。","靡靡香草合，阴阴夏木催。","昭亭有佳色，每至不容回。"]},{"t":"予元丰戊午岁自楚至宋由柘城至福昌年二十有五后十年当元祐二年再过宋都追感存殁怅然有怀","f":"七言律诗","c":["宋玉台前官树林，十年孤客独沾襟。","白头青鬓隔存殁，落日断霞无古今。","暮云梁苑雁鹜暗，久泛吴船江海深。","阅世悲欢嗟老眼，呼儿取酒十分斟。"]},{"t":"今早将饮酒闻莺有感","f":"五言律诗","c":["萧条古兰若，春日等閒斜。","唧唧初闻燕，匆匆又过花。","旧游都似梦，到处即为家。","把酒听莺处，羁怀感岁华。"]},{"t":"以病在告寄杨器之","f":"七言律诗","c":["饮冷寒中不自知，故应病骨易尪羸。","老人素懒何妨病，太守兼容得自私。","雨汗欺风元自湿，火云挟日故行迟。","江楼清绝真孤负，正是斋居禁酒时。"]},{"t":"内生日","f":"七言律诗","c":["从我奔驰走四方，清贫殊不厌糟糠。","黔娄环堵贫常醉，寿母高堂老亦康。","夷险百为吾有命，穷通一意子真刚。","今年生日心无事，好为儿孙举寿觞。"]},{"t":"双凫","f":"五言律诗","c":["双凫元自白，况乃小池清。","逐伴知身洁，当庭独眼明。","暖沙晴共戏，寒渚夜多惊。","何事秋风起，轩然向主鸣。"]},{"t":"双槐晚秀三月一日初见新叶","f":"七言律诗","c":["东皇无处著繁华，亦复分张到我家。","他日老苍悲败蘖，今晨嫩绿出新芽。","秃翁承弁纤纤发，村妇萦鬟草草花。","桃李蹊中人绝迹，绿阴门巷正藏鸦。"]},{"t":"太府李萃卿挽词","f":"五言律诗","c":["妙誉驰场屋，家风在搢绅。","使华推厚德，卿月上通津。","齿德时方重，山丘迹已陈。","长年先友泪，怀感独沾巾。"]},{"t":"太皇太后挽词","f":"五言律诗","c":["共政艰难际，临朝保佑初。","经纶付耆老，利泽到樵渔。","礼盛谦常抑，功成委不居。","圣君深致孝，尽守典刑馀。"]},{"t":"太皇太后挽词","f":"七言律诗","c":["坐安民物由修己，默合神明为至公。","他日已占怀月梦，后来方信补天功。","四时化育坤无事，六合清明日正中。","九载忧勤已陈迹，空留双阙对青嵩。"]},{"t":"少年","f":"五言律诗","c":["朱绳缚天狗，白羽射旄头。","新佩将军印，初成甲第楼。","绮罗诸院夜，鞍马五陵秋。","惟有如霜鬓，令君览镜愁。"]},{"t":"文周翰惠酒以诗谢之","f":"七言律诗","c":["一梦东都白发新，天涯同是吊灵均。","读书久误平生事，饮酒聊娱现在身。","汉上卧龙新得雨，江边饥雁晚知春。","黄髯相见应相问，为道真成泽畔人。"]},{"t":"无题","f":"五言律诗","c":["蔌蔌鸣叶下，初无风过之。","流年一如此，慷慨使心悲。","平日谈尧舜，立朝羞自私。","温炉煖老客，聊复此栖迟。"]},{"t":"日落","f":"五言律诗","c":["日落长云暗，风悲古岸秋。","渚鸥遥避客，野蝶戏随舟。","疏拙资微禄，飘零厌远游。","若无尊里酒，何物与消愁。"]},{"t":"月夜怀陈永源","f":"五言律诗","c":["众喧息遥夜，爽气渍烦襟。","殷勤低檐月，入幌来相寻。","平生学虚静，每为多病侵。","卧想陈夫子，幅巾修竹林。"]},{"t":"木芙蓉菊花盛开","f":"七言律诗","c":["空山岑寂何所有，晚菊芙蓉相对幽。","伴我悠悠过閒日，怜渠灼灼媚穷秋。","清香但欲持供佛，醉舞何妨插满头。","此生萍梗难前料，知复明年相见不。"]},{"t":"水南春望","f":"七言律诗","c":["洛岸东风送马行，桥横落日半川明。","天连观阁云垂地，春入山河秀满城。","老去飘萍甘屏迹，兴来怀古未忘情。","短歌一曲聊回首，不待悲秋白发生。"]},{"t":"牛谷口","f":"七言律诗","c":["十万全师一战擒，谷盘苍硖路幽深。","凄凉今古兴亡事，辽阔英雄割据心。","涨洛暮连诸谷雨，秋云低抱半山阴。","文皇功业今何处，磨灭荒碑蔓草侵。"]},{"t":"王子开朝散早年以疾病谢事还江阴求诗为别三首 其一","f":"五言律诗","c":["济物昔所务，舍耕还自非。","骎骎老将至，忽忽意多违。","门有王夫子，柴车谢事归。","令人三叹息，羞涩向尘衣。"]},{"t":"邓学士慎思挽词","f":"五言律诗","c":["清苦吟诗客，癯羸嗜学身。","诗书不得力，鬼物定欺人。","类物传遗学，经书植妙因。","九原谁与友，千载葬鱼臣。"]},{"t":"邓慎思学士挽词","f":"七言律诗","c":["青衫献赋逢知己，白首耽书还误身。","名著道山传故事，政行两郡泣遗民。","文成典午群疑泮，诗和少陵佳句新。","叹息苦身成底事，湖坟宿草已愁人。"]},{"t":"东池","f":"五言律诗","c":["东池久不到，摇落过秋中。","万竹萧萧雨，孤荷袅袅风。","遣秋诗酒在，久客岁时穷。","唯有思乡梦，长随洛水东。"]},{"t":"东堂","f":"五言律诗","c":["杳杳寒鸡唱，漫漫夜色深。","斗柄垂地直，河势向江沉。","林鸟栖欲去，草虫寒尚吟。","幽人掩蓬荜，不睡拥单衾。"]},{"t":"他乡","f":"五言律诗","c":["春寒客古寺，草草过莺花。","小榼供朝酒，温炉煮夜茶。","柏庭鸣晓吹，楼角丽朝霞。","莫叹萍蓬迹，心安即是家。"]},{"t":"冬日书事二首 其二","f":"五言律诗","c":["孤城已惨淡，晚色复朦胧。","日动乌栖叶，云开雁去风。","草繁田尚绿，霜薄叶微红。","已是悲摇落，那堪岁更穷。"]},{"t":"冬日书事二首 其一","f":"五言律诗","c":["草草漫翁居，心安知有馀。","风高收野潦，霜晚足园蔬。","宿火温茶箧，明灯转素书。","御冬无旨蓄，渍药酒盈壶。"]},{"t":"冬日杂书六首 其六","f":"五言律诗","c":["望极添秋思，楼高动旅怀。","天寒诸濑急，野阔四山来。","馀叶能几许，高鸿殊未回。","年年洛阳道，岁晚厌风埃。"]},{"t":"冬日杂书六首 其五","f":"五言律诗","c":["短景冰霜地，人稀豹虎村。","风连诸壑动，日带乱山昏。","浩荡空回首，萧条独掩门。","东周旧耆老，留滞饱知闻。"]},{"t":"冬日杂书六首 其四","f":"五言律诗","c":["岁暮周南远，惊心鬓欲丝。","风霜为客老，淮海寄书迟。","峡冷重云夜，天昏断雁悲。","山炉通夕火，赖尔独吾私。"]},{"t":"冬日杂书六首 其三","f":"五言律诗","c":["一径秋风起，牛羊晚自归。","寒灯明野店，吠犬守荆扉。","空峡风霜急，孤村火烛微。","庭梧摇落尽，栖鸟夜归稀。"]},{"t":"冬日杂书六首 其二","f":"五言律诗","c":["岁暮北风疾，山深寒日昏。","授衣贫厌补，添纩老须温。","懒慢抛书卷，晴明到药园。","邻家新酒熟，吾敢但空樽。"]},{"t":"冬日杂书六首 其一","f":"五言律诗","c":["地僻秋将老，山深客未归。","闭门朝对雨，搜箧冷添衣。","图暗经阴画，琴昏在匣徽。","妻孥惯山薮，不复问珠玑。"]},{"t":"冬日杂兴六首 其六","f":"五言律诗","c":["击柝山城闭，疏灯野店扃。","疾风鸣夜谷，晴水动浮星。","霜翼归何晚，邻机织未停。","短歌时自和，愁绝更谁听。"]},{"t":"冬日杂兴六首 其五","f":"五言律诗","c":["南壁苍崖壮，穷冬井落閒。","风声先老树，日色避诸山。","落雁饥相向，啼乌夕自还。","微微寒月影，蓬户已深关。"]},{"t":"冬日杂兴六首 其四","f":"五言律诗","c":["空山身欲老，徂岁腊还来。","愁怯年年柳，伤心处处梅。","绿蔬挑甲短，红蜡点花开。","冰雪知何有，东风日夜回。"]},{"t":"冬日杂兴六首 其三","f":"五言律诗","c":["池馆留馀雪，西山照夕曛。","腊催梅蕊迸，春向鸟声新。","愁思供多病，风光欲近人。","年年桃李树，相对只伤神。"]},{"t":"冬日杂兴六首 其二","f":"五言律诗","c":["水落桥痕在，沙乾岸草枯。","霜馀槐老壮，风际竹清疏。","啄木高逾响，鹡鸰飞且呼。","二年亲友绝，惟有对禽鱼。"]},{"t":"冬日杂兴六首 其一","f":"五言律诗","c":["小园晴自扫，曝日坐前轩。","野鼠穿山叶，寒乌啄草根。","短篱藩隙地，别径入孤村。","幽趣供岑寂，淹留不复论。"]},{"t":"冬日作二首 其二","f":"五言律诗","c":["泽国久还雨，频妨裘褐温。","羁怀常悄悄，醉眼任昏昏。","云赴荆王梦，天迷楚客魂。","飘萍惟泥酒，吾事肯轻论。"]},{"t":"冬日作二首 其一","f":"五言律诗","c":["南雨不成雪，北风楼观寒。","眉颦鲁酒薄，肠断楚梅酸。","云梦寒全薄，湖湘春欲还。","举头瞻去雁，羡尔有轻翰。"]},{"t":"冬节小不佳怀正叔老兄","f":"七言律诗","c":["老境光阴短景催，新冬又复一年回。","焚香燕坐衣僧衲，煮药高眠废酒杯。","处处庖厨鸣瓮缶，年年歌笑惨风埃。","孟公歌舞犹须雪，未放愁眉取次开。"]},{"t":"冬后三日郊赦到同郡官拜敕回有感","f":"七言律诗","c":["诏书夜下走风雷，清晓州门拜敕回。","天上六龙归禁阙，人间一雨到根荄。","江边时日将舒柳，雪后春光欲到梅。","白首放臣随众喜，教儿深酌手中杯。"]},{"t":"冬至三首 其三","f":"五言律诗","c":["孤衾不成寐，起坐听鸡号。","楼闭更筹静，天寒星斗高。","萧条陶令酒，清怨楚臣骚。","凛凛悲秋意，何须待二毛。"]},{"t":"冬至三首 其二","f":"五言律诗","c":["汴水日夜浅，天寒霜野宽。","拂衣秋叶乱，冲面北风寒。","不作归山计，空悲走马鞍。","济时吾力薄，俯仰一悲叹。"]},{"t":"冬至三首 其一","f":"五言律诗","c":["昨夜新霜落，淮南十月初。","寒云风后白，高木雨来疏。","功业嗟谋拙，星霜逼岁馀。","子云真拙者，寂寞为玄书。"]},{"t":"冬至后三日三首 其三","f":"五言律诗","c":["梅柳有情态，江城过岁除。","山村见霜橘，江市出寒鱼。","谪久衣冠懒，身闲故旧疏。","傍篱挑翠甲，忆我故园蔬。"]},{"t":"冬至后三日三首 其二","f":"五言律诗","c":["水国过冬至，风光春已生。","梅如相见喜，雁有欲归声。","老去书全懒，闲中酒愈倾。","穷通付吾道，不复问君平。"]},{"t":"冬至后三日三首 其一","f":"五言律诗","c":["寒暑添线衲，朝晡折足铛。","何劳问荣辱，便是了平生。","理自阴阳运，吾宁口舌争。","深居玩吾宝，不遗世人轻。"]},{"t":"冬至赠潘郎","f":"七言律诗","c":["晓镜星星华发新，江山流落未归人。","五纹暗度人间线，九寸潜通地下春。","歌笑欣欣环老稚，杯盘草草称清贫。","与君同是柯山客，窗外梅花解笑人。"]},{"t":"出都有感","f":"七言律诗","c":["来时雪尽花初发，归去柳阴蝉乱鸣。","四序风光半为客，百年飘泊一浮名。","春来多病思高卧，老去违时畏后生。","若有黄精换华发，敢随车马到高城。"]},{"t":"务中晚作","f":"五言律诗","c":["官事一酒瓮，寝斋低竹檐。","朝昏睡过半，老病醉相兼。","楼晚双旂袅，城昏叠鼓严。","隔江吹笛处，空碧帖新蟾。"]},{"t":"北桥送客","f":"七言律诗","c":["桥上垂杨系马嘶，桥头船尾插青旗。","船来船去知多少，桥北桥南长别离。","亭上几倾行客酒，游人自唱少年辞。","百年回首皆陈迹，浮世飘零亦可悲。"]},{"t":"发云山近岐亭望光蔡接尉氏","f":"七言律诗","c":["白草黄茅间瘦田，郊原残暑已萧然。","泽连楚梦悲秋野，山近尧封望日天。","浓绿远陂铺晚稼，幽香秋水折残莲。","热行更益相如渴，怅望华陵陆子泉。"]},{"t":"发长平","f":"五言律诗","c":["归牛川上渡，去翼望中迷。","野水侵官道，春芜没断堤。","川平双桨上，天阔一帆西。","无酒消羁恨，诗成独自题。"]},{"t":"发安化回望黄州山","f":"七言律诗","c":["流落江湖四见春，天恩复与两朱轮。","几年鱼鸟真相得，从此江山是故人。","碧落已瞻新日月，故园好在旧交亲。","此生已免嘲伧父，莫避北风京洛尘。"]},{"t":"发泗州","f":"七言律诗","c":["万艘猎猎战风桅，我亦孤舟别岸隈。","漠漠晓云生木末，萧萧飞雨送帆开。","消磨岁月书千卷，零落江湖酒一杯。","因病得州真漫尔，功名于我亦悠哉。"]},{"t":"发金陵折柳亭二首 其一","f":"五言律诗","c":["绿衮溶溶日，红飞寂寂春。","青山今古事，芳草去来人。","歌吹酒家市，帆樯贾客津。","谁云绝胜地，登眺更伤神。"]},{"t":"发金陵折柳亭二首 其二","f":"五言律诗","c":["桃李蕃晴日，江山秀晚春。","孤舟多病客，长道未归人。","豪俗竞行乐，倦游慵问津。","南山还暮雨，疑有楚台神。"]},{"t":"四月二十日书二首 其二","f":"七言律诗","c":["久将醉眼视群儿，只与旁观作笑嘻。","赋芋狙公曾未悟，牵丝木偶几多时。","云间炎景人方畏，地下微阴谁得知。","荣谢古今同此理，老翁端坐但忘机。"]},{"t":"四月二十日书二首 其一","f":"七言律诗","c":["十步荒园亦懒窥，枕书小醉睡移时。","健如黄犊时无几，钝似寒蝇老自知。","休惜飞驰春过眼，但求强健酒盈卮。","枇杷著子红榴绽，正是清和未暑时。"]},{"t":"四安道中","f":"五言律诗","c":["地平弥望水，舟稳满帆风。","黄叶新霜后，青山落照中。","封疆天象别，风俗岛夷同。","黯黯危桥夜，疏灯照闭蓬。"]},{"t":"老舅寓陈诸况不能尽布以二诗代书得閒为和佳也 其一","f":"七言律诗","c":["欲知老子居陈事，古寺萧条屋数楹。","幸免绝粮惭孔圣，更无环堵羡渊明。","参差拙句何曾是，宠辱浮云无可惊。","断送光阴须美酒，惟应此事费经营。"]},{"t":"归马二首 其二","f":"七言律诗","c":["萧萧霜鬓独惊秋，病眼天边暮倚楼。","已老冯唐犹不遇，思归庾信正多愁。","溪通积雨流方壮，山入重云翠未休。","一梦淮南经岁别，菊林还向洛阳浮。"]},{"t":"归马二首 其一","f":"七言律诗","c":["归马骎骎不受鞭，晚霞如画照晴川。","萧疏黄叶孤舟岸，零落秋云断雁天。","临水登山悲楚客，烹鸡酌酒爱诸仙。","任从老逐霜毛至，莫遣愁来玉盏边。"]},{"t":"未试即事杂书率用秋日同文馆为首句 其三","f":"五言律诗","c":["倦枕愁霜苦，晴窗宿雾开。","幕云当昼合，袍雪与风来。","元日彤庭实，春风曲水杯。","何须恋杨柳，圣世要无媒。"]},{"t":"未试即事杂书率用秋日同文馆为首句 其一","f":"五言律诗","c":["邃馆深鱼钥，华堂静锁闱。","每劳蛩作伴，不与燕同归。","古栋蜗成篆，空墙藓作衣。","寂寥还泛菊，九日莫相违。"]},{"t":"正月二十日梦在京师","f":"五言律诗","c":["客睡何展转，青灯暗又明。","春云藏泽国，夜雨啸山城。","许国有寸铁，耕田无一成。","朦胧五更梦，俄顷踏王京。"]},{"t":"正月十八日晴霁登柯眺望二首 其二","f":"五言律诗","c":["寂寂池亭古，园荒草自春。","东风独游客，迟日未归人。","久雨众山晦，初晴万境新。","长歌视天壤，高兴不无人。"]},{"t":"正月十八日晴霁登柯眺望二首 其一","f":"五言律诗","c":["柯山通细履，幽步近青红。","送目无穷浪，吹花尽日风。","馀生付沮溺，高论看夔龙。","陈许春多雪，吾行亦欲东。"]},{"t":"正月三日大雪雪晴有感","f":"七言律诗","c":["平生对雪须千首，何事今春无片词。","老大怯寒唯泥酒，穷愁须醉不吟诗。","润催庭柳将开眼，冷送江梅欲别枝。","何处高楼有残白，旧游无处寄相思。"]},{"t":"正月六日","f":"七言律诗","c":["杨柳梢头腊雪消，东风犹著晚寒骄。","新年花柳传芳信，去腊星霜变斗杓。","来共春烟情冉冉，洒随疏雨泪萧萧。","蛾眉一闭年华改，纵有遗魂可得招。"]},{"t":"永宁遣兴三首 其三","f":"五言律诗","c":["花县春曾到，人家幽谷间。","市门犹碍石，耕垄尽依山。","地僻荆榛秀，人稀鱼鸟闲。","赖逢贤令尹，沉醉不知还。"]},{"t":"永宁遣兴三首 其二","f":"五言律诗","c":["朱颜潘令尹，不肯事轻肥。","笋径青无地，苔墙绿有衣。","书勤枯简断，诗疾紫毫飞。","应笑疏慵尉，朝游暮醉归。"]},{"t":"永宁遣兴三首 其一","f":"五言律诗","c":["国破空陵墓，时移改要冲。","人随幽谷路，县隐乱山峰。","零落荒祠树，悠扬晚寺钟。","犹传仙旧隐，跨鹿有遗踪。"]},{"t":"永济桥","f":"七言律诗","c":["墟庙无人吊毁垣，故桥遗址至今存。","侵波野岸生新草，齧石老沙留旧痕。","金殿有基藏兔穴，玉舆无路半樵村。","甘棠古道轮蹄断，落日空山暮雨昏。"]},{"t":"用元韵因寄邦直","f":"五言律诗","c":["濠上昔相逢，同时执桂丛。","远游悲聚散，投老信穷通。","静见贤人节，恬知达士风。","淹留君莫叹，荣辱竟虚空。"]},{"t":"白羊道中二首 其二","f":"五言律诗","c":["日出客心喜，路平人足轻。","风高不成冷，雨过有馀清。","水落溪鱼出，村深田鹳鸣。","胜游须秀句，多愧谢宣城。"]},{"t":"白羊道中二首 其一","f":"五言律诗","c":["徒旅已屡憩，过山知几峰。","空畦鸣野水，坏道拱寒松。","醁酒自能暖，褐裘初御冬。","朝饥久未食，林寺已鸣钟。"]},{"t":"立秋后便凉诗示秬等","f":"七言律诗","c":["暑别齐纨知有日，秋生蕲竹果如期。","月明半夜似相觅，角怨五更知为谁。","风露满天河转后，江山千里雁来时。","短檠莫倦亲灯火，又见槐花黄满枝。"]},{"t":"乔木","f":"七言律诗","c":["舍北参天乔木长，依凭清荫护高堂。","鸟啼杳杳重阴合，风到翩翩翠叶凉。","已许孤高凌夏日，不妨坚老要秋霜。","投身麋鹿无人地，非尔烦忧未易忘。"]},{"t":"任左藏挽词","f":"五言律诗","c":["人也隐君子，一官聊自閒。","谁能学管库，竟尔死茅菅。","良璞不易剖，大弨终不弯。","惟应太史录，他日出名山。"]},{"t":"休日不出","f":"七言律诗","c":["久厌衣冠尘土浸，赐休何苦马骎骎。","穷冬积雪春不雨，昨日残红今绿阴。","却扫不知门外事，安禅深得静中心。","读书陶令非求解，禁酒扬雄不待箴。"]},{"t":"休日不出闻西池游人之盛","f":"七言律诗","c":["三日春风尘涨天，沟泥愁污破鞍鞯。","扫门静闭无来客，隐几深居学坐禅。","薄雨掠尘时点点，细蟾窥夜独娟娟。","都人解与残春竞，半在西池听管弦。"]},{"t":"伤春","f":"五言律诗","c":["山城夜来雨，卧病惜残春。","暗暗鸟啼树，飘飘花去人。","地偏佳客断，官冷酒钱贫。","乘兴还骑马，田家乐更真。"]},{"t":"刘景文许惠毡裘未至督之","f":"七言律诗","c":["塞上寒羊剪毡毛，软于春絮腻于膏。","齑盐倦客愁无褐，诗礼将军许赠袍。","雅服何妨冠苏帽，瘦腰兼称束郿绦。","想公封寄应多憾，不挂长身衬佩刀。"]},{"t":"同七兄及崧上人自坟庄还寺","f":"五言律诗","c":["和风快人意，岸帻晚襟凉。","日落野痕碧，月生淮际光。","论诗得灵运，静语属支郎。","不是耽閒散，从来懒性长。"]},{"t":"同无咎遐叔文叔同游凝祥得游字","f":"七言律诗","c":["客子长安尘满裘，道人门馆自深幽。","东风拂地千条柳，春水平池数点鸥。","俯首一官真底事，倒囊三百更何求。","读书挟策君知否，失性还同博塞游。"]},{"t":"同李十二醉饮王氏牡丹园二首 其二","f":"七言律诗","c":["吹尽纷纷桃李尘，天香国艳一翻新。","正过谷雨初晴日，分得西都大半春。","旧态似推新艳好，红芳不似淡妆真。","嗟予久得丘园意，何日相逢一幅巾。"]},{"t":"同李十二醉饮王氏牡丹园二首 其一","f":"七言律诗","c":["东风穷巷只埃尘，谁见城南万朵新。","不问主人聊一饮，为携佳客送馀春。","比君意气三年老，贷我疏狂一味真。","醉里尚能驰马去，看君倒著接䍦巾。"]},{"t":"同陈器之题迎福院轩","f":"七言律诗","c":["东风吹面酒楹樽，腊后一番梅柳新。","残雪作寒山向晚，横烟不动野浮春。","地留京洛豪华气，川带秦韩战伐尘。","今古悠悠君莫问，祇应沉醉是天真。"]},{"t":"同周楚望饮华园","f":"七言律诗","c":["杖藜携手踏青苔，潇洒池亭为客开。","柳色渐经秋雨暗，荷香时与好风来。","斜阳似欲妆诗句，新月邀将入酒杯。","身世已甘长寂寞，忘形赖有子徘徊。"]},{"t":"同袁思正诸公登楚州东园楼","f":"七言律诗","c":["杖藜萧飒对云沙，白首逢春只叹嗟。","身老易伤千里目，眼惊还见一年花。","地平旷野连云直，天带清淮向海斜。","尚有风光供醉笔，我生诗酒是生涯。"]},{"t":"同戚郎夜饮","f":"五言律诗","c":["云物岁将暮，风烟晚自凄。","更人初授宿，晚翼已归栖。","美酒浅深酌，新诗取次题。","亲交尽在眼，幸不费招携。"]},{"t":"同器之游大宋陂值雨","f":"七言律诗","c":["微云护日晓阴阴，春去馀芳尚可寻。","诗倚醉豪连卷写，酒逢勍敌百分斟。","山光左右双屏画，雨脚峥嵘万羽林。","沙路晚晴归马疾，一梳新月上烟岑。"]},{"t":"吕郡君挽词","f":"五言律诗","c":["表海东侯长，分吴异姓王。","世家端作合，华裔远相望。","龙去孤神剑，雏成九凤凰。","多情潘散骑，悼逝足文章。"]},{"t":"寺西閒步","f":"五言律诗","c":["闾里静无事，野塘春水生。","好风时独立，芳草共闲行。","闰月迟春候，轻阴弄晚晴。","邻炊烟火动，下舍晚鸡鸣。"]},{"t":"岁暮","f":"五言律诗","c":["岁暮无聊客，端居如坐禅。","薄霜犹衣裌，多雨急收田。","落日乌鸢集，晴林橘柚悬。","已无轩冕念，岑寂度残年。"]},{"t":"岁暮书事十二首 其十二","f":"五言律诗","c":["云去暮天迥，雁飞寒夜长。","姮娥守孤月，青女恨连霜。","不寐看银烛，长吟送羽觞。","山炉与石鼎，伴我老他乡。"]},{"t":"岁暮书事十二首 其十一","f":"五言律诗","c":["日落擎明烛，一杯千里心。","骄儿惊醉舞，山仆怪悲吟。","谷冷水流急，天昏云起阴。","三更何处雁，急急尚哀音。"]},{"t":"岁暮书事十二首 其十","f":"五言律诗","c":["陈叶不肯堕，冻醪凝未融。","寒林晴有影，霜日冷无风。","许国片心壮，劳生双鬓蓬。","功名任愚智，万事古今同。"]},{"t":"岁暮书事十二首 其九","f":"五言律诗","c":["千载伤顽俗，遗风耿未忘。","陈荒丘击鼓，魏褊女缝裳。","远客防猜嫉，官居备寇攘。","妻儿怪多喜，清洛有归艎。"]},{"t":"岁暮书事十二首 其八","f":"五言律诗","c":["自昔周人俗，贪庸巧治生。","千金不冠带，一饮起纷争。","佩犊攻攘敚，通书为姓名。","二南分陕化，寂寞久无声。"]},{"t":"岁暮书事十二首 其七","f":"五言律诗","c":["壮心常许国，平日讨论兵。","天地身将老，山河意欲惊。","病多缘痛饮，吟苦更伤情。","斗酒新丰市，何人问马生。"]},{"t":"岁暮书事十二首 其六","f":"五言律诗","c":["北风吹马疾，石径上危基。","野俎饱貆脯，山炉煮橡糜。","寒耕敲冻石，猎火上风枝。","留滞亲麋鹿，多惭发欲丝。"]},{"t":"岁暮书事十二首 其五","f":"五言律诗","c":["原庙依冈起，传闻世祖营。","南阳无雊雉，熊耳合投兵。","霜日蓬原路，天风柏殿声。","山川英气在，不负昔闻名。"]},{"t":"岁暮书事十二首 其四","f":"五言律诗","c":["牛羊已归去，残照满山陂。","霜雁田中静，风鸢木杪悲。","川原今自若，龙虎昔交驰。","丘陇耕桑尽，千年不复知。"]},{"t":"岁暮书事十二首 其二","f":"五言律诗","c":["清洛鱼梁浅，霜鳞素鲫肥。","供厨调鼎快，充腹此羹稀。","老去只便饱，年来甘息机。","寒江鲈鲙美，怅望未成归。"]},{"t":"岁暮书事十二首 其一","f":"五言律诗","c":["岁晏北风疾，山空万谷号。","木枯随意折，鸿断不成高。","深屋支蓬户，温炉煖缊袍。","老夫原不寐，鸣竹鼓萧骚。"]},{"t":"岁暮书事十二首 其三","f":"五言律诗","c":["风捲尘沙白，云垂雪意凝。","夜山时叫虎，晚市早收灯。","园栗炮还美，村醪醉不能。","三年官况味，真是冷于冰。"]},{"t":"岁暮福昌怀古四首 其一 谷州故城","f":"七言律诗","c":["原北荒城旧谷州，文皇功业莽悠悠。","天戈挥去开东夏，金甲归来献二囚。","想像英姿辉日月，苍茫故国委林丘。","山川惨惨空回首，落日悲风蔓草秋。"]},{"t":"岁暮福昌怀古四首 其二 张子房","f":"七言律诗","c":["谋臣何处不知名，谁与留侯敢抗衡。","筹下兴亡分楚汉，幄中谈笑走韩彭。","惧诛老将争枭首，高卧成功更养生。","戡乱直须希世哲，乘时儿女漫纵横。"]},{"t":"岁暮福昌怀古四首 其三 李贺宅","f":"七言律诗","c":["少年词笔动时人，末俗文章久失真。","独爱诗篇超物象，祇应山水与精神。","清溪水拱荒凉宅，幽谷花开寂寞春。","天上玉楼终恍惚，人间遗事已埃尘。"]},{"t":"岁暮福昌怀古四首 其四 连昌宫","f":"七言律诗","c":["欲问兴亡已惨颜，桑田沧海变人间。","无情野水青春在，不动南山白日閒。","伐木清溪寒剥啄，鸣禽高柳晓缗蛮。","蛾眉皓齿终黄土，谁道仙宫有使还。"]},{"t":"戏二潘","f":"五言律诗","c":["眊氉柯山客，还家只醉眠。","桂堂浑忘却，蝉室故依然。","未用临书卷，聊须办酒钱。","所欣家有弟，乡校首称贤。"]},{"t":"戏同小儿作望南京内门","f":"七言律诗","c":["别都制度拟王畿，双阙岧峣望太微。","万乘旂常难望幸，九天楼观自相辉。","百年龙虎兴王气，万雉金汤却敌威。","一梦江南尚淹泊，风尘似欲变征衣。"]},{"t":"早春","f":"七言律诗","c":["辉辉暖日弄游丝，风软晴云缓缓飞。","残雪暗随冰笋滴，新春偷向柳梢归。","可怜鬓发蹉跎老，每惜梅花取次稀。","何事都城轻薄子，买欢酤酒试春衣。"]},{"t":"早秋感怀","f":"五言律诗","c":["永日付悠悠，年华逝不留。","风声送残暑，云色淡新秋。","吾道倘有待，穷通宁遽忧。","朝来望清颍，一雁下汀洲。"]},{"t":"早起观雨","f":"七言律诗","c":["雨叶风枝日夜长，东园秾密欲生光。","可怜积雨过初暑，更转馀寒作晓凉。","蚕事已成家媪喜，麦畦初泼老农忙。","綵丝结缕催端午，又见黄头鼓楫郎。"]},{"t":"早起偶成","f":"五言律诗","c":["枕席清如水，萧然一老僧。","鸡声消壁月，晓日失窗灯。","山叶寒逾响，江云薄易凝。","老僧曾教我，任运且腾腾。"]},{"t":"早登望嵩楼望少室雪畏风不敢招客","f":"七言律诗","c":["临汝城中春雪消，望嵩楼上对岧峣。","已披氛雾呈孤秀，未许春寒上泬寥。","子晋玉笙如不隔，浮丘仙袂欲相招。","便思唤客同清赏，苦畏春风入敝貂。"]},{"t":"次韵孔舍人曝书","f":"五言律诗","c":["图书陈秘奥，樽俎肆雍容。","玉殿朝回客，蓬山深处峰。","探囊图轴旧，题壁姓名重。","盛世年年事，新篇莫厌供。"]},{"t":"次韵王敏仲池上","f":"七言律诗","c":["春晚馀芳尚可寻，晴雷沙岸走车音。","苑分广乐和声度，池受晴天倒影深。","席上宫花辉御醴，坐中琼树间瑶林。","归人自畏严城鼓，却望桥西日未沉。"]},{"t":"次韵王敏仲至西池会饮","f":"七言律诗","c":["圣朝无复用舟师，戏遣艨艟插戟枝。","沸浪有声黄帽动，春风无力彩旗垂。","不胜杯酌宁辞醉，传语风光共此嬉。","远比永和真继轨，临摹茧纸看他时。"]},{"t":"次韵邠老见贻","f":"七言律诗","c":["已嗟肮脏倚门边，况复归来灶不烟。","观国未书攀桂籍，还家却上过淮船。","瑰奇难售真当尔，凿枘相遭亦偶然。","未死此生谁料得，且将见在斗尊前。"]},{"t":"次韵张公远二首 其二","f":"七言律诗","c":["平淡春云捧额浮，秋光剑戟近人流。","无肠可断方为憾，有药能治不是愁。","可待挑琴知有术，未传驱豆更无谋。","遥知添得春窗梦，尤在樽前烛下羞。"]},{"t":"次韵张公远二首 其一","f":"七言律诗","c":["襄王坐上微词客，子建车前步水妃。","瞥过低鬟流盼处，争先含笑独来时。","东边日下终无雨，阙上书时合有碑。","肠断吴王烟水国，扁舟何日逐鸱夷。"]},{"t":"次韵李晋裕教授九日见赠","f":"七言律诗","c":["满酌聊酬菊蕊黄，登高仍在太山阳。","笑谈佳节宾朋集，诗酒清欢兴味长。","倦客得閒聊欲饮，老人虽醉不成狂。","先生莫叹齑盐久，行见高才颖出囊。"]},{"t":"次韵李德载见寄","f":"七言律诗","c":["头颅幸获免奸锋，甘分江湖老钓篷。","老得一州聊自慰，相望千里与谁同。","已欣台省登群俊，犹数湖湘卧病翁。","诗就醉馀频走笔，待观云海戏群鸿。"]},{"t":"次韵和王彦昭九日湖园会饮","f":"五言律诗","c":["故人怜寂寞，九日共登临。","天地客行远，山河秋已深。","狂来能醉舞，兴罢独悲吟。","莫怪凄凉甚，多忧损壮心。"]},{"t":"次韵秦七寄道潜","f":"七言律诗","c":["衰疲久厌五更朝，每愧冥鸿在泬寥。","顾我尘冠彫旧鬓，爱君山桂长新条。","文词画虎工逾拙，世味春冰老益消。","只欲归依香火社，高堂时听法音潮。"]},{"t":"次韵寄赵伯坚二首 其二","f":"五言律诗","c":["相思何处望，月阁对南堂。","念子犹记我，怀君时举觞。","可能思颍好，端是种花忙。","閒说河阳政，佳哉副所望。"]},{"t":"次韵寄赵伯坚二首 其一","f":"五言律诗","c":["西湖望中潬，能有几多程。","问讯懒不讲，篇章来愈清。","为邦循旧政，把酒忆交情。","祝子过新岁，春风入帝城。"]},{"t":"次韵盛居中夜饮","f":"七言律诗","c":["吴衣厌拂洛阳尘，梦寐一樽淮海滨。","每愿脱巾常漉酒，况逢投辖苦留宾。","苍龙挂斗寒垂夜，翡翠浮花暖作春。","上界高真足官府，追随却属散仙人。"]},{"t":"次韵黄汝器与君谟唱和三首 其三","f":"七言律诗","c":["爱君退易似前贤，投劾归来不待年。","世故饱谙真昨梦，道心不系学虚船。","莫悲白雪凋玄鬓，自有丹砂暖寸田。","两郡诗筒屡传寄，主盟骚雅定谁先。"]},{"t":"次韵黄汝器与君谟唱和三首 其二","f":"七言律诗","c":["吴门韦白旧推贤，文雅相望数百年。","千里江山留醉墨，五湖风月纵归船。","书来远慰连镮梦，岁熟归收种秫田。","仕禄及亲身早退，高名荣事更谁先。"]},{"t":"次韵黄汝器与君谟唱和三首 其一","f":"七言律诗","c":["饮量平吞叔度陂，宣城风月旧相知。","雪霜欺客凋新鬓，珠玉投人出好诗。","门对洞庭书满架，饮翻云梦酒盈卮。","江城少驻还乡棹，一伴山翁醉习池。"]},{"t":"次韵斯举送岩桂新酿","f":"五言律诗","c":["丛桂仙君子，小山幽处芳。","□□□鄙素，汉殿略涂黄。","有客怜衰病，新醅许撇尝。","并将尘外物，助我北窗凉。"]},{"t":"江亭别故人","f":"七言律诗","c":["津亭把酒燕西东，无复馀花一点红。","农事一春荒积雨，长淮千里驾东风。","休谈世事循环外，且寄骚愁醉眼中。","船鼓已鸣篙缆起，客行何事亦匆匆。"]},{"t":"竹堂","f":"七言律诗","c":["谁道清贫守冷官，绕家十万翠琅玕。","直应流水深相与，不待清风已自寒。","学得凤鸣真自许，化成龙去不终蟠。","知君何世无来者，可是王郎独与欢。"]},{"t":"老舅寓陈诸况不能尽布以二诗代书得閒为和佳也 其二","f":"七言律诗","c":["浮生已老付悠悠，未免饥寒目下忧。","全仗黄庭能却老，那堪白发更悲秋。","所欣耳界常清净，渐放心君得自由。","垒块苦消消未尽，每逢风月亦閒愁。"]},{"t":"耒将之临淮旅泊泗上属病作迎候上官不敢求告比归尤剧疏拙无以自振但自悯叹耳","f":"七言律诗","c":["谋身不解免飘蓬，零落孤舟西复东。","双鬓虽青应早白，病颜更醉不成红。","崎岖避俗人难合，憔悴多愁疾易攻。","莼菜碧鲈秋正美，步兵终欲向江东。"]},{"t":"自巴河至蕲阳口道中得二诗示仲达与秬同赋 其二","f":"七言律诗","c":["浩浩浑流卷白沙，中流鼓棹四无涯。","喜逢山色开眉黛，愁对江云起炮车。","雨足郊原丰稻菽，日斜鸥鹭满蒹葭。","长年怕作扁舟客，赖有高谈一笑哗。"]},{"t":"自海至楚途次寄马全玉八首 其八","f":"七言律诗","c":["紫蟹双螯荐客盘，倾来不觉酒壶乾。","雨多泽国蒲鱼美，秋至楚天风露寒。","老去论交嗟我晚，尊前一笑忆君欢。","红莲幕下无书檄，剩寄新诗满卷看。"]},{"t":"自海至楚途次寄马全玉八首 其七","f":"七言律诗","c":["二年海角寄东城，岁久移居亦有情。","去路山川嗟我远，旧时风月为谁清。","一廛受地今难继，三径怀归久欲耕。","何日山林有茅屋，百年无复问功名。"]},{"t":"自海至楚途次寄马全玉八首 其六","f":"七言律诗","c":["萧萧晚雨向风斜，村远荒凉三四家。","野色连云迷稼穑，秋声催晓起蒹葭。","愁如夜月长随客，身似飞鸿不记家。","极目相望何处是，海天无际落残霞。"]},{"t":"自海至楚途次寄马全玉八首 其五","f":"七言律诗","c":["少年居士正安禅，法是怀公门下传。","已解出尘金里矿，何妨离欲火中莲。","苦心参道嗟予晚，极口随机恃子怜。","若许维扬傍仁里，一廛须买许行田。"]},{"t":"自海至楚途次寄马全玉八首 其四","f":"七言律诗","c":["生涯飘泊一航轻，浩荡晴川送我行。","北望山川连海远，南来风月近淮清。","人家稻熟丰年满，泽国天高秋意生。","惟有羁愁消不得，登临清泪落如倾。"]},{"t":"自海至楚途次寄马全玉八首 其三","f":"七言律诗","c":["高城欲去更徘徊，病眼登临强一开。","风物尽为愁里景，山川疑是梦中来。","此身双鬓何劳白，未老尘心可得灰。","欲把烦愁付杯酒，祇应清梦待尊罍。"]},{"t":"自海至楚途次寄马全玉八首 其二","f":"七言律诗","c":["萧萧柳岸野风秋，虹挂前山晚雨收。","回首孤城空绿树，满川斜日放归舟。","年来双泪供愁尽，去去劳生几日休。","试问故人思我否，梦魂犹在海边州。"]},{"t":"自海至楚途次寄马全玉八首 其一","f":"七言律诗","c":["迂疏怀抱独君知，杖拂亲依即我师。","一句未能参妙道，数篇空复寄新诗。","子方奋迅云间翮，我厌追随世上儿。","安得岩坰两如志，铜瓶乌几为君携。"]},{"t":"至日有感二首 其二","f":"七言律诗","c":["一卧孤村两见冬，独搔华发思无穷。","荒山极目漫汗雪，老树当庭昼夜风。","佳节妻儿具樽酒，茅斋斟酌慰愁翁。","未央晓贺瞻天冕，正在炉烟缥缈中。"]},{"t":"至日有感二首 其一","f":"七言律诗","c":["两逢至日惊身老，远寄周南览物悲。","佳节风烟长惨惨，他乡人物自熙熙。","荆榛崤渑秦关破，草树芳华隋苑隳。","怅望高歌一回首，兹辰尊酒莫相违。"]},{"t":"至安化驿先寄淮阳故人","f":"五言律诗","c":["萧条安化驿，倦客思悠哉。","积水连天阔，青山送客来。","疏篱风捲叶，败屋雨生苔。","寄语淮阳旧，人今放逐回。"]},{"t":"舟中晓思","f":"五言律诗","c":["树色未啼鸟，桨声初度航。","客灯青映壁，城角冷吹霜。","飘泊年来甚，羁游情易伤。","年丰清颍尾，吾计亦差良。"]},{"t":"观洛涨","f":"七言律诗","c":["雨锁山川昼不开，洛波一夕涨如催。","西来势蹴诸山动，东转声包厚地回。","一片晓光吴阵甲，万桴南响会稽雷。","何人共此乘桴志，直到蓬瀛亦壮哉。"]},{"t":"访人汴上有感","f":"七言古诗","c":["万尾鳞鳞汴岸舟，汴流日夜去悠悠。","舟行水去常如旧，世事纷纷何日休。","落日昏昏沙际晚，白云片片碧天秋。","□□□□□□□，□□□□□□□。"]},{"t":"过孝感县十里所望一土山下有渔舟呼之不来委舟负鱼径去不顾俄有一舟不待呼自拿舟直前取舟中美鱼致之求价甚贱予倍与之值卒辞倍值而去予语之曰尔不待招而赴人之求仁也售不求厚价廉也子岂有道者乎兹楚境也昔有劝屈大夫以餔糟啜醨者岂非子耶为作一篇","f":"五言律诗","c":["有道隐屠钓，仁廉非偶然。","倾筐出紫鳜，挥手谢青钱。","昔有离骚客，名高楚国贤。","独醒遭尔笑，吾幸醉终年。"]},{"t":"过泗州推官王永年致仕还乡王年四十而致仕士大夫所少也","f":"七言律诗","c":["为忆田园便拂衣，休官退勇似君稀。","尘埃摆脱青衫去，闾里惊嗟白发稀。","南亩稻粱仍岁熟，旧山芝朮入秋肥。","百年从此皆閒日，寄语人间浪是非。"]},{"t":"齐安今秋酒殊恶对岸武昌酒可饮故人潘主簿时惠双榼","f":"七言律诗","c":["军城晓鼓已蓬蓬，城下秋云卷暮江。","祇有老鸡能换卧，更无佳客可倾缸。","冲风时动萧萧叶，晚日斜窥寂寂窗。","犹喜江南有佳客，怜贫时致玉壶双。"]},{"t":"齐安食蒌蒿根菊茁","f":"七言律诗","c":["故园蔬甲又逢春，想见雕槃巧斗新。","强掘蒌根槃郁屈，故挑菊茁嚼芳辛。","春来小疾妨杯切，老去怀乡役梦频。","堪笑吴伧恋莼鲙，素衣愁化洛阳尘。"]},{"t":"何处春深好二首 其二","f":"五言律诗","c":["何处春深好，春深居士家。","荒园几畦菜，环堵数株花。","自蜡登山屐，仍驱下泽车。","时时客问字，醉帽任倾斜。"]},{"t":"何处春深好二首 其一","f":"五言律诗","c":["何处春深好，春深禅宿家。","茶炉寒夙火，佛案晓添花。","坏宅无妖火，通途有宝车。","院深人不到，幡影逐风斜。"]},{"t":"初入试院","f":"七言律诗","c":["莫叹匆匆襆被行，赖逢数子美如英。","已看明月同为客，应犯初寒复入城。","白日有书追睡思，青灯无梦听秋声。","直无剔甲逍遥地，几日疑公太瘦生。"]},{"t":"初秋对雨","f":"五言律诗","c":["闭户理残编，疏慵得自便。","朝凉清病思，秋雨对高眠。","屋冷深藏燕，槐疏混抱蝉。","所欣堂下菊，芳意已鲜鲜。"]},{"t":"别外甥杨克一二首 其一","f":"五言律诗","c":["东南秋雨足，泽国水连天。","日出数声雁，风高何处船。","寒菹初获韭，野饷屡烹鲜。","吾事无淹速，悠悠得醉眠。"]},{"t":"即事","f":"五言律诗","c":["雨蘖生朝菌，秋墙长若邪。","槐榆蔽穷巷，藜藋接邻家。","但愿好事酒，无劳长者车。","御冬须旨蓄，吾亦问生涯。"]},{"t":"县斋","f":"七言律诗","c":["只合门如野叟家，市朝声利苦喧哗。","但知得醉频沽酒，何处逢春不见花。","暗树五更鸡报晓，晚庭三叠鼓催衙。","知君宰邑端无事，吟笑何妨到暮鸦。"]},{"t":"孝感县","f":"五言律诗","c":["萧索江干县，林端见客樯。","山川错吴楚，人物混荆杨。","风略寒芦阵，云迷夕鸟行。","故乡同见月，谁记白头郎。"]},{"t":"寿安怀古","f":"七言律诗","c":["萧王积甲事空传，子晋吹笙去不还。","千里荒芜山色在，百年兴废水声间。","雉飞陇麦新耕地，花落丛祠旧战关。","旅宦远游仍吊古，苦无樽酒奈愁颜。"]},{"t":"寿阳楼下泊舟有感","f":"七言律诗","c":["寿阳楼下清淮水，帆去帆来何日休。","浮世十年多少事，风烟依旧别离愁。","楼头夜静行人绝，楼下影斜淮月秋。","不道孤吟不能寐，一声羌笛怨谁舟。"]},{"t":"张夫人挽词","f":"五言律诗","c":["世德簪缨贵，家风孝友传。","承夫知不忌，爱子故亲贤。","飘忽人间梦，生平物外缘。","诸天清净报，可但閟重泉。"]},{"t":"李少卿挽词","f":"五言律诗","c":["青云旧驰誉，白发早辞荣。","谈笑惟诗酒，交游尽老成。","支离病中见，潇洒旧时情。","已矣不可问，九原松柏声。"]},{"t":"李处道都曹丈挽词","f":"五言律诗","c":["凄凉正始后，尚复有斯人。","恸哭亦云已，伤心难重陈。","传家双令器，怀德万遗民。","尚想典刑在，萧然老鹤身。"]},{"t":"李赞皇画像","f":"五言律诗","c":["管乐久寥阔，兴王一士多。","平生自龙虎，功业在山河。","公子悲黄犬，骚人赴汨罗。","当年阅川恨，流落复如何。"]},{"t":"沟泥二首 其二","f":"五言律诗","c":["不嫌泥潦巷，自扫寂寥居。","雨已标新杏，春犹遗老樗。","风光习暖事，云物或寒除。","颇复撩诗句，时时漫与书。"]},{"t":"沟泥二首 其一","f":"五言律诗","c":["沟泥不可步，况复雨清晨。","下直休半日，闭门闲晚春。","著书聊尔耳，隐市笑徒云。","买酒待新月，奈兹千里云。"]},{"t":"泛江偶成","f":"五言律诗","c":["扁舟漾寒水，暂使客心清。","天与秋阴合，江连野色平。","洪波回赤壁，苍野带孤城。","更想孙郎战，临风动壮情。"]},{"t":"芳华阁","f":"七言律诗","c":["玉仗无踪辇路摧，旧名犹得榜高台。","月斜晓树鸣鹎鵊，日暖春芜放雉媒。","清洛夜声萦谷转，锦屏晴色照人来。","悽凉满眼兴亡恨，谁是芜城作赋才。"]},{"t":"近清明二首 其二","f":"五言律诗","c":["冉冉春向老，昏昏日复斜。","鲜欢常止酒，不睡更烹茶。","幡起烟中刹，鸡鸣林外家。","陈王斗鸡道，风柳不胜斜。"]},{"t":"近清明二首 其一","f":"五言律诗","c":["斜日去不驻，好风来有情。","江城过风雨，花木近清明。","水树閒照影，山禽时引声。","吾年行老矣，淹泊蹇何成。"]},{"t":"连昌宫","f":"七言律诗","c":["长安王气已消磨，吊古遗墟恨怆多。","宫殿成尘新草木，丘陵无主故山河。","雨馀耕陇寻遗宝，夜静溪泉响细波。","才子已销泉下骨，百年独讽旧时歌。"]},{"t":"迟日","f":"五言律诗","c":["迟日花光乱，东风酒浪深。","天边为客恨，老去惜春心。","起舞狂犹在，悲歌病不禁。","高楼见千里，不醉莫登临。"]},{"t":"陈履常惠诗有曾门一老之句不肖二十五岁谒见南丰舍人于山阳始一书而褒与过宜阳有同途至亳之约耒以病不能如期后八年始遇公于京师南丰门人惟君一人而已感旧慨叹因成鄙句愿勿他示","f":"七言律诗","c":["南丰冢木已萧萧，犹有门人守一瓢。","文彩自应传壶奥，典刑犹可想风标。","纷纷但见侏儒饱，寂寂谁歌隐士招。","十载敝冠弹未得，簪缨知复为谁彯。"]},{"t":"驱马","f":"五言律诗","c":["骎骎驱马去，秋晚思悠哉。","日暖禾黍熟，霜晴鸿雁来。","晚篁经雨出，幽菊犯寒开。","官冷无拘束，寻山首易回。"]},{"t":"京师废宅","f":"七言律诗","c":["当道朱门白昼扃，高堂歌吹久无声。","古窗积雨昏残画，朽树经阴长寄生。","门下老人时洒扫，旧时来客叹平生。","艳姬骄马知何处，独有庭花春正荣。"]},{"t":"依韵和范三登淮亭","f":"七言律诗","c":["身如客雁寄汀洲，北望休登王粲楼。","残雪朔风惊岁晚，早梅新柳动春愁。","免遭斤斧甘无用，敢向波涛较善游。","奔走尘埃欲归去，勒移恐作故山羞。"]},{"t":"依韵和晁十七见招之什","f":"七言律诗","c":["断送春光酒万壶，敢辞羸马为君驱。","桑田日暖鸠呼妇，杨柳叶深莺哺雏。","诗冷有情寻水石，年丰无盗起萑蒲。","河阳潘令风骚客，醉倒樽前许我无。"]},{"t":"依韵奉酬慎思兄夜听诵诗见咏之作","f":"七言律诗","c":["昔遇晁公淮水东，士衡已听语如钟。","五车讲学知无敌，十载论文喜再逢。","古匣剑光疑鬼泣，夜天虎啸有风从。","许侯破的由来事，杜老裁诗晓墨浓。"]},{"t":"卧病月馀呈子由二首 其二","f":"七言律诗","c":["风叶鸣窗已复朝，唤回归梦故山遥。","酒壶暗淡浮尘集，药鼎青荧败叶烧。","闭户独依寒蟋蟀，移床近就雨芭蕉。","雪深更请安心术，长日如年未易消。"]},{"t":"卧病月馀呈子由二首 其一","f":"七言律诗","c":["蔀室悠悠昏复朝，强披庄子说逍遥。","四禅未到风犹梗，九转无功火不烧。","学道若为调鹿马，是身不实似芭蕉。","丹砂赤箭功何有，想听清言意自消。"]},{"t":"捲帘","f":"五言律诗","c":["捲帘新月上，林影散微茫。","庭草鸣虫近，风灯秋幌凉。","长年惟有病，晚岁苦多伤。","身世竟何就，吾将问蜀庄。"]},{"t":"和上维道祈雨有应","f":"七言律诗","c":["江乡长夏亢阳骄，太息秋原稻穗焦。","暑气暮收秦地火，雨声秋响浙江潮。","夜斋凉送檐间滴，晓枕清闻竹上飘。","椒醑礼神惭德薄，圣朝当宁四时调。"]},{"t":"和小雨","f":"五言律诗","c":["入夜雨声急，坐愁衾枕单。","春归千里恨，梦断五更寒。","遣兴芳樽满，惊心节物残。","山城近野水，半夜有归翰。"]},{"t":"和门下相公从驾幸学","f":"七言律诗","c":["继圣文明举旧章，儒宫传跸驻胶庠。","地疑阙里弦歌宅，经奏周书隶古行。","遣子东夷思入学，受成西旅伫来王。","鲁侯在泮犹歌诵，盛事须刊孔子堂。"]},{"t":"和见梦","f":"五言律诗","c":["青山将白发，奔走倦埃尘。","与物拙难合，惟君心独亲。","相思成夜梦，得句寄游鳞。","未得亲谈笑，书来莫厌频。"]},{"t":"和出山","f":"五言律诗","c":["晓别招提去，春风信马行。","路幽皆竹影，山远尚松声。","岭断晴天阔，川横绿野平。","不因泉石好，安觉利名轻。"]},{"t":"和北寺","f":"五言律诗","c":["寺倚苍崖古，僧閒昼掩扉。","晓云辞岭去，夕鸟占林归。","悟理观幡动，临风想锡飞。","寄怀玄观外，更觉此生微。"]},{"t":"和吕与叔秘书省观兰","f":"七言律诗","c":["千里猗猗谁取将，忽惊颜色照文房。","每怜坠露时施泽，更许光风为汎香。","独秀已先梁苑草，托根宁复楚天霜。","坐令黄菊羞粗俗，只合萧条篱下芳。"]},{"t":"和西斋","f":"五言律诗","c":["山色供开镜，溪光照掩扉。","暗虫先夜响，萎叶近秋飞。","灌垄晴蔬出，开笼暮鹤归。","鸣琴坐朗月，轻露点秋衣。"]},{"t":"和即事","f":"七言律诗","c":["溪如圆堑木如城，鱼鸟从游信此情。","啅雀踏枝飞尚袅，仰荷承雨侧还倾。","弹琴废久重寻谱，种药求多旋记名。","于世久判无妙策，直应归学老农耕。"]},{"t":"和宋二上元迎驾","f":"七言律诗","c":["拜揖清光咫尺间，彫舆欲动更移班。","蓬莱不动鳌头稳，阊阖未开天上閒。","老去一官羞简策，春来归梦满淮山。","自惭衰病独随俗，醉逐游人月下还。"]},{"t":"和应之永日","f":"五言律诗","c":["多病倦烦暑，幸兹山水幽。","惜芳悲鷤䳏，占雨听鸣鸠。","池影澄当户，山阴暮转楼。","黄昏萤点点，秋信与堪愁。"]},{"t":"和应之石涧","f":"五言律诗","c":["麦气朝含露，溪光夕照烟。","斗麋苍角老，雏雉绛毛鲜。","葵折红缯绉，莲香水麝燃。","敢辞幽僻处，直恐负林泉。"]},{"t":"和应之灯蛾","f":"五言律诗","c":["万物皆畏死，尔生何独愚。","由来附炎热，鲜不丧其躯。","浅浅权利客，跹跹轻薄夫。","高门甚烈火，相劝以奔趋。"]},{"t":"和应之细雨","f":"五言律诗","c":["朝烟和细雨，病眼暗难分。","有润物皆泽，无声人不闻。","绿连平野稼，翠杂乱山氛。","晚霁复何有，飘飘神女云。"]},{"t":"和应之雨中见怀之作","f":"五言律诗","c":["官居苦岑寂，容易过花时。","绿暗野初秀，红乾风更吹。","燕游心未展，归去意犹迟。","浩荡云山外，新诗寄我思。"]},{"t":"和应之盛夏","f":"五言律诗","c":["驱马畏炎暑，杜门常鲜欢。","吴绡朝扇薄，越布夜衾单。","饮沼山禽渴，沾泥雨果残。","二年薇与蕨，实厌野人餐。"]},{"t":"和张提举","f":"七言律诗","c":["刺举威寒江国东，自惭多病幸优容。","喜来丈室谈何妙，往拜高轩愿莫从。","宛水春生初绉縠，钟山雪尽见蟠龙。","新年强起寻芳物，零落宫梅白一重。"]},{"t":"和李令放税","f":"七言律诗","c":["晚田既废麦初耕，冠盖侵星独出城。","但见饥寒号岁晚，不闻箫鼓赛秋成。","仓无农父千斯庆，税比周人什一轻。","抚字从来须守令，莫辜圣世念疲氓。"]},{"t":"和苏仲南邵湖会饮三首 其三","f":"五言律诗","c":["新亭当绝岛，景物更清妍。","耳热风前酒，心澄水底天。","观鱼方有得，荐味肯烹鲜。","默坐吟春草，知君似惠连。"]},{"t":"和苏仲南邵湖会饮三首 其二","f":"五言律诗","c":["交友不在眼，逢君怀抱开。","主人容客醉，樽酒犯寒来。","老境侵霜鬓，羁愁付酒杯。","身闲不易得，相与且徘徊。"]},{"t":"和苏仲南邵湖会饮三首 其一","f":"五言律诗","c":["老病倦岑寂，燕游聊与俱。","开樽当胜地，飞盖渡平湖。","落日晚明灭，烟林远有无。","归来灯火夜，人影乱栖凫。"]},{"t":"和陈器之苦雨","f":"七言律诗","c":["急雨凄风未肯归，三川烟树远凄迷。","泻山涨潦千霆怒，到地重云万幕低。","扰扰泥涂同野鹜，萧萧昏晓听邻鸡。","为君一借扶摇便，静扫平郊散马蹄。"]},{"t":"和陈器之谢王渑池牡丹","f":"七言律诗","c":["十首新诗换牡丹，故邀春色入深山。","御袍黄粉天然薄，醉脸胭脂分外殷。","开晚东君留意厚，落迟晴昼伴春閒。","狂来满插乌纱帽，未拟尊前感鬓斑。"]},{"t":"和周廉彦","f":"七言律诗","c":["天光不动晚云垂，芳草初长衬马蹄。","新月已生飞鸟外，落霞更在夕阳西。","花开有客时携酒，门冷无车出畏泥。","修禊洛滨期一醉，天津春浪绿浮堤。"]},{"t":"和闻莺","f":"七言律诗","c":["冉冉东风万柳丝，啼莺常自与春期。","妆残玉枕朝醒后，绣倦纱窗昼梦时。","文羽自奇非谷隐，好音应合有人知。","风流潘令多才思，为尔春来几首诗。"]},{"t":"和晁十七昼眠","f":"五言律诗","c":["冉冉残春去，悠悠归梦赊。","窗围幽幌静，风引昼帘斜。","清荫延高柳，馀红惜晚花。","山居谙静僻，诗句是生涯。"]},{"t":"和晁应之山中","f":"五言律诗","c":["康乐虽为吏，不忘山水情。","我无连璧美，君许托车行。","幽鸟花前语，春泉竹外鸣。","勒移无草草，吾友笑功名。"]},{"t":"和得故人书","f":"五言律诗","c":["来书才一纸，离别意何长。","应为相思苦，还能细作行。","水浮新恨阔，花想旧容芳。","欲问人何处，青楼在帝乡。"]},{"t":"和葺西斋","f":"五言律诗","c":["川舟真有待，勿叹滞塘坳。","自古荆榛地，岂容鸾凤巢。","君才宜柱石，我志老衡茅。","从此延风月，新诗与细嘲。"]},{"t":"夜","f":"七言律诗","c":["木落风高砧杵伤，孤城更漏入秋长。","寒生疏牖人无梦，月过中庭树有霜。","报落梧桐犹陨叶，知时蟋蟀解亲床。","年年多病浑无寐，静对楞严一炷香。"]},{"t":"夜泊","f":"七言律诗","c":["远雁初归枫叶乾，孤舟晚系岸边滩。","淮声夜静凌风壮，月色秋深照客寒。","疏拙功名甘阔略，飘零踪迹但悲叹。","不关酒薄难成醉，自是年来少所欢。"]},{"t":"夜泊泗上阻风雨","f":"七言律诗","c":["雨昏古岸断人迹，天黑孤城闭水关。","灯火樽前初拥膝，风云淮上欲移山。","避人鱼鸟那足怪，吹浪蛟龙不自閒。","便使乘桴亦何事，沧波岁晚合知还。"]},{"t":"夜读贾长江诗效其体","f":"五言律诗","c":["五字一篇诗，人传贾岛词。","清秋千古在，幽淡几人知。","霜夜灯前读，林间静处思。","恍然如见面，更对七朱丝。"]},{"t":"夜意","f":"五言律诗","c":["每见青桐落，常虞白发侵。","伤心惟片月，不睡更清砧。","蟋蟀秋声早，银河夜色深。","崎岖无限意，萧索一长吟。"]},{"t":"夜意","f":"五言律诗","c":["荒城转五更，北斗向谁倾。","穴斗时争齧，林栖或自惊。","老来神虑淡，睡足骨毛轻。","石磬催僧粥，低窗枕畔鸣。"]},{"t":"奉议杨君予姊丈也廉静乐道不交世俗造道微妙自得不耀未六十而终予实铭其墓其子克一又纂其遗文求书卷末怀想平昔不知涕之横集也","f":"七言律诗","c":["杨君冢木已萧萧，笔墨遗文久寂寥。","堕泪交亲悲宿草，长饥奴仆守空瓢。","平生好事谁能继，后世高名骨已消。","欲酌一杯浇墓隧，遗魂楚些倘能招。"]},{"t":"官舍岁暮感怀书事五首 其五","f":"七言律诗","c":["笔床茶灶素围屏，潇洒幽斋灯火明。","木落风霜初十月，坐寒星斗欲三更。","消磨永夜书盈案，分付閒愁酒满觥。","干世愈疏身渐老，官閒何苦厌山城。"]},{"t":"官舍岁暮感怀书事五首 其四","f":"七言律诗","c":["北风吹雁去翩翩，流滞周南又一年。","田为岁荒陶令秫，酒无人乞广文钱。","香笼钵水清晨咒，坐暖蒲团后夜禅。","更谢晴明好山色，数峰残雪在檐前。"]},{"t":"官舍岁暮感怀书事五首 其三","f":"七言律诗","c":["霜菊娟娟尚有花，萧条厅树暮啼鸦。","万竿修竹开侯府，十里青山隐相家。","麋鹿并游谙野性，诗书相对是生涯。","冷官自有贫中乐，敢向朱门肉食誇。"]},{"t":"官舍岁暮感怀书事五首 其二","f":"七言律诗","c":["修竹高槐交映门，公居潇洒近山云。","醉眠多似陶彭泽，官况贫于郑广文。","秋菊捣尘供晓饵，寒松收子和香焚。","经年门巷无车马，只有清风伴此君。"]},{"t":"官舍岁暮感怀书事五首 其一","f":"七言律诗","c":["衙鼓鼕鼕送夕阳，经时无客上高堂。","渊明柳老秋多雨，子敬毡寒夜有霜。","山树叶稀晴摘果，斋炉灰煖晓焚香。","经纶自有英雄在，閒散须教属漫郎。"]},{"t":"建平途次","f":"五言律诗","c":["野桥田径滑，官路柳条新。","流水伴丽日，野花留晚春。","点空知去翼，冲绿有归人。","自笑谙岐路，无劳更问津。"]},{"t":"泊长平晚望","f":"五言律诗","c":["川隐夷犹棹，春归杳霭天。","翠深交岸树，绿野望川田。","渔酒数家市，船樯何处船。","登临一回首，无限意茫然。"]},{"t":"泊舟候水","f":"七言律诗","c":["一水悠悠断复连，卸帆终日小滩前。","青旗招饮篙工醉，五两敧风贾客眠。","树色远分芳草路，鸟行斜断夕阳天。","渔舟惯伴危樯宿，馈我霜鳞不用钱。"]},{"t":"泊舟都梁亭二首 其二","f":"七言律诗","c":["微春已动陈根绿，晴日初流大泽澌。","客路苦寒惟饮酒，老年便暖屡添衣。","霜林背日梅迟拆，冰渚知春雁早飞。","江上三年陈迹在，年年穿竹折梅时。"]},{"t":"泊舟都梁亭二首 其一","f":"七言律诗","c":["旅枕无眠客梦劳，五更旁舍一鸡号。","汴淮水阔浮梁小，城郭霜晴宝塔高。","梅锁冷香通雀啄，水翻新绿出渔篙。","君恩许作还乡客，肯对江蓠赋广骚。"]},{"t":"范参军挽词","f":"五言律诗","c":["力学志不就，多才宦可嗟。","生平叔知己，身后妇成家。","温洛新阡茂，东吴庆系赊。","功名付儿子，文史旧生涯。"]},{"t":"范忠宣挽歌二首 其二","f":"七言律诗","c":["潇湘卧病吊累沉，赐诏君王用意深。","多士方怀宣父日，苍生竟失傅岩霖。","毡裘他日瞻吾父，丹扆何人附旧箴。","白首门生恩未报，悲词空想薤歌音。"]},{"t":"范忠宣挽歌二首 其一","f":"七言律诗","c":["晚生长恨老成空，犹及风流正始中。","经国谋猷号名相，传家正直似先公。","回天巨力章犹在，拯溺深言老更忠。","谁念人心吊邦国，新阡客泣白杨风。"]},{"t":"试院即事呈诸公","f":"七言律诗","c":["天街落日走鸣珂，咫尺衡门不许过。","催去据鞍犹鹤望，争观夹道已云罗。","奏篇定有凌云赋，招隐今无扣角歌。","最苦清秋孤美睡，通宵三问夜如何。"]},{"t":"诗呈同院后至诸公","f":"五言律诗","c":["骢马嘶将近，天门报欲回。","妻孥怜别久，邻里问归来。","左学徒仍在，西城宴许陪。","腹毛何足问，奇捷看渠魁。"]},{"t":"金陵怀古","f":"七言律诗","c":["控带洪流古帝城，欲寻旧事半榛荆。","六朝山色情终在，千古江声憾未平。","设险丘陵荒蔓草，带城桑柘接新耕。","十年重到无人问，独立东风一怆情。"]},{"t":"雨中五首 其五","f":"五言律诗","c":["三日雨不止，阴云生我堂。","晓寒如腊月，冻坐忆朝阳。","过雁低薄屋，高梅飘度墙。","呼童倾一榼，独对孟光尝。"]},{"t":"雨中五首 其四","f":"五言律诗","c":["春残厌寒搅，雨多空日长。","饭馀时策杖，睡足独焚香。","芍药正酣寝，海棠浑未妆。","贤哉堂下竹，相对只苍苍。"]},{"t":"雨中五首 其三","f":"五言律诗","c":["积雨暗春色，东风还惨悽。","梅残无复笑，莺怨欲成啼。","暇日无民讼，芳时有酒携。","不辞乘兴出，病足畏深泥。"]},{"t":"雨中五首 其二","f":"五言律诗","c":["节物即自好，客心何落然。","早寒清野市，夜雨湿江天。","破屋疏茅滴，空厨湿苇烟。","政须一杯酒，相与度残年。"]},{"t":"雨中五首 其一","f":"五言律诗","c":["手种阶前树，今朝亦有花。","春阴寒食节，陋巷逐臣家。","欲酌消愁酒，先浇破睡茶。","游人归踏雨，里巷晚喧哗。"]},{"t":"青阳驿会刘伯声夜话","f":"五言律诗","c":["奔走倦尘埃，相逢颜暂开。","语阑灯烬改，饮散月华来。","行役风霜苦，流年岁月催。","我愚甘自分，惆怅子多才。"]},{"t":"青春","f":"五言律诗","c":["青春忽妍好，半岭丽朝阳。","谷鸟喜相见，园花明晓妆。","闲居耽道味，吟眺惜风光。","扣户有佳客，悠然三举觞。"]},{"t":"冒雨归饮酒","f":"五言律诗","c":["密雨集春庭，花含晓气清。","喜倾烧酒酽，更御暑衣轻。","老惜春无日，穷欣岁有成。","杖藜园径晓，坐见小池平。"]},{"t":"将至汉川夜泊","f":"五言律诗","c":["水翼飞栖定，连樯宿暝烟。","苇风惊客梦，江月伴人眠。","多病閒偏乐，苦吟愁易牵。","渔郎尔何恨，终夕独鸣舷。"]},{"t":"将至寿州初见淮山二首 其二","f":"七言律诗","c":["晚系孤舟古岸隈，蒹葭风定渚鸥回。","山兼野色苍茫去，月向淮心晃荡来。","秋色解将愁并至，年华偏与客相催。","青衫手板徒劳尔，富贵功名安在哉。"]},{"t":"将至寿州初见淮山二首 其一","f":"七言律诗","c":["浩荡平波欲接天，天光波色远相连。","风鸣雨桨初离浦，岸转青山忽对船。","泽国秋高添气象，人家南去好风烟。","步兵何必江东走，自有鲈鱼不值钱。"]},{"t":"将至海州明山有作","f":"七言律诗","c":["望望孤城沧海边，好云深处是人烟。","鸟飞山静晴秋日，水阔人閒熟稻天。","旗影远摇沽酒市，棹歌归去隔村船。","功名富贵非吾事，誓斸明山数亩田。"]},{"t":"将别普济二首 其二","f":"七言律诗","c":["孤城淮北晚钟残，落日桥边送客鞍。","物外楼台秋更豁，山深松竹晚多寒。","窗风细细侵衣冷，檐雨萧萧到夜阑。","佳境欲留嗟不可，尘埃踪迹但悲叹。"]},{"t":"将别普济二首 其一","f":"七言律诗","c":["老槐疏竹寺门幽，九月轻寒袭客裘。","漠漠淮烟天际晚，萧萧山雨坐中秋。","风前红叶知时落，篱下黄花对客愁。","为语老僧无我笑，此生终待老林丘。"]},{"t":"将赴上庠偶成","f":"七言律诗","c":["卷中课最诗成后，枕上功名睡美馀。","弟子解疑常隐几，轮人能笑久观书。","山林沉痼时搔首，松菊耽淫自荷锄。","干世可能寻一饱，齑盐未用食无鱼。"]},{"t":"屋东","f":"七言律诗","c":["苍鸠呼雨屋东啼，麦穗初长燕子飞。","竹里人家鸡犬静，水边官舍吏民稀。","溪声夜涨寒通枕，山色朝晴翠染衣。","赖有西邻好诗句，赓酬终日自忘机。"]},{"t":"幽草二首 其二","f":"五言律诗","c":["衰草已无赖，秋花只强名。","雨园蛩响细，寒树鸟啼清。","淹泊知吾道，幽居见物情。","唯应有邻叟，足雨问农耕。"]},{"t":"幽草二首 其一","f":"五言律诗","c":["幽草堂轩秀，盆池遇雨添。","新晴雀哺子，永日燕穿帘。","世事休惊目，闲中且养恬。","黄公有美酒，时得醉厌厌。"]},{"t":"怨曲二首 其二","f":"五言律诗","c":["祖席驻征桡，开帆复信潮。","隔筵桃叶泣，吹管杏花飘。","船去鸥飞阁，人归鹿上桥。","别离惆怅泪，江鹭宿红蕉。"]},{"t":"故仆射司马文正公挽词四首 其一","f":"五言律诗","c":["黼座方恭点，邦家付老臣。","颂歌民一口，形势国千钧。","富庶新田里，忠臣旧搢绅。","裴公恨不早，丘祷叹无神。"]},{"t":"故仆射司马文正公挽词四首 其三","f":"五言律诗","c":["经济心犹壮，清羸疾易伤。","那知两楹奠，遽失万夫望。","家有诗书积，坟无金玉藏。","谁知幅巾敛，曾佩上公章。"]},{"t":"故仆射司马文正公挽词四首 其二","f":"五言律诗","c":["辞爵浮云外，安民反手中。","山林独往意，衮绣太平功。","布被终身俭，貂冠一命崇。","他年两行泪，碑下泣羊公。"]},{"t":"故仆射司马文正公挽词四首 其四","f":"五言律诗","c":["伊洛平生兴，园林独乐居。","曾过郑公里，得御李膺车。","华屋当年客，名山异代书。","定知传不朽，埋玉自沾裾。"]},{"t":"春日遣兴","f":"七言律诗","c":["洛阳自古帝王都，百战荆榛只故墟。","零乱园林遗物在，嬉游人物古风馀。","草迷公子障泥锦，花近佳人油壁车。","漂泊强随游客辔，不辞尘土污衣裾。"]},{"t":"春日遣兴二首 其二","f":"七言律诗","c":["日烘烟柳软于丝，桃李成尘绿满枝。","芳草有情随处好，落花无赖信风吹。","关心伤感知何处，过眼芳菲能几时。","一病春来妨痛饮，遣愁惟有强裁诗。"]},{"t":"春日遣兴二首 其一","f":"七言律诗","c":["流光向老惜芳菲，搔首悲歌心事违。","绿野染成延昼永，辞红吹尽放春归。","荆榛废苑人閒牧，风雨空城乌夜飞。","断送一番桃李尽，可怜桑柘有光辉。"]},{"t":"春阴二首 其二","f":"七言律诗","c":["溪树昏昏锁暮云，晚山愁黛对含颦。","不甘小雪犹妨暖，长恨閒阴每占春。","宝带金貂侯第客，钿车珂马帝京尘。","王城自古繁华地，回首高歌怅望频。"]},{"t":"春阴二首 其一","f":"七言律诗","c":["漠漠重云向晚低，腊寒新去有馀威。","风捎檐滴难开幌，润引炉香易著衣。","把酒自倾金错落，探春谁污锦障泥。","山城冷落无歌舞，只有芳醪取次携。"]},{"t":"春晚有感","f":"七言律诗","c":["洛川三月鹎鵊鸣，游絮萦空尘不惊。","茸茸草色铺风软，点点杨花著水轻。","何处浮云度天末，不妨微雨破春晴。","江南有客增归思，怅望汀洲蘋芷生。"]},{"t":"春望","f":"五言律诗","c":["暖日晴薰草，清淮阔浸天。","地卑连远水，城废入春田。","目极风灯外，愁悬泪脸边。","人生苦多感，花柳自年年。"]},{"t":"春望","f":"五言律诗","c":["鸟去晴云外，帆归芳草边。","平淮分绿野，春树接低天。","残蘖寒馀烧，新青雨后田。","年来千里目，容易泪双悬。"]},{"t":"春寒","f":"五言律诗","c":["客舍逢桃李，清樽聊自欢。","梦中经夜雨，醉里度春寒。","草色远还绿，鸟声晴更繁。","预期多病眼，花发更辞看。"]},{"t":"春寒二首 其二","f":"五言律诗","c":["漠漠阴还合，迢迢日自长。","云容将雨露，山意自风霜。","栏甲青辞土，园枝笑倚墙。","薄寒能几许，春雨满池塘。"]},{"t":"春寒二首 其一","f":"五言律诗","c":["星霜残腊过，霰雪一冬频。","云重常昏昼，寒多更入春。","晚风捎翠暮，轻雨敛微尘。","满酌山樽酒，驱愁尔最亲。"]},{"t":"春暮","f":"七言律诗","c":["春尽空馀白日长，枝头青杏已堪尝。","人閒帘幕燕相语，风暖园林柳半黄。","病里不知时节换，老来都减少年狂。","残风浊酒应堪在，更遣流莺送几觞。"]},{"t":"春暮有感二首 其二","f":"五言律诗","c":["江城春雨暗，客舍夜灯明。","搆火添香炷，拥衾闻竹声。","微明旁舍火，断续远楼更。","何处离群鸟，孤飞深夜鸣。"]},{"t":"春暮有感二首 其一","f":"五言律诗","c":["午枕消暗永，春裘御晓清。","砌红多近采，园绿有深鸣。","窗破斜光入，炉消断碧横。","白头为吏苦，高卧笑浮生。"]},{"t":"昼卧怀陈三时陈三卧疾","f":"七言律诗","c":["睡如饮蜜入蜂房，懒似游丝百尺长。","陋巷谁过居士疾，春风正作国人狂。","吟诗得瘦由无性，辟谷轻身合有方。","欲饷子桑归问妇，一瓢过午尚悬墙。"]},{"t":"柘城道中","f":"五言律诗","c":["欲雪日易晚，不寒风更清。","崩桥断官路，积水入空城。","屏翳野初烧，降丘民始耕。","冬晖疾如马，汲汲暝犹征。"]},{"t":"柯山闻鹎鵊","f":"七言律诗","c":["三年不听早朝鸡，惭愧高林鹎鵊儿。","满眼山林春已去，五更风露月沉西。","厌听田舍驱牛苦，想见天门宝马嘶。","独我朦胧贪晓睡，故园门巷梦中迷。"]},{"t":"神宗皇帝挽词三首 其二","f":"七言律诗","c":["三百年成玉鼎丹，缟帷惊变紫宸班。","遗弓有泪哀何及，嘶马无踪去不还。","霜露无情金阙暗，山川常在石麟閒。","青衫曾赐当年桂，欲附龙髯不可攀。"]},{"t":"秋日","f":"五言律诗","c":["陨叶鸟不顾，枯茎虫莫吟。","野荒田已穫，江暗夕多阴。","夜语闻山雨，无眠听楚砧。","敝裘还补绽，披拂动归心。"]},{"t":"秋日忆家","f":"七言律诗","c":["汩汩流光长远客，年年秋至是离家。","孤城入夜寒更迥，霜月满天归梦赊。","摵摵老桐风后叶，娟娟疏菊雨残花。","茅檐布被犹无力，长走尘埃真可嗟。"]},{"t":"秋日游柯市","f":"五言律诗","c":["柯市渔樵暮，游人落落稀。","肩禾新穫野，炷火欲鸣机。","草木经寒雨，川原淡夕晖。","北归吾敢必，身世正多违。"]},{"t":"秋日登海州乘槎亭","f":"七言律诗","c":["海上西风八月凉，乘槎亭外水茫茫。","人家日暖樵渔乐，山路秋晴松柏香。","隔水飞来鸿阵阔，趁潮归去橹声忙。","蓬莱方丈知何处，烟浪参差在夕阳。"]},{"t":"秋兴","f":"七言律诗","c":["薄云蔽日晚悠悠，檐雨萧萧急未收。","佳树已彫今岁叶，西风还是去年秋。","蹉跎不奈时惊客，牢落惟凭酒散愁。","多病支离欣得睡，晚来凉气满衾裯。"]},{"t":"秋怀次韵晁应之三首 其三","f":"五言律诗","c":["清秋万里兴，力疾上层台。","岁熟雉兔饱，风高榆柳摧。","晚篁元自绿，幽菊为谁开。","寂寞无人问，乡书久不来。"]},{"t":"秋怀次韵晁应之三首 其二","f":"五言律诗","c":["衰鬓不堪洗，病躯先觉阴。","天寒白日短，岁暮乱山深。","薄酒醒无力，危弦奏不禁。","谋身老逾拙，三听洛阳砧。"]},{"t":"秋怀次韵晁应之三首 其一","f":"五言律诗","c":["木落晚风急，宵凉侵暑衣。","有期惟向老，无计未成归。","只益颠毛脱，还从髀骨肥。","感时仍吊古，回首意多违。"]},{"t":"秋夜","f":"五言律诗","c":["月到啼蛩壁，风摇睡鹊枝。","秋来客不寐，遥夜漏何迟。","已近风霜节，寂无蚊蚋时。","天时只自尔，浪遣宋生悲。"]},{"t":"秋雨","f":"五言律诗","c":["阶下梧桐树，芳菲亦已休。","岁时惊病客，风雨送清秋。","栖鸟归何晚，鸣虫响渐收。","萧萧寒色暮，吹作夜深愁。"]},{"t":"秋雨二首 其二","f":"七言律诗","c":["陋巷柴门掩寂寥，一窗风雨晚萧萧。","清秋渐冷尤宜懒，閒日苦长无处消。","乌几青筇扶病弱，素琴黄卷伴逍遥。","交朋南北音书隔，虽有芳樽谁可招。"]},{"t":"秋雨二首 其一","f":"七言律诗","c":["急雨凄风未肯晴，墙阴先报候虫鸣。","扫除暑气驱三伏，催促秋声向五更。","美酒若能斟靖节，二毛偏解著潘生。","醉来真有无穷意，老去何劳浪自惊。"]},{"t":"秋宫","f":"七言律诗","c":["帐额斓斑暗旧金，玉猊香重暖沈沈。","秋风宫殿梧桐老，暮雨楼台帘幕深。","银箭漏迟鸡唱晓，绮窗人睡昼生阴。","无眠惯滴班姬泪，听尽长安夜夜砧。"]},{"t":"秋晓","f":"七言律诗","c":["老人不睡秋夜长，五更鼓角鸣东堂。","悲蛩床下欲无语，黄叶瓦清新有霜。","雁声相应江南北，斗杓欲下天中央。","老人山尊有美酒，岸巾先酌一杯尝。"]},{"t":"秋晚","f":"五言律诗","c":["鸟栖林已静，门掩吏家归。","黄叶雨中尽，鸣虫霜后微。","尘凝经暑扇，貂敝早寒衣。","赖有清尊酒，山炉彻夜围。"]},{"t":"种芭蕉","f":"五言律诗","c":["幽居玩芳物，自种两芭蕉。","空山夜雨至，滴滴复萧萧。","凉叶泛朝露，芳心展夕飙。","东堂日虚静，秀色慰无聊。"]},{"t":"种圃","f":"五言律诗","c":["僦舍亦为圃，从人笑我痴。","自求佳草木，仍补小藩篱。","吾事正如此，人生聊自怡。","霜松未及尺，独我见奇姿。"]},{"t":"赴官寿安泛汴二首 其二","f":"七言律诗","c":["落泊云随宿雨开，西风似与早寒催。","晓天雁起平沙去，霜岸风鸣败叶来。","扰扰劳生移岁月，纷纷过眼旋尘埃。","求田问舍真良策，功业应须与命偕。"]},{"t":"赴官寿安泛汴二首 其一","f":"七言律诗","c":["西来秋兴日萧条，昨夜新霜缉缊袍。","开遍菊花残蕊尽，落馀寒水旧痕高。","萧萧官树皆黄叶，处处村旗有浊醪。","老补一官西入洛，幸闻山水颇风骚。"]},{"t":"赴宣城守吴兴道中","f":"五言律诗","c":["秋野连云静，三吴稻熟时。","风江客帆疾，晴野雁行迟。","草木霜天晚，山川泽国卑。","宣城不负汝，好继谢公诗。"]},{"t":"送丁秀才侍竹之邕州","f":"五言律诗","c":["五岭天南极，扁舟到几时。","山川故国远，猿鸟异乡悲。","书史传家旧，功名及壮期。","相携有佳客，莫负锦囊时。"]},{"t":"送丁宣德赴邕州佥判","f":"七言律诗","c":["邕南亭障久消兵，莫厌扁舟万里行。","岭外山川从古秀，幕中谈笑属时平。","天连涨海鹏飞近，风卷孤城飓母生。","勿为跕鸢思款段，古来男子重功名。"]},{"t":"送刘南夫赴任京师","f":"五言律诗","c":["却扫楚山根，相过唯有君。","齐年未白发，不日上青云。","送别悲秋早，伤离赖酒醺。","青衫老司马，落泪独纷纷。"]},{"t":"送江瞻道之汝阴尉","f":"七言律诗","c":["少年相见已蹉跎，千里分携可奈何。","世路险艰知子少，人间忧患属予多。","二年穷巷山阳客，一棹清风颍水波。","我为离居感身世，援琴西望独悲歌。"]},{"t":"送李公辅赴宰宣城","f":"七言律诗","c":["与君骑竹即同游，抱子相看发已秋。","莫惜往来勤马足，未须容易转船头。","君方搜句窗间岫，我已悬情天际舟。","抱椠石渠无所欲，劳君时致管城侯。"]},{"t":"送杨念行监簿侍行赴鄂渚","f":"七言律诗","c":["楚天南去水冥冥，鄂渚悠悠到几程。","京洛信稀千里隔，江湖春尽一帆轻。","莫辞送别青春满，会是相逢白发生。","饱读诗书取卿相，不应如我老无成。"]},{"t":"送复守张坰朝奉罢归","f":"七言律诗","c":["一梦西都十二年，竟陵相遇各华颠。","风流家世仁人后，恺悌歌谣楚俗传。","学道爱君甘淡薄，倦游嗟我久留连。","自怜江上伤春眼，不待琵琶已泫然。"]},{"t":"送春","f":"五言律诗","c":["莽莽平原绿，悠悠晚树红。","巢成莺哺子，柳老絮飞空。","碧草长亭路，青旂野店风。","伤心对千里，无酒奈愁攻。"]},{"t":"送徐任","f":"七言律诗","c":["白发青衫困宦游，相逢不复话封侯。","少年壮气青云上，投老生涯一醉休。","献璞谁怜藏美玉，恶声不至为虚舟。","从来满卷新诗句，写取淮天万里秋。"]},{"t":"送曹子方赴福建运判","f":"七言律诗","c":["平生邺下曹公子，家世风流合有文。","横槊尚传瞒相国，紫髯不是画将军。","诏书宽大民何怨，刺史威严吏合勤。","好作楚词更下俚，云中一降武夷君。"]},{"t":"送婿陈景初还钱塘","f":"七言律诗","c":["乃翁风节老弥坚，嗣子清修学有传。","为爱诗书贤事业，肯羞葛练拙包缠。","经年上国劳归梦，一棹寒流放去船。","饱读陈编勤笔砚，书来寄我好文编。"]},{"t":"送蔡彦规之任风泉主簿","f":"五言律诗","c":["四十曳青袍，功名晚未遭。","贤人固难进，小邑且徒劳。","秦俗讴谣口，雍州形势豪。","凭君怀古意，一一寄风骚。"]},{"t":"重九考罢试卷书呈同院诸公","f":"七言律诗","c":["回首登高行复冬，后时只合叹龙钟。","愁须白酒来酣战，诗为黄花吊不逢。","十日飞腾过眼疾，万签甲乙定谁从。","共应净扫氍毹榻，深炷炉香午睡浓。"]},{"t":"重到临淮寿圣院","f":"五言律诗","c":["陈迹不可访，旧游三十年。","相逢非故物，大半已沈泉。","世界扬尘海，浮生不系船。","老人无固必，醉即掩篷眠。"]},{"t":"钦慈皇后挽词二首 其二","f":"五言律诗","c":["淑德承明旧，徽音固有来。","据龙符圣嗣，合剑会轩台。","玉冷衣销馥，鸾昏镜集埃。","伤心国西道，寂寞送车回。"]},{"t":"钦慈皇后挽词二首 其一","f":"五言律诗","c":["畴昔熙宁盛，远同麟趾时。","内敦勤俭德，阴辅太平基。","馀烈光彤史，追荣备母仪。","遗民怀永裕，箫鼓不胜悲。"]},{"t":"闻邠老下第作诗迎之","f":"七言律诗","c":["淡墨高张动禁城，风驰电落走寰瀛。","从来万卷贮便腹，可得千人无一名。","且向江边伴逐客，会须天上冠群英。","遥思匹马千山里，孤店村深听晚莺。"]},{"t":"食薇","f":"五言律诗","c":["岁穷阴不解，短日过墙微。","幽鸟穿林小，寒乌啄树饥。","冰霜崖岭壮，烟火井闾稀。","老拙安閒僻，无心厌食薇。"]},{"t":"倚声制曲三首 其三","f":"楚辞体","c":["山未高兮水不深，此情此意薄千金。","今朝酒伴双垂泪，明夜灯前独拥衾。","玉箸异时空见迹，麈犀千里亦通心。","桃源路绝无人到，应许刘郎再访寻。"]},{"t":"倚声制曲三首 其二","f":"七言律诗","c":["不恨因缘不恨天，强持牙板向樽前。","阳关一曲动山月，别泪千行盈酒船。","薄命有情今已矣，傍人无意亦凄然。","愿君学取梁间燕，秋去春来到妾边。"]},{"t":"倚声制曲三首 其一","f":"七言律诗","c":["春丝惹恨鬓云垂，媚态愁容半在眉。","早是思深难语别，可堪肌瘦不胜衣。","眼前有恨景尤速，门外无情车载脂。","自笑不如天上月，尊前犹有见郎时。"]},{"t":"哭蔡彦规二首 其二","f":"五言律诗","c":["文章不用世，沦落掩山阿。","命也人无奈，悲哉天谓何。","至交嗟我少，双泪为君多。","遥想山阳墓，秋风吹薜萝。"]},{"t":"哭蔡彦规二首 其一","f":"五言律诗","c":["青衫未白首，已叹掩新阡。","哭别自今日，书来才去年。","功因钟鼎记，名赖友朋传。","平昔围棋笑，临枰更泫然。"]},{"t":"哲宗皇帝挽词四首 其四","f":"五言律诗","c":["七月宫车驾，西陵观阙新。","风云悲厚夜，羽卫异时巡。","落月低金爵，秋芜暗石麟。","威灵凛如在，善继有天伦。"]},{"t":"哲宗皇帝挽词四首 其三","f":"五言律诗","c":["万世兴王业，千年极治辰。","泽丘还北祭，玉检议东巡。","汗竹人间事，因山地下春。","云天不可望，髯断泣遗臣。"]},{"t":"哲宗皇帝挽词四首 其二","f":"五言律诗","c":["秦地蟠螭纽，细阳玉象光。","升歌陈备乐，信史记多祥。","夺邑公无怨，开边义侮亡。","威灵对三后，常在白云乡。"]},{"t":"哲宗皇帝挽词四首 其一","f":"五言律诗","c":["端拱循尧道，无为十六年。","偏师擒颉利，上将勒燕然。","梦损周王寿，丹催黄帝仙。","凄凉旧载笔，恸哭抱残编。"]},{"t":"庚辰腊八日大雪二首 其二","f":"五言律诗","c":["东州逢腊雪，却忆竟陵梅。","客路人方远，天涯雁欲回。","遥怜檐外白，还点砌边苔。","久是无人过，谁知照酒杯。"]},{"t":"庚辰腊八日大雪二首 其一","f":"五言律诗","c":["平生腊八日，借钵受斋糜。","客路岁将晚，旅庖晨不炊。","持杯从破律，遣兴自吟诗。","何日依禅宿，钟鱼自有时。"]},{"t":"夏日二首 其二","f":"七言律诗","c":["重云卷雨过山来，遍洒中田到晓回。","错落晴山移斗极，阴森暗峡宿风雷。","佳人夜夜齐纨恨，骚客年年鹎鵊哀。","欲见清秋近消息，月明白露湿苍苔。"]},{"t":"夏日二首 其一","f":"七言律诗","c":["诗书老去信无功，偷得閒官许养慵。","山影当庭初转日，水声穿竹自来风。","晚催萱蕊昏还敛，日射榴房午更红。","览物赋诗成底事，萧萧双鬓欲衰翁。"]},{"t":"夏日十二首 其十一","f":"五言律诗","c":["蛩怨青莎老，萤飞秋水深。","庭除延夜色，砧杵发秋心。","雄剑鸣初匣，寒衣补硬针。","老来词赋懒，从使二毛侵。"]},{"t":"夏日十二首 其十","f":"五言律诗","c":["陶令抛官易，庞公去隐深。","由来浮世事，可见昔人心。","卜筑閒多思，奔驰病不禁。","檐楹来燕雀，鸾鹤自山林。"]},{"t":"夏日十二首 其九","f":"五言律诗","c":["种药幽人事，还披本草经。","出山抛旧翠，过雨有新青。","术受壶中秘，方传肘后灵。","不辞勤服饵，为变发星星。"]},{"t":"夏日十二首 其八","f":"五言律诗","c":["久与山川约，那无风月情。","经营原阔略，疏放自平生。","山友招相见，乡书向远征。","殷勤语归计，贫苦病难成。"]},{"t":"夏日十二首 其七","f":"五言律诗","c":["谢守常搜句，陶潜亦效官。","傍溪分水细，过巘得天宽。","布种随蔬陇，寻香到药栏。","野装儿稚笑，绳屦鹿衣冠。"]},{"t":"夏日十二首 其六","f":"五言律诗","c":["养拙贫无事，深幽乐更真。","檐巢偷哺子，树啄巧藏身。","窃果莺知主，移居蚁过邻。","老夫朝食美，荐俎有溪鳞。"]},{"t":"夏日十二首 其五","f":"五言律诗","c":["细径依原僻，蓬蒿四五家。","山田来雉兔，溪雨熟桑麻。","竹笼晨收果，茅庵夜守瓜。","颇知农事乐，彼此问生涯。"]},{"t":"夏日十二首 其四","f":"五言律诗","c":["朝雨来还密，村墟一望间。","远声惟野竹，润色但青山。","书史供高卧，莓苔只闭关。","萧萧觉秋兴，飘飒近衰颜。"]},{"t":"夏日十二首 其三","f":"五言律诗","c":["山雨晴来暑，溪云暗复兴。","林塘阴不解，巾帻润还蒸。","书帙慵披蠹，盘餐厌扑蝇。","老来疲薾甚，多病日侵陵。"]},{"t":"夏日十二首 其一","f":"五言律诗","c":["过雨芰荷乱，繁阴竹树多。","雏声知鸟哺，萍动见鱼过。","细径饶苔藓，阴墙引薜萝。","角巾从倒侧，疏懒欲如何。"]},{"t":"夏日三首 其三","f":"七言律诗","c":["枣径瓜畦经雨凉，白衫乌帽野人装。","幽花避日房房敛，翠树含风叶叶香。","养拙久拚藏姓氏，致身安事巧文章。","汉庭卿相皆豪俊，不遇何妨白发郎。"]},{"t":"夏日三首 其二","f":"七言律诗","c":["黄帘翠幕断飞蝇，午影当轩睡未兴。","枕稳海鱼镌紫石，扇凉山雪画青缯。","廊阴日转雕栏树，坐冷风生玉碗冰。","满案诗书尘蠹甚，故应疏懒过炎蒸。"]},{"t":"夏日三首 其一","f":"七言律诗","c":["长夏江村风日清，檐牙燕雀已生成。","蝶衣晒粉花枝午，蛛网添丝屋角晴。","落落疏帘邀月影，嘈嘈虚枕纳溪声。","久拚两鬓如霜雪，直欲樵渔过此生。"]},{"t":"夏日杂兴四首 其四","f":"七言律诗","c":["蔬圃茅斋三亩馀，溪光山影动浮虚。","病妻老去惟寻药，稚子年来解爱书。","中散无堪心放荡，冯唐已老兴萧疏。","全真养素安吾分，敢谓轩裳不我如。"]},{"t":"夏日杂兴四首 其三","f":"七言律诗","c":["墙下溪流清且长，夹溪乔木雨苍苍。","袅风翠果擎枝重，照水圆荷舞叶凉。","蜗壳已枯黏粉壁，燕泥时落污书床。","南山野客閒相过，赠我能携药满筐。"]},{"t":"夏日杂兴四首 其二","f":"七言律诗","c":["无地从容解郁陶，寄怀林野散尘劳。","含风槐柳参天合，足雨桑麻映露高。","五斗得官迷簿领，一廛何处斸蓬蒿。","致身富贵须年少，顾我衰迟已二毛。"]},{"t":"夏日杂兴四首 其一","f":"七言律诗","c":["隔墙泉下是东溪，细溜涓涓入我池。","一部笙箫寒竹响，百年风雨古槐姿。","果悬幽槛朱初熟，蔓度空墙翠欲垂。","野趣转深身愈老，故应寂寞畏人知。"]},{"t":"挽李少卿","f":"七言律诗","c":["几年林下远埃尘，儒雅风流谁与邻。","笔尾病来犹壮健，诗情老去更清新。","幽斋昔日琴书换，新冢东风草木春。","怀想只疑高兴在，一吟遗句泪沾巾。"]},{"t":"挽黄几道","f":"五言律诗","c":["异政颍川凤，遗风叔度陂。","闻哀苦朋友，归葬束书诗。","百岁乡人社，他年故吏碑。","知公万金产，故在阿戎儿。"]},{"t":"效白体二首 其二","f":"七言律诗","c":["州贫须惜尊罍费，俗陋兼无妓乐名。","幸有蒲团供燕坐，不妨藜杖助閒行。","看炊香稻供斋饭，自采寒蔬试野羹。","身外无营内无事，近来心气尽和平。"]},{"t":"效白体二首 其一","f":"七言律诗","c":["功名富贵付悠悠，高卧山城又过秋。","燕坐香灯为静侣，閒行麋鹿是同游。","青黄草木新霜过，潇洒溪山夜雨收。","回首十年梁苑客，枉教白却少年头。"]},{"t":"效白体赠杨补之","f":"七言律诗","c":["青衫居士断荤血，一榻萧然如在山。","堂下黄花惊岁晚，尊中绿酒觉官閒。","胸中已了一事大，镜里莫惊两鬓斑。","我亦久怀伊洛兴，烦君先为卜禅关。"]},{"t":"晓作","f":"五言律诗","c":["静枕有远听，风声带晓江。","寒云垂紞紞，严鼓已逢逢。","功业惊残岁，江山隐陋邦。","寒鸡憎客梦，呼日上低窗。"]},{"t":"栾提举妻石氏挽词","f":"五言律诗","c":["和敬承夫顺，勤劬教子贤。","平生积净业，仓卒叹无年。","孤剑留耿介，九雏谁抚怜。","尘埃旧脂泽，春草掩新阡。"]},{"t":"润州书事","f":"五言律诗","c":["野蔓封城堞，疏松隔丽谯。","楼临寒汹涌，门揖翠岧峣。","客思闲易感，归心去莫招。","何时送客处，看我理归桡。"]},{"t":"病肺齿痛对雪","f":"七言律诗","c":["拥庭晴雪照高堂，卧病悠悠废举觞。","肺疾仅同园令渴，齿伤不为幼舆狂。","交飞翠斝知谁醉，独嗅乌巾认旧香。","惟有烹茶心未厌，故知淡泊味能长。"]},{"t":"破幌","f":"五言律诗","c":["破幌一点白，卧知千里明。","低窗通雪气，乔木尚风声。","传警军城静，鸣钟梵刹清。","高眠寻断梦，邻树已乌惊。"]},{"t":"离山阳入都寄徐仲车","f":"七言律诗","c":["孤城芳树碧层层，村落黄昏只见灯。","回首事如前夕梦，出门心似下山僧。","仕求行道时难偶，意欲谋閒力不能。","寄语东皋多酿酒，待予归日解行縢。"]},{"t":"离天长寄周重实","f":"七言律诗","c":["相逢握手便忘形，射策天门尽弟兄。","浮世有谁尊道义，青衫自笑为功名。","高谈未尽胸中意，作别犹如梦后惊。","半夜叩门投野寺，天寒孤月更分明。"]},{"t":"离光山驿","f":"七言律诗","c":["邮亭结束问残更，斜月西南鸡未鸣。","草草劳人常少睡，绵绵远道苦无情。","田家稔熟人情好，野路雨馀秋气清。","老得一州藏拙去，鹓鸾台阁尽豪英。"]},{"t":"离陈至华西","f":"五言律诗","c":["落日照原隰，晚风吹客鞭。","空巢霜后木，残蘖烧馀田。","憔悴贫中客，苍茫岁暮天。","远游轻道路，无地息劳肩。"]},{"t":"离建雄涂中","f":"五言律诗","c":["远水悠悠静，孤樯袅袅迟。","草深春已后，麦秀日长时。","聚语条桑妇，行歌拾穗儿。","年丰随处乐，飘泊我何为。"]},{"t":"离宿州后寄兄弟","f":"七言律诗","c":["落日村桥涕泫然，东风匹马去翩翩。","两行绿树当隋岸，一片春云限楚天。","妄意致身常许国，强颜得禄废求田。","幅巾会作淮南叟，白发相收一钓船。"]},{"t":"离富池望庐岳是日入夹口直达浔阳遂舍大江之险示同行","f":"七言律诗","c":["山秀江清三百里，与君三宿一扁舟。","饮残桑落溪云暮，卧冷桃笙楚雨秋。","舟隐长江逢夹口，眼明五老立云头。","几年泽国行将遍，归与亲朋说旧游。"]},{"t":"离楚夜泊高丽馆寄杨克一甥四首 其三","f":"五言律诗","c":["客去水关闭，疏灯亦复收。","川鸣半夜雨，卧冷五更秋。","扁舟已寒暑，冉冉真乘桴。","一灯照客睡，短梦良悠悠。"]},{"t":"离蕲阳守风林皇方虑风壮晚未知所止俄顷风息一食顷宿富池作诗示同行","f":"七言律诗","c":["老怕风波见辄惊，赖逢谈笑慰危情。","纵观云岭屏风合，坐见江涛镜面平。","淹速人生难预计，险夷世路不须营。","尘埃老作东州守，得得扁舟作此行。"]},{"t":"秦兵部书堂","f":"五言律诗","c":["丈人怜我厚，许与过常情。","身世已迂阔，功名何敢争。","笑谈忘晚辈，樽俎罄生平。","欲斸临淮地，从公老此生。"]},{"t":"读孙巨源经纬集","f":"七言律诗","c":["等閒咳唾烂成文，奏牍三千世共珍。","不向人间调鼎鼐，却归天上作麒麟。","侍游曲水欢何在，敷奏延英迹已陈。","四辅当时曾避柱，熙宁天子属词臣。"]},{"t":"读黄鲁直诗","f":"七言律诗","c":["江南宿草一荒丘，试读遗编涕不收。","不践前人旧行迹，独惊斯世擅风流。","一尊华发江边客，万里黄茅岭外州。","虎豹磨牙九关邃，重华可诉且南游。"]},{"t":"都梁夜景","f":"七言律诗","c":["浩浩黄流注渺漫，南山峰岭对巑岏。","青灯覆地严城夜，白月当天淮上寒。","酒市歌呼迷客醉，画楼灯火暗更残。","扁舟老客无馀事，拥褐高眠夜未阑。"]},{"t":"都梁亭下","f":"五言律诗","c":["金塔青冥上，孤城苍莽中。","浅山寒带水，旱日白吹风。","人事剧翻手，生涯真转蓬。","高眠待春涨，鲑菜伴南公。"]},{"t":"都梁雪天晚望","f":"七言律诗","c":["浮梁淮面欲飞腾，金碧浮屠间玉层。","古岸萧条风捲雪，长河咽绝水浮冰。","留连淮汴残年客，蹭蹬尘埃一老僧。","闻道都梁梅未拆，可随桃李畏严凝。"]},{"t":"钱仲珣追船及陈留","f":"七言律诗","c":["野岸南风百草长，沄沄汴水卷沙黄。","扁舟转柁迷城市，送客追船罗酒浆。","休唱阳关伤远别，所欣莼菜入新堂。","宦名衰晚君无问，便得封侯鬓已苍。"]},{"t":"偶成","f":"五言律诗","c":["却扫客不至，端为四国骚。","杯寒荐园实，食俭煮溪毛。","霜过橘柚熟，天晴鸿鹄高。","幽斋高木近，不寝听鸡号。"]},{"t":"偶成二首 其二","f":"五言律诗","c":["绿遍长安树，春归空隔年。","愁多落花地，情远倚楼天。","河汉昆崙外，苍龙北极天。","老知玄有味，羞更赋神仙。"]},{"t":"偶成二首 其一","f":"五言律诗","c":["鸟啼宫直散，归舍日犹长。","暗树残春绿，回风欲雨凉。","久知痴有绝，端为酒成忙。","可是嘲须解，平生一漫郎。"]},{"t":"偶成题裴晋公祠","f":"七言律诗","c":["独持将钺静氛妖，后世英名日月昭。","善听圣君非易遇，将亡凶竖不难枭。","悲风蔓草移今古，野殿空庭锁寂寥。","更有从军老司马，铭功文字配咸韶。"]},{"t":"宿马庄寺","f":"七言律诗","c":["冲泥我马僵欲仆，空村落日不逢人。","开门野寺净如扫，迎客老僧閒更真。","佛案青黄园果细，斋厨汲洗野蔬频。","年来到处无馀念，静对同龛金色身。"]},{"t":"宿东鲁父居二首 其二","f":"五言律诗","c":["郡国何时极，羁愁触处生。","望随天不尽，春共野兼平。","烟树淮南阔，渔盐楚俗轻。","飘零五年别，叹息鬓毛更。"]},{"t":"宿东鲁父居二首 其一","f":"五言律诗","c":["夕阳低欲尽，春浅色萧萧。","暝色催归牧，炊烟向晚樵。","疏星临水际，远火隔村桥。","黯黯柴门夜，栖鸦对寂寥。"]},{"t":"宿故济阳城","f":"五言律诗","c":["夜色萧条寺，天寒老病身。","空村惟有雪，远道更无人。","不寐依炉暖，多愁赖酒醇。","遥思双凤阙，雨露已先春。"]},{"t":"宿柳子观音寺","f":"七言律诗","c":["黄尘满道客衣穿，古寺荒凉暂息肩。","倦体收来便稳榻，汗颜濯去快寒泉。","野僧治饭挑蔬至，童子携茶对客煎。","夜久月高风铎响，木鱼呼觉五更眠。"]},{"t":"宿铜陵","f":"五言律诗","c":["山色日已远，问人归路长。","碧天凉夜阔，秋物雨馀荒。","人静路傍寺，鸟啼林下房。","铜陵竟何就，空死汉吴王。"]},{"t":"寂寂","f":"五言律诗","c":["寂寂秋日暮，辉辉檐影斜。","鸣虫隐衰蔓，晚蝶守馀花。","雨急荷翻叶，墙崩竹引芽。","不才非吏隐，鸡黍学山家。"]},{"t":"寄子由二首 其二","f":"七言律诗","c":["丈席他年闻至言，艰难不敢坠周旋。","文词老去真何益，道妙平生薄有缘。","人事眼前惟欲睡，丹经肘后更难传。","清秋一室林泉好，洒扫思为杖屦先。"]},{"t":"寄子由二首 其一","f":"七言律诗","c":["万里归来真得仙，七年瞻望漫悁悁。","安閒旧得还丹诀，著论新成古史编。","应接强颜聊复尔，是非袖手独超然。","门人白首侯芭在，眷恋微官愧昔贤。"]},{"t":"寄文刚求蟹","f":"五言律诗","c":["遥知涟水蟹，九月已经霜。","筐实黄金重，螯肥白玉香。","尘埃离故国，诗酒寄他乡。","苦乏西来使，何缘至洛阳。"]},{"t":"寄陈鼎","f":"七言律诗","c":["懒著青衫沉醉眠，近来沽酒困无钱。","常忧送乏邻僧米，何啻寒无坐客毡。","直道漫凭詹尹卜，浮生已付祖师禅。","祇应居士无醒日，知有渊明种秫田。"]},{"t":"寄陈履常二首 其二","f":"五言律诗","c":["故人犹念我，一笑向何人。","老去唯佛祖，州闲如隐沦。","残年河朔雪，近腊水乡春。","何日相逢笑，天边白发新。"]},{"t":"寄陈履常二首 其一","f":"五言律诗","c":["近闻彭泽令，旅饭寄招提。","杜老不厌赋，韦郎犹愧妻。","得州惭牧养，怀友负招携。","祇学新诗好，高吟独醉泥。"]},{"t":"寄荣子雍三首 其三","f":"七言律诗","c":["家家新酒滴新醅，残岁峥嵘春欲回。","霜野寂无新到雁，雪林寒有欲开梅。","关河路永双横辙，天地身閒一举杯。","酬答风光千点泪，怯将愁眼更登台。"]},{"t":"寄荣子雍三首 其二","f":"七言律诗","c":["苍苍老柏古南禅，袅袅修篁泮水湾。","此地笑谈惟我共，百年交友得君难。","已甘心向诗书老，会与身图云水閒。","年少功名须力致，看君朝佩日珊珊。"]},{"t":"寄荣子雍三首 其一","f":"七言律诗","c":["东风三月洛阳城，倾盖相逢气倍增。","看尽园花方信马，饮斜楼月更挑灯。","年光飘忽双驰毂，心事萧条一老僧。","酒病年来慵把笔，新文寄我苦凭陵。"]},{"t":"寄晁应之二首 其二","f":"七言律诗","c":["瑜珥瑶环豁眼明，碧梧翠竹照人清。","同车汲黯今难忮，挟弹潘郎旧有名。","自是风流袭家世，行看谈笑取公卿。","尘埃落魄谁如我，一事无成白发生。"]},{"t":"寄晁应之二首 其一","f":"七言律诗","c":["强读诗书叹白头，一官飘泊寄东周。","匏瓜有系身难去，人足无音境更幽。","晚接贤豪宽病思，老将文字写离忧。","相思一夕亲谈笑，梦断云山相对愁。"]},{"t":"寄滁州邵子发同年二首 其二","f":"七言律诗","c":["年来万事付禅宗，两鬓虽青心已翁。","欲借一廛希许子，更将五斗继无功。","春来行乐君应厌，老去裁诗我未工。","闻道琅邪山色好，为题新句寄清风。"]},{"t":"寄滁州邵子发同年二首 其一","f":"七言律诗","c":["夫子才豪官尚卑，穷城冷落有谁知。","莫嫌五斗纡高兴，且与青山赋好诗。","得失可齐陶令酒，功名休问蜀庄蓍。","三年流落甘忧患，一笑何当慰别离。"]},{"t":"寄蔡彦规兼谢惠酥梨二首 其二","f":"七言律诗","c":["洛川北岸锦屏西，竹树萧萧面翠微。","风月有情常似旧，山川信美不如归。","文章送老甘无用，鱼鸟从游久息机。","寄语长安倦游客，年来何事素书稀。"]},{"t":"寄蔡彦规兼谢惠酥梨二首 其一","f":"七言律诗","c":["自煮新酥笼旋开，秦霜犹污紫梨腮。","旧园歌舞唐宫废，灌顶醍醐佛国来。","寄我远传千里意，憾君不举百分杯。","西来新味饶乡思，淮蟹湖鱼几日回。"]},{"t":"探春有感二首 其一","f":"七言律诗","c":["出城但怪风光老，草色苍茫柳色深。","烟树远浮春缥缈，风光不动日阴沉。","芳郊未厌萦纡入，美酒何妨取次斟。","羸马青衫亦何事，一生空负野人心。"]},{"t":"探春有感二首 其二","f":"七言律诗","c":["柳萼蒙茸待放绵，樱桃新叶大如钱。","深春冷落花残后，寒食朦胧月淡天。","独坐每将诗作伴，遣愁安得酒如泉。","伤心千里休凝望，城外东风早满船。"]},{"t":"探梅有感","f":"七言律诗","c":["泽畔骚人未放回，江边又探腊前梅。","已知无木相先得，固使凌寒特地开。","杜老阁前劳赋咏，玉川窗外独惊猜。","试思感旧伤千里，可以临风举一杯。"]},{"t":"晚卧","f":"五言律诗","c":["日落烦暑退，秋晴河汉明。","微云映天白，纤月过林清。","独卧谁晤语，幽怀殊未平。","萧萧夜深冷，皓露满前楹。"]},{"t":"晚泊襄邑","f":"五言律诗","c":["月暗风林静，斗垂霜夜清。","疏灯隔树小，暗水历船鸣。","学字声形苦，紬书卜祝轻。","此身南北惯，随处有平生。"]},{"t":"晚凉行稻畦间","f":"五言律诗","c":["草木秋微警，山川夏已深。","迎风云卷幕，沉日水浮金。","晚鸟吟高木，霏烟暝远林。","杖藜循野泽，谈笑不行吟。"]},{"t":"晚晴","f":"五言律诗","c":["裛尘朝雨细，透竹夕阳明。","鸟雀知春去，牛羊散晚晴。","官闲端欲老，谋拙漫无成。","堂下清溪水，三逢蘋芷生。"]},{"t":"晚霁","f":"五言律诗","c":["山川收滞雨，乌鹊有和声。","半岭日犹照，一天云尽行。","人皆理墙壁，吾亦扫柴荆。","鹅鸭何多喜，渠流漾浅清。"]},{"t":"晨兴自篱西望东园新开花","f":"七言律诗","c":["东园本是吾家有，不到经旬亦可嗟。","步出寝门迎晓日，却从篱外望新花。","安禅岂问荒三径，阅古终须饱五车。","儿女相怜牢落甚，为翁浅盏酌流霞。"]},{"t":"晨起眺望","f":"七言律诗","c":["众木交阴园径荒，独寻细径上东冈。","山头秀插垂云处，江面平分浴日光。","沙际离离横水鸟，林端历历过风樯。","登临每到消忧处，不觉三年客异乡。"]},{"t":"望女几雪","f":"七言律诗","c":["万戟高攒女几晴，卷帘初见雪峥嵘。","光迎晓日峰千叠，气入阴风夜五更。","晴色北临秦甸白，寒威东抱洛阳清。","坐看沟壑承馀泽，付与春田次第耕。"]},{"t":"望龟山二首 其二","f":"七言律诗","c":["日落龟山山更清，原头啼鸟已春声。","可怜山近不能到，尽日与山相对行。","云里人家自来往，天边楼阁远分明。","白鸥不解游客意，惊起碧烟深处横。"]},{"t":"望龟山二首 其一","f":"七言律诗","c":["淮上风高寒日西，龟山岭下白云归。","游人苦憾日已晚，青山自与云为期。","轻舟渔子犯烟去，照水白鸥窥影飞。","人间不作逍遥客，老去尘埃空满衣。"]},{"t":"梅花","f":"七言律诗","c":["北风万木正苍苍，独占新春第一芳。","调鼎自期终有实，论花天下更无香。","月娥服御无非素，玉女精神不尚妆。","洛岸苦寒相见晚，晓来魂梦到江乡。"]},{"t":"梦中作","f":"五言律诗","c":["去路迎朝日，齐安客马西。","山行逢晓雨，客裤溅寒泥。","历险舆何健，冲风酒自携。","回头思旧止，陈迹已凄凄。"]},{"t":"淮上夜风","f":"五言律诗","c":["县郭初传柝，船窗已闭篷。","星低春野路，月淡夜淮风。","烟水东南阔，渔盐吴楚同。","久游谙里社，赊酒问邻翁。"]},{"t":"清洛","f":"五言律诗","c":["清洛西风急，遥知故国秋。","羁游成岁月，疏放合淹留。","地迥惊身老，山高更旅愁。","登临有词赋，不减在荆州。"]},{"t":"谒太昊祠","f":"七言律诗","c":["千里垂精帝道尊，神祠近正国西门。","风摇广殿松杉老，雨入修廊羽卫昏。","日落狐狸号草莽，年丰父老荐鸡豚。","旧游零落今谁在，尘壁苍茫字半存。"]},{"t":"谒告之楚出都晚泊","f":"五言律诗","c":["马迹不在眼，浪声初泊船。","苍禾荒霁泽，红树表霜川。","淮海南浮地，星辰北拱天。","东方聊一饱，楚稻不论钱。"]},{"t":"谒敬亭祠","f":"五言律诗","c":["古庙依山麓，开门石磴深。","疏林归鸣鸟，野殿宿寒阴。","落日鱼盐市，丰年箫鼓音。","我来无所祷，壁宇叹尘侵。"]},{"t":"野望","f":"五言律诗","c":["野宽秋望阁，浩荡雨初还。","寒树争标岭，归云各占山。","岁穷风物惨，地阔井闾闲。","饱食端无补，微官亦愧颜。"]},{"t":"雪斋","f":"五言律诗","c":["雪霁山堆黛，江晴日炫金。","风烟调柳态，冰雪彻梅心。","节物何妩媚，端居自滞淫。","无眠听云雁，稍有北归音。"]},{"t":"雪晴苦寒","f":"五言律诗","c":["水驿微茫外，樯乌苍莽中。","人愁暮村雪，雁急夜淮风。","大泽冻相接，群山深未穷。","萧条岁事晚，舟楫伴南翁。"]},{"t":"雪晴野望","f":"七言律诗","c":["萧萧空谷隐山云，渡水人归何处村。","樵径雪迷唐苑路，鸟声寒集汉祠门。","公堂吏散惟修竹，近岭林疏见饮猿。","客坐无毡君莫笑，陶潜亦有酒盈樽。"]},{"t":"鸿轩下有蔷薇予初至时生意盖仅存耳予为灌溉壅护今年春遂大盛仲春著花数百萼大几如芍药丰盛妍丽顷所未见也余有黄州之行酌酒赏别","f":"七言律诗","c":["堂下蔷薇亲灌溉，辛勤才见一春花。","时如转毂无停轨，客似飞鸿不定家。","一岁相邀伴寂寞，明年谁复对芳华。","驱车又向黄州去，风月相望一叹嗟。"]},{"t":"鹿仙山","f":"七言律诗","c":["溪清山秀隐神仙，乘鹿真人去几年。","天地壶中无客到，方书肘后有谁传。","秦皇采药迷蓬岛，汉武烧金得紫烟。","真境寥寥在何处，未容尘世妄攀缘。"]},{"t":"黄几道哀挽","f":"七言律诗","c":["风流正始久无声，颇复因公到后生。","千里族人分俸禄，百年乡党守题评。","青云脱屣乌台峻，白首含香画省清。","但得将军桃李在，宁须公相写铭旌。"]},{"t":"喜七兄疾愈二首 其二","f":"七言律诗","c":["南邻隐士龙虎鼎，东寺比丘坚密身。","欲知十室有信处，顾此两贤非世人。","战胜天魔初起定，宝成丹灶不妨贫。","何时共此閒居士，紫领长衫乐社神。"]},{"t":"喜七兄疾愈二首 其一","f":"七言律诗","c":["净名居士本非病，五禽先生能养身。","家人但讶少林观，乡里不知颜子贫。","身内固知精是药，人间惟有道通神。","喜闻渐离乌皮几，花气晴来欲逼人。"]},{"t":"喜雨赠潘邠老昆仲","f":"七言律诗","c":["卧闻飞雨响高堂，已觉翛翛短幌凉。","悔祸毕方收烈燄，知时田祖放新秧。","箪瓢幸免迁三径，谷麦行看粜万箱。","欲过东坡泥没脚，春馀烟柳正苍苍。"]},{"t":"寒食日同妇子辈东园小宴","f":"五言律诗","c":["寒食无与乐，携孥宴小园。","青春积雨霁，白日万花繁。","时节悲江国，穷愁泥酒尊。","故乡终在眼，乐不得重论。"]},{"t":"寒食日赠同饮者","f":"五言律诗","c":["春城风雨后，花落满人家。","宿润留芳草，晴辉上晓霞。","园林正寒食，樽酒对年华。","一笑相逢地，功名莫叹嗟。"]},{"t":"寒食前一日大雨不止","f":"七言律诗","c":["寒食穷愁叹陋邦，可怜终日雨淙淙。","不妨农亩连云稼，独惜园花脱锦杠。","最苦繁声欺屋漏，愿看霁色放春江。","明朝日出谁能料，已喜灯花照夜窗。"]},{"t":"寒食赠游客","f":"七言律诗","c":["阴阴画幕映雕栏，一缕微香宝篆残。","寒食园林三月近，落花风雨五更寒。","筝调宝柱弦初稳，酒满金壶饮未乾。","明日踏青郊外去，绿杨门巷系雕鞍。"]},{"t":"惠庄道中","f":"五言律诗","c":["山雨夜尘息，林霜晨气清。","荒城馀古木，破冢有新耕。","风俗通秦壤，川原抱洛京。","凭高时驻马，指点问山名。"]},{"t":"楮河","f":"五言律诗","c":["土壁裂如削，流泉漱雨间。","平沙放清浅，小石聚潺湲。","绝岸木斜出，隔桥人暮还。","凭鞍照毛发，羁旅易衰颜。"]},{"t":"游李氏园","f":"七言律诗","c":["堂下新年见草芽，惊心强起探年华。","柳呈雪后青苍干，梅破风前一两花。","绰约风光新物态，栽培园沼好生涯。","奔驰世路吾何有，一到林塘一叹嗟。"]},{"t":"登城二首 其二","f":"五言律诗","c":["绿野望不极，登临引兴长。","凭高延泽国，搔首对风光。","乍出莺贪柳，新归燕拣梁。","欣欣物华好，吾亦引清觞。"]},{"t":"登城二首 其一","f":"五言律诗","c":["楚望迷千里，孤城草树浓。","凭临点衣雨，容易落花风。","人事年年改，风光处处同。","未能忘出处，徙倚更书空。"]},{"t":"登城隍庙","f":"七言律诗","c":["灵祠孤绝压城头，下瞰清濠一曲流。","尽日风埃昏几席，有时箫鼓祭春秋。","西瞻太昊祠千树，北望封君土一丘。","旅客登临一长望，春心容易起骚愁。"]},{"t":"登城楼","f":"七言律诗","c":["沙雨初乾巾褐轻，独披衰蔓步高城。","天晴海上峰峦出，野暗人家灯火明。","归鸟各寻芳树去，夕阳微照远村耕。","登楼已恨荆州远，况复安仁白发生。"]},{"t":"登梦野亭","f":"五言律诗","c":["危亭瞰云梦，眼界浩无边。","秋见长江路，晴宽七泽天。","永怀哀郢赋，谁吊独醒贤。","俯仰悲千古，披襟尚飒然。"]},{"t":"登梦野亭怀旧","f":"七言律诗","c":["曾上高台望翠微，重来悲叹客难期。","章华苍莽寻无处，云梦逶迤寒更迟。","墨客多情曾痛饮，玉箫何处弄妍词。","请君点检当时事，只应朱颜非旧时。"]},{"t":"登楚望北楼","f":"七言律诗","c":["袅袅危楼百尺梯，秋风有客独攀跻。","路穷流水远更远，目断夕阳西复西。","帘卷似迎轻燕入，柳深时有暗蝉嘶。","洞庭落叶悲骚客，鹎鵊何劳著意啼。"]},{"t":"腊日四首 其四","f":"五言律诗","c":["园冷无人扫，门荒少客过。","槐高庭日少，竹近野风多。","霰雪催残腊，山川对浩歌。","飘蓬求季主，身世问如何。"]},{"t":"腊日四首 其三","f":"五言律诗","c":["日暖村村路，人家迭送迎。","婚姻须岁暮，酒醴幸年登。","箫鼓儿童集，衣裳妇女矜。","敢辞鸡黍费，农事及春兴。"]},{"t":"腊日四首 其二","f":"五言律诗","c":["腊云寒不动，残岁转萧条。","雪意千山静，天形一雁高。","冰留檐旧滴，红到杏新梢。","寂寞群儿笑，因文更解嘲。"]},{"t":"腊日四首 其一","f":"五言律诗","c":["今日何妍暖，青春亦不迟。","竹寻穿地笋，梅有犯寒枝。","云物晴无事，禽鱼暖自私。","芳菲行满眼，准拟报愁知。"]},{"t":"腊日晚步","f":"五言律诗","c":["喜觉阳和近，山园策杖行。","草应知地暖，柳欲向人轻。","残雪通春信，鸣禽报晓晴。","田闾未成计，搔首向春耕。"]},{"t":"腊月书事","f":"五言律诗","c":["荆棘连昌路，珠玑久化尘。","青山飞白鸟，野水渡行人。","寂寂繁华尽，悠悠草木春。","人间有兴废，何事独伤神。"]},{"t":"落日","f":"五言律诗","c":["落日西风急，空山客独惊。","夕云寒不动，秋水暮多声。","粟厌周人饭，莼思故国羹。","南飞有征雁，羡尔羽毛轻。"]},{"t":"落莫","f":"五言律诗","c":["岁晚苦落莫，独游情易伤。","晴溪沙漾碧，秋径叶铺黄。","幽菊开经雨，疏槐老奈霜。","闭门无俗客，摅散有林塘。"]},{"t":"赋得风示秬秸","f":"五言律诗","c":["寂寂含至韵，清风时见嘉。","无意偶自动，虽鸣终不哗。","宫悬奏编磬，朝佩响冲牙。","谁知无谱曲，举世好黄华。"]},{"t":"赋得瀑布","f":"五言律诗","c":["浩浩自太古，洋洋灌百川。","深将一源润，首出万峰巅。","晴浴岱宗日，香通华岳莲。","应有真仙子，挥榜上青天。"]},{"t":"道旁花","f":"五言律诗","c":["长夏百草秀，道旁多野花。","无名自红紫，有意占年华。","灼灼照流水，斑斑上古槎。","中原何日扫，将尔付泥沙。"]},{"t":"雁","f":"七言律诗","c":["知时避就物之难，千里萧萧振羽翰。","水国稻收朝食乏，海天霜重夜飞寒。","烟云秋去南山暖，风日春归朔野宽。","九万腾凌那可测，弋人矰缴漫多端。"]},{"t":"鲁直示其伯父祖善马鞍松隐斋诗次其韵","f":"五言律诗","c":["老鹤阅世久，归来毛骨寒。","田园半拱木，儿稚总胜冠。","爱客能酤酒，寻山不跨鞍。","平生未见面，试作阿咸看。"]},{"t":"感春二首 其二","f":"五言律诗","c":["为问闲茅客，穷愁何所欢。","焚香延昼睡，酤酒过春寒。","岁月颠毛换，古今行路难。","浮生付造物，留滞复何叹。"]},{"t":"感春二首 其一","f":"五言律诗","c":["不觉悠悠过，东风换故年。","青春消霰雪，白日满山川。","草绿飘梅地，江平去雁天。","故园桃李动，东望每依然。"]},{"t":"感遇二十五首 其七","f":"五言律诗","c":["太冬积严杀，布令兆微霜。","凄凄中园木，华采欻摧藏。","岂无孤芳者，佳菊独煌煌。","后彫虽尔德，曷补蕙兰伤。"]},{"t":"感遇二十五首 其六","f":"五言律诗","c":["群动同大块，冥冥含至精。","乾坤职覆载，日月互昏明。","蚊虫共一器，扰扰一时争。","推移付大化，终古一空名。"]},{"t":"慎思兄别墅在长沙白鹤山晋陶淡旧居事见本传今其居有大杉可十数围蕃茂特异世传淡藏丹其中用前韵谨赋","f":"七言律诗","c":["千年骑鹤老仙翁，固是山川秀气钟。","桃洞自宜无客到，吴门应合有人逢。","岩前旧隐孤杉老，壶里真游白鹿从。","近有蓬莱读书客，卜居偶占翠岚浓。"]},{"t":"新葺附火小阁","f":"五言律诗","c":["低牖仅障风，深炉宿火红。","忘怀荣辱外，无事寂寥中。","陨叶鸣寒瓦，飞霜皎夜空。","宵分未投宿，饥苦北来鸿。"]},{"t":"新霁","f":"七言律诗","c":["园门几日断行踪，新霁欣然路小通。","晚萼有情开宿雨，长林尽日舞高风。","后皇佳植宁无橘，鸾凤求栖亦有桐。","不惜园林娱逐客，此情谁似主人翁。"]},{"t":"暇日同孙毕二同舍游李氏园亭","f":"七言律诗","c":["荡荡东风散客心，出门驱马问园林。","花房待暖徐徐放，柳色随春旋旋深。","城郭远来无俗客，松篁深处有幽禽。","王公留壁题诗句，应许骚人尽日吟。"]},{"t":"暇日步西园感物辄为诗得七篇 其六 斑竹","f":"五言律诗","c":["重瞳陟方时，二妃盖老人。","安肯泣路傍，洒泪留丛筠。","颇疑葛陂化，点点留斑鳞。","慎勿脱水去，入世多埃尘。"]},{"t":"暇日步西园感物辄为诗得七篇 其一 酴醾","f":"五言律诗","c":["欲知此园古，请视酴醾苍。","孙枝已轮囷，走蔓龙蛇长。","春风一吹嘘，灼灼发奇光。","仙姝不可挹，顺风饮其香。"]},{"t":"福昌杂咏五首 其五","f":"七言律诗","c":["满目凄凉供客愁，断霞残照想沧洲。","风云萧瑟三川夜，星斗纵横万壑秋。","骑省衰迟空作赋，荆蛮留滞感登楼。","迷魂不待巫阳些，自有骚词继远游。"]},{"t":"福昌杂咏五首 其四","f":"七言律诗","c":["天倚冈峦翠万重，倚楼搔首更书空。","莓苔古屋荒秋雨，草木空山起夜风。","汉帛北来邀塞雁，楚招南望忆江枫。","尘埃流落悲生事，白发年来拟见攻。"]},{"t":"福昌杂咏五首 其三","f":"七言律诗","c":["乘云飞去不辞家，女几荒祠一径斜。","溪入乱云鸣佩玦，树蟠苍石老龙蛇。","夜寒玉镜悬清月，天碧霓衣曳彩霞。","陵谷易迁尘骨老，衰颜更欲服丹砂。"]},{"t":"福昌杂咏五首 其二","f":"七言律诗","c":["东望川原拱别都，汉唐冠盖已丘墟。","地横嵩少雄中夏，天险轘辕困万夫。","宫殿荒凉兴废恨，山河惨淡战争馀。","登临不见淮南道，只有风尘满客裾。"]},{"t":"福昌杂咏五首 其一","f":"七言律诗","c":["张翰飘然欲鲙鲈，周南久客意何如。","风悲故国荆榛地，日落空城雉兔墟。","明月捣衣闻洛杵，故人凭雁寄南书。","旅歌辛苦空弹铗，谁念朝盘未食鱼。"]},{"t":"福昌南望","f":"七言律诗","c":["朝市推迁不复还，暮云平野水潺潺。","山川寂寞繁华后，都邑萧条鱼鸟閒。","鹤柱千年无故老，仙棋一局换人间。","兴亡今古知何极，莫向雍琴妄惨颜。"]},{"t":"蒙恩除奉常有感","f":"五言律诗","c":["平生秉周礼，投老奉龙旗。","斥逐偶不死，归来敢恨迟。","门阑走宾客，行李饬妻儿。","又踏长安道，多惭鬓有丝。"]},{"t":"蓬瀛台二首 其二","f":"七言律诗","c":["苍烟乔木古台荒，下见蓬瀛六月凉。","过雨谁知非峡女，好风应是为襄王。","欢来未放流年老，事去却寻陈迹伤。","飘泊南游未能返，兴来回首独凄凉。"]},{"t":"蓬瀛台二首 其一","f":"七言律诗","c":["青冥不尽海茫茫，一望蓬瀛去路长。","秋信解凭诗客寄，春心长为楚魂伤。","萦回四望山如画，兴废千年木已苍。","直使台倾荆棘满，闻琴何用涕沾裳。"]},{"t":"遣兴次韵和晁应之四首 其三","f":"七言律诗","c":["夜泛孤舟清洛津，宓妃轻步若为亲。","清涵星汉光垂地，冷觉鱼龙气近人。","镜里悲秋双鬓发，马边随客两京尘。","愁心欲比东流水，滚滚无穷日日新。"]},{"t":"遣兴次韵和晁应之四首 其四","f":"七言律诗","c":["蓬门鸟雀啅黄昏，归径牛羊各有群。","水阔鱼龙阴后出，山空虎豹夜深闻。","西来客引秦川雨，南去秋连楚泽云。","唐汉废兴无处问，西风禾黍但丘坟。"]},{"t":"遣兴次韵和晁应之四首 其一","f":"七言律诗","c":["老去诗书倦讨论，一樽相对尚殷勤。","锻炉放荡狂中散，书阁萧条老子云。","要路交亲嗟隔阔，他乡耆旧饱知闻。","衰知多病头风甚，解寄新文独有君。"]},{"t":"遗兴次韵和晁应之四首 其一","f":"七言律诗","c":["日落村虚烟霭青，草根促织晚先鸣。","群山衮衮望中去，新月娟娟愁里生。","暗峡风云秋惨淡，高城河汉夜分明。","寄书故国还羞涩，白首萧条老病婴。"]},{"t":"遗兴次韵和晁应之四首 其二","f":"七言律诗","c":["洛阳宫殿锁埃尘，翠辇东还几度春。","双阙晓云连太室，九门晴影动天津。","地藏宝鼎宁无祲，龙护灵书固有神。","游豫此时期圣主，保釐从古仗元臣。"]},{"t":"遗兴次韵和晁应之四首 其四","f":"七言律诗","c":["露下风悲萤火流，周南羁客意悠悠。","山川老去三年泪，关塞秋来万里愁。","惯逐禽鱼谙异俗，每因霜月梦沧洲。","一抛砚井双蓬鬓，天畔诗成独倚楼。"]},{"t":"遣兴次韵和晁应之四首 其二","f":"七言律诗","c":["西风淅淅满征衣，天畔危亭面翠微。","云解映山常漠漠，叶知辞树亦依依。","苦饥黄鹄犹谋食，无事轻鸥得远飞。","落日秋风满江汉，杖藜三叹未能归。"]},{"t":"遗兴次韵和晁应之四首 其三","f":"七言律诗","c":["女几山前云雨收，五更星斗转西楼。","苍苍淡月关河晓，袅袅西风观阁秋。","独鹤有求时饮啄，孤云无事任沉浮。","可怜白发张公子，还望西山歌四愁。"]},{"t":"遣闷","f":"五言律诗","c":["为问庭前鹊，归期何太迟。","旧传能报喜，东去是何时。","黄叶西风急，幽花白露滋。","朝朝清洛水，坎坎只东驰。"]},{"t":"酬同年徐正夫司户时欲卜筑嵩洛间","f":"五言律诗","c":["少别老相见，无言空惘然。","功名属多病，诗酒乐衰年。","釜厌颜公粥，囊须赵壹钱。","归装何日办，嵩少好林泉。"]},{"t":"僦居小室之西有隙地不满十步新岁后稍暖每开户春色斗进戏名其户曰嬉春因为此诗","f":"七言律诗","c":["苍苍老桧已消雪，冉冉烟芜欲斗妍。","围得青春数亩地，断将平楚一方天。","春风入户如相觅，新月低窗最可怜。","老子婆娑便终日，一壶春酒与周旋。"]},{"t":"暮归","f":"五言律诗","c":["牛羊久已下，寂寂掩城扉。","水鹤鸣城堞，飞萤上戟衣。","夜凉江海近，天阔斗牛微。","何日招舟子，寒江北渡归。"]},{"t":"暮春","f":"七言律诗","c":["夜雨轻寒拂晓晴，牡丹开尽过清明。","庭前落絮谁家柳，叶里新声是处莺。","白发生来如有信，青春归去更无情。","便当种秫长成酒，远学陶潜过此生。"]},{"t":"暮春三首 其三","f":"五言律诗","c":["红点蔷薇架，绿深桃李蹊。","语莺知果熟，忙燕聚新泥。","节物有常态，羁游无定栖。","宁须说鹏鴳，物理固应齐。"]},{"t":"暮春三首 其二","f":"五言律诗","c":["应接非吾事，深幽兴有馀。","笋深鸣鸟下，花薄午风疏。","草浅见飞雉，溪清生细鱼。","端居亦多趣，不用席门车。"]},{"t":"暮春三首 其一","f":"五言律诗","c":["还将多病眼，冉冉对残春。","啼鸟日求侣，晚花如向人。","物情懒著意，杯酒最关身。","亦有功名志，吾生付大钧。"]},{"t":"暮春书事四首 其四","f":"五言律诗","c":["林花飞已久，芳草雨馀长。","人静槐庭午，帘斜竹院凉。","沾泥新笋白，封蜡煮醪香。","莫厌残春醉，流莺劝举觞。"]},{"t":"暮春书事四首 其三","f":"五言律诗","c":["冉冉春将老，迟迟日正长。","露花低晓架，风絮集闲堂。","水暖荷争出，杯寒杏已尝。","芳菲值穷谷，嗟负少年狂。"]},{"t":"暮春书事四首 其二","f":"五言律诗","c":["漠漠山云合，檐风透薄帷。","柳藏阴后絮，樱压雨中枝。","坐暖晨杯罢，香浓午睡时。","薄寒犹故在，再取紫貂披。"]},{"t":"暮春书事四首 其一","f":"五言律诗","c":["冉冉春将老，悠悠昼掩关。","鸠鸣高柳暗，雨细广庭闲。","尘榻谈无客，风帘望有山。","衔泥新燕子，一一及时还。"]},{"t":"暮春赠陈器之","f":"七言律诗","c":["牡丹开过解鞦韆，鹎鵊鸣时三月天。","尽日好风吹絮雪，一池春水泛莲钱。","溪边蒲笋供朝饭，堂上图书伴昼眠。","端坐穷城何所得，只收风月入新篇。"]},{"t":"蔡河涨二首 其二","f":"五言律诗","c":["浑浑虽未已，浩浩竟东归。","阔处长天近，澄边一鸟飞。","西风疏苇乱，斜日远村微。","淹泊从吾道，扁舟伴钓矶。"]},{"t":"蔡河涨二首 其一","f":"五言律诗","c":["长河秋雨涨，极目漫难分。","潢潦虽无自，龟鱼恐有神。","天宽垂鉴影，风细起龙鳞。","老去扁舟兴，临流欲问津。"]},{"t":"潘大临莲池二首 其二","f":"七言律诗","c":["年年酷暑轸皇慈，恩诏犹矜庶狱累。","白首坐曹真有罪，清风高枕叹无时。","乘轩敢望终如鹤，用智从前不及葵。","他日东门驱匹马，故应难忘习家池。"]},{"t":"潘大临莲池二首 其一","f":"七言律诗","c":["避暑人人得自怡，坐曹最苦剧囚累。","江边金石焦流日，堂上糟浆酷烈时。","一酌甘寒烦素绠，终朝挥拂倦蒲葵。","谁知颜巷箪瓢外，更有秋风菡萏池。"]},{"t":"潘鲠奉议挽词","f":"五言律诗","c":["廉退辞荣早，清贫卜吉迟。","买山新兆域，从窆旧书诗。","松菊留三径，箪瓢遗两儿。","升堂旧宾客，执绋涕交颐。"]},{"t":"醉宿慈氏院晨起","f":"七言律诗","c":["痛饮淋漓半夜醒，披衣坐待晓窗明。","风松一夕清无限，垆火三更暖有情。","孤阁鸣钟天黯惨，寒山戴雪晚峥嵘。","年来渐向深杯怯，强学刘伶欲解酲。"]},{"t":"题朱氏园","f":"七言律诗","c":["东风邀客入芳菲，夹径吹香李万枝。","啼鸟远闻知昼静，好花相续得春迟。","连樯东去淮天阔，绿野南环楚泽卑。","客至会须留醉墨，主人留榜待新诗。"]},{"t":"题庐阜官厅壁","f":"五言律诗","c":["平生山水兴，今夜宿东林。","落日楼殿影，西风钟梵音。","云横山阁迥，雨过虎溪深。","脚力犹堪在，他年当重寻。"]},{"t":"题李方叔文卷末","f":"七言律诗","c":["他日东坡誉子文，澜翻健笔欲凌云。","决科正尔真馀事，射策如何但报闻。","诡御获禽虽可鄙，挽弓射叶亦徒勤。","莫辞更拟相如作，寂寞思玄未放君。"]},{"t":"题洪泽亭","f":"七言律诗","c":["三年淮海飘萍客，今日亭边再舣舟。","人似垂杨随日老，事如流水几时休。","閒于万事常难得，仕以为生最拙谋。","此世定知犹几至，遑遑奔走欲何求。"]},{"t":"题倪敦复北轩","f":"五言律诗","c":["潇洒倪夫子，新城面北堂。","庭前无狱讼，客至有壶觞。","昼静尘埃绝，春馀花草香。","为君题素壁，容我醉中狂。"]},{"t":"题斋壁","f":"七言律诗","c":["松庭日午听啼莺，帘外人稀睡老铃。","已叹近秋添白发，更因多病读黄庭。","江鱼未上烹难致，吴酒空斟醉易醒。","好住安心莫惆怅，此身天地一浮萍。"]},{"t":"题堂下桐","f":"七言律诗","c":["零落当轩两树桐，秋来相伴一衰翁。","寒枝向月空馀影，陨叶知时不待风。","故国山川天黯淡，美人音信雁西东。","岁华节物俱寥落，满眼牢愁赖酒攻。"]},{"t":"题淮阴孙簿壁","f":"七言律诗","c":["荒凉官舍对淮流，樽酒相逢为少留。","夹道老椿鸦哺子，隔墙荒草牧呼牛。","渡头人散前村市，天际帆来何处舟。","自古诗人最多感，新篇应解写骚愁。"]},{"t":"题楚州圣井并赠主僧","f":"五言律诗","c":["古佛胜妙力，一泓常湛然。","祷祈供众欲，守护赖师贤。","清碧晨斋罢，秋登宝供前。","自怜多病质，时许挹清泉。"]},{"t":"赠人三首次韵道卿 其三","f":"七言律诗","c":["可是相逢意便深，为郎巧笑不须金。","门前一尺春风髻，窗外三更夜雨衾。","别燕从教灯见泪，夜窗惟有月知心。","东西芳草浑相似，欲望高城何处寻。"]},{"t":"赠人三首次韵道卿 其二","f":"七言律诗","c":["醉里纷纷散别筵，醒来客枕一灯前。","黄茅野岸三更月，春水长亭十里船。","一点泪凭谁寄与，十年香在恨依然。","空疑窗外梅花发，珠箔青楼若个边。"]},{"t":"赠人三首次韵道卿 其一","f":"七言律诗","c":["未必蝤蛴如素领，故应新月学蛾眉。","引成密约因言笑，试得真情是别离。","樽酒且倾寒琥珀，泪妆更看薄胭脂。","北城月落乌啼后，便是孤舟肠断时。"]},{"t":"赠无咎","f":"七言古诗","c":["快哉亭下水连城，落日断霞相映明。","人在捲帘尊俎里，诗从挥麈笑谈生。","扬州何逊风流在，江夏黄香句法清。","□□□□□□□，□□□□□□□。"]},{"t":"赠别何道士","f":"七言律诗","c":["疏散多违久自知，形骸况复病先衰。","全身幸免诛三献，避世何劳赋五噫。","闻说永嘉饶水石，便思轻帆向天涯。","却嗟病翮伤摧甚，孤鹤高飞不得随。"]}]};